-- 为高一、高二、高三全部正式技能补齐“梗概—展开讲解—就地示范—图像记忆—自查”。
-- 内容为原创讲解；本迁移只更新复习系统知识卡，不修改独立小测系统。

update public.chem_knowledge_cards
set structured_content = structured_content
  || $class_patch${"version":2,"overview":["先按“样品含几种物质”分成纯净物和混合物；这是整棵树的第一刀。","纯净物再按元素种类分成单质和化合物；混合物不能直接进入这条分支。","无机化合物继续分为氧化物、酸、碱、盐；每一类都有独立判断标准。","酸的元数、强弱、含氧与否可同时存在；碱的元数、强弱、溶解性也可交叉。","电解质/非电解质是只针对化合物的另一条横向分类线，不能用“能否导电”直接替代。"],"scopeNote":"本卡按苏教版必修内容和福建高中范围整理；分类结论始终以同一判断标准为前提。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$class_patch$::jsonb
  || jsonb_build_object(
    'rootTree',
    coalesce(structured_content->'rootTree', '{}'::jsonb)
      || jsonb_build_object(
        'examples', jsonb_build_array('空气：多种物质组成，走混合物分支', '液氯Cl₂：一种物质组成，走纯净物分支'),
        'visualSteps', jsonb_build_array('物质', '数物质种类', '一种→纯净物', '多种→混合物')
      )
  ),
  review_status = 'approved',
  updated_at = now()
where id = 'KC_H1_CLASSIFY' and skill_id = 'H1_CLASSIFY';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H1_ELECTROLYTE_INTRO","version":2,"intro":"假设“电解质”三个字已经完全忘记：先记住它不是“会不会导电”的同义词，而是对化合物的一种分类。判断时要依次检查研究对象、产生离子的方式和导电状态。","overview":["第一道门：电解质和非电解质只研究化合物，金属、石墨等单质不参加这组分类。","第二道门：看物质本身在水溶液中或熔融状态能否产生自由移动的离子。","导电是现象，自身电离是原因；不能只凭“某溶液能导电”下结论。","固态离子化合物有离子却常不导电，因为离子被固定；熔融或溶于水后离子能移动。"],"sections":[{"title":"先把四个容易混淆的词分开","summary":"物质、溶液、离子和导电现象不是同一层面的概念。","items":[{"label":"化合物","rule":"由两种或两种以上元素组成的纯净物。只有化合物才继续判断电解质或非电解质。","examples":["NaCl、HCl、NaOH、蔗糖都是化合物。","【示范：先分清Cu、NaCl和NaCl溶液】Cu是单质，虽能导电却不参加电解质分类；NaCl是化合物，在熔融或水溶液中产生Na⁺、Cl⁻，是电解质；NaCl溶液由水和NaCl组成，是混合物。"],"caution":"Cu、O₂、石墨属于单质，不说它们是电解质或非电解质。","visualSteps":["化合物","研究对象","是否化合物","自身产生离子","现象与本质"]},{"label":"电离","rule":"电解质溶于水或受热熔化时形成自由移动离子的过程；不是通电后才发生，也不是把分子“切碎”。","examples":["NaCl熔融后形成Na⁺和Cl⁻；HCl进入水中形成水合离子。","【示范：先分清Cu、NaCl和NaCl溶液】Cu是单质，虽能导电却不参加电解质分类；NaCl是化合物，在熔融或水溶液中产生Na⁺、Cl⁻，是电解质；NaCl溶液由水和NaCl组成，是混合物。"],"visualSteps":["电离","研究对象","是否化合物","自身产生离子","现象与本质"]},{"label":"导电","rule":"带电粒子发生定向移动形成电流。金属靠自由电子导电，电解质溶液或熔融电解质靠离子导电。","examples":["铜丝靠电子导电；NaCl溶液靠Na⁺、Cl⁻导电。","【示范：先分清Cu、NaCl和NaCl溶液】Cu是单质，虽能导电却不参加电解质分类；NaCl是化合物，在熔融或水溶液中产生Na⁺、Cl⁻，是电解质；NaCl溶液由水和NaCl组成，是混合物。"],"visualSteps":["导电","研究对象","是否化合物","自身产生离子","现象与本质"]}]},{"title":"电解质与非电解质的判断门","summary":"按固定顺序判断，任何一步不满足就停止。","items":[{"label":"步骤1：先问是不是化合物","rule":"是化合物才进入下一步；单质和混合物都不属于这两个类别。","examples":["稀盐酸是混合物，不能说“稀盐酸是电解质”；应说HCl是电解质。","【示范：五种物质过三道门】依次判断NaCl、HCl、蔗糖、Cu、盐酸：先排除单质Cu和混合物盐酸；NaCl、HCl能自身形成离子，判电解质；蔗糖以分子存在，判非电解质。"],"visualSteps":["步骤1：先问是不是化合物","化合物门","水溶液或熔融","离子来自物质本身","作出分类"]},{"label":"步骤2：是否由物质本身产生离子","rule":"在水溶液中或熔融状态，若该化合物本身能形成离子，就是电解质。","examples":["酸、碱、盐通常属于电解质；许多金属氧化物在熔融状态能导电，也属于电解质。","【示范：五种物质过三道门】依次判断NaCl、HCl、蔗糖、Cu、盐酸：先排除单质Cu和混合物盐酸；NaCl、HCl能自身形成离子，判电解质；蔗糖以分子存在，判非电解质。"],"visualSteps":["步骤2：是否由物质本身产生离子","化合物门","水溶液或熔融","离子来自物质本身","作出分类"]},{"label":"步骤3：两种状态都不能自身产生离子","rule":"化合物在水溶液中和熔融状态都不能自身电离，判为非电解质。","examples":["蔗糖、乙醇等在水中主要以分子存在。","【示范：五种物质过三道门】依次判断NaCl、HCl、蔗糖、Cu、盐酸：先排除单质Cu和混合物盐酸；NaCl、HCl能自身形成离子，判电解质；蔗糖以分子存在，判非电解质。"],"visualSteps":["步骤3：两种状态都不能自身产生离子","化合物门","水溶液或熔融","离子来自物质本身","作出分类"]}]},{"title":"为什么“溶液导电”不能一票定结论","summary":"先追问溶液里的离子是谁产生的。","items":[{"label":"物质与水反应后导电","rule":"某些化合物本身不电离，却和水反应生成电解质，使溶液导电；导电原因来自生成物。","examples":["CO₂溶于水生成少量H₂CO₃，溶液可导电，但CO₂本身判为非电解质。","NH₃与水作用形成少量NH₄⁺和OH⁻，NH₃本身通常判为非电解质。","【示范：CO₂、CaCO₃和浓度的三个坑】CO₂与水反应后溶液导电，离子主要来自生成的H₂CO₃，故CO₂是非电解质；CaCO₃虽难溶，溶解部分形成离子，仍是电解质；强弱只看电离程度，不看浓度和导电灯泡亮度。"],"visualSteps":["物质与水反应后导电","追溯离子来源","难溶不等于非电解质","强弱不等于浓稀","分别下结论"]},{"label":"难溶不等于非电解质","rule":"能溶解的部分若能形成离子，仍是电解质；分类看性质，不看溶解量多少。","examples":["CaCO₃、BaSO₄虽难溶，仍属于电解质。","【示范：CO₂、CaCO₃和浓度的三个坑】CO₂与水反应后溶液导电，离子主要来自生成的H₂CO₃，故CO₂是非电解质；CaCO₃虽难溶，溶解部分形成离子，仍是电解质；强弱只看电离程度，不看浓度和导电灯泡亮度。"],"visualSteps":["难溶不等于非电解质","追溯离子来源","难溶不等于非电解质","强弱不等于浓稀","分别下结论"]},{"label":"强弱不等于导电强弱","rule":"强弱电解质看电离程度；溶液导电能力还受浓度、离子电荷和迁移能力影响。","examples":["很稀的强电解质溶液可能比浓度较大的弱电解质溶液导电弱。","【示范：CO₂、CaCO₃和浓度的三个坑】CO₂与水反应后溶液导电，离子主要来自生成的H₂CO₃，故CO₂是非电解质；CaCO₃虽难溶，溶解部分形成离子，仍是电解质；强弱只看电离程度，不看浓度和导电灯泡亮度。"],"visualSteps":["强弱不等于导电强弱","追溯离子来源","难溶不等于非电解质","强弱不等于浓稀","分别下结论"]}]},{"title":"从微观图像理解三种状态","summary":"有没有离子与离子能不能移动要分开。","items":[{"label":"固态NaCl","rule":"晶体中有Na⁺和Cl⁻，但离子只能在固定位置附近振动，不能自由移动，通常不导电。","examples":["【示范：同一NaCl的三幅微观图】固态时Na⁺、Cl⁻被晶格固定而不导电；熔融时晶格破坏，离子可移动；水溶液中离子被水合并分散，可在电场中定向移动。"],"visualSteps":["固态NaCl","固态固定","熔融可动","水合分散","离子定向移动"]},{"label":"熔融NaCl","rule":"晶格被破坏，Na⁺和Cl⁻可以移动；接通电场后分别向相反方向迁移，能够导电。","examples":["【示范：同一NaCl的三幅微观图】固态时Na⁺、Cl⁻被晶格固定而不导电；熔融时晶格破坏，离子可移动；水溶液中离子被水合并分散，可在电场中定向移动。"],"visualSteps":["熔融NaCl","固态固定","熔融可动","水合分散","离子定向移动"]},{"label":"NaCl水溶液","rule":"水分子把离子分散并水合，离子可自由移动，能够导电。","caution":"不要把溶液中的粒子写成“NaCl分子”。","examples":["【示范：同一NaCl的三幅微观图】固态时Na⁺、Cl⁻被晶格固定而不导电；熔融时晶格破坏，离子可移动；水溶液中离子被水合并分散，可在电场中定向移动。"],"visualSteps":["NaCl水溶液","固态固定","熔融可动","水合分散","离子定向移动"]}]}],"workedExamples":[{"substance":"先分清Cu、NaCl和NaCl溶液","path":"Cu是单质，虽能导电却不参加电解质分类；NaCl是化合物，在熔融或水溶液中产生Na⁺、Cl⁻，是电解质；NaCl溶液由水和NaCl组成，是混合物。","labels":["研究对象","是否化合物","自身产生离子","现象与本质"]},{"substance":"五种物质过三道门","path":"依次判断NaCl、HCl、蔗糖、Cu、盐酸：先排除单质Cu和混合物盐酸；NaCl、HCl能自身形成离子，判电解质；蔗糖以分子存在，判非电解质。","labels":["化合物门","水溶液或熔融","离子来自物质本身","作出分类"]},{"substance":"CO₂、CaCO₃和浓度的三个坑","path":"CO₂与水反应后溶液导电，离子主要来自生成的H₂CO₃，故CO₂是非电解质；CaCO₃虽难溶，溶解部分形成离子，仍是电解质；强弱只看电离程度，不看浓度和导电灯泡亮度。","labels":["追溯离子来源","难溶不等于非电解质","强弱不等于浓稀","分别下结论"]},{"substance":"同一NaCl的三幅微观图","path":"固态时Na⁺、Cl⁻被晶格固定而不导电；熔融时晶格破坏，离子可移动；水溶液中离子被水合并分散，可在电场中定向移动。","labels":["固态固定","熔融可动","水合分散","离子定向移动"]},{"substance":"铜、NaCl、蔗糖三连判","path":"先看研究对象：铜是单质，退出分类；NaCl和蔗糖是化合物。再看自身产生离子：NaCl可以，判电解质；蔗糖不可以，判非电解质。","labels":["对象门","自身电离门","不能只看导电"]},{"substance":"CO₂水溶液为什么能导电","path":"CO₂本身不直接电离；它与水反应生成H₂CO₃，H₂CO₃部分电离产生离子。因此“溶液能导电”不等于“CO₂是电解质”。","labels":["追溯离子来源","CO₂是非电解质","H₂CO₃是电解质"]}],"checkpoints":["我能先判断研究对象是否为化合物。","我能解释固态NaCl不导电而熔融NaCl导电。","我不会把铜、盐酸溶液归入电解质。","我能用“离子来自谁”解释CO₂、NH₃的边界。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_ELECTROLYTE_INTRO' and skill_id = 'H1_ELECTROLYTE_INTRO';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H1_PERIODIC","version":2,"intro":"元素周期律不是一串需要硬背的箭头。先把“原子结构—周期表位置—元素性质”接成因果链，再在同周期或同主族的前提下使用递变规律。","overview":["原子序数=核电荷数=质子数；中性原子中还等于核外电子数。","周期序数看电子层数，主族序数通常看最外层电子数。","同周期从左到右：有效核吸引总体增强，半径总体减小，金属性减弱、非金属性增强。","同主族从上到下：电子层增多，半径增大，金属性增强、非金属性减弱。","比较结论必须用事实落地：与水/酸反应、氢化物稳定性、最高价氧化物对应水化物酸碱性等。"],"sections":[{"title":"从原子结构重新起步","summary":"周期律的根在核外电子排布，而不是表格位置本身。","items":[{"label":"原子核与核外电子","rule":"原子核含质子和中子；质子数决定元素种类。质量数A=质子数Z+中子数N。中性原子的电子数等于质子数。","examples":["²³₁₁Na含11个质子、12个中子和11个电子。","【示范：²³₁₁Na的结构账】Na有11个质子、12个中子；中性原子有11个电子，分层为2、8、1。失去最外层1个电子形成Na⁺，质子数不变，所以仍是钠元素。"],"visualSteps":["原子核与核外电子","核内质子","质量数减质子数","电子分层","得失电子"]},{"label":"电子层与最外层电子","rule":"高一阶段先用分层排布理解：电子优先从内层排起；最外层电子直接影响主要化学性质。","examples":["Na为2、8、1，易失去1个电子；Cl为2、8、7，易得到1个电子。","【示范：²³₁₁Na的结构账】Na有11个质子、12个中子；中性原子有11个电子，分层为2、8、1。失去最外层1个电子形成Na⁺，质子数不变，所以仍是钠元素。"],"visualSteps":["电子层与最外层电子","核内质子","质量数减质子数","电子分层","得失电子"]},{"label":"原子与离子","rule":"原子失电子形成阳离子，得电子形成阴离子；质子数不变，因此元素种类不变。","examples":["Na→Na⁺+e⁻；Cl+e⁻→Cl⁻。","【示范：²³₁₁Na的结构账】Na有11个质子、12个中子；中性原子有11个电子，分层为2、8、1。失去最外层1个电子形成Na⁺，质子数不变，所以仍是钠元素。"],"visualSteps":["原子与离子","核内质子","质量数减质子数","电子分层","得失电子"]}]},{"title":"结构怎样定位到周期表","summary":"先周期、再主族，最后用性质交叉检验。","items":[{"label":"判断周期","rule":"基态主族原子的电子层数等于周期序数。","examples":["电子排布2、8、2有3个电子层，位于第3周期。","【示范：由2、8、7定位Cl】3个电子层确定第3周期，7个最外层电子确定第ⅦA族；易得1e⁻形成Cl⁻。再用最高价、最低负价和氢化物等信息交叉核对。"],"visualSteps":["判断周期","数电子层","数最外层电子","定周期和主族","性质复核"]},{"label":"判断主族","rule":"主族元素的最外层电子数通常等于主族序数；He是特殊稳定结构。","examples":["2、8、2对应第ⅡA族；2、8、7对应第ⅦA族。","【示范：由2、8、7定位Cl】3个电子层确定第3周期，7个最外层电子确定第ⅦA族；易得1e⁻形成Cl⁻。再用最高价、最低负价和氢化物等信息交叉核对。"],"caution":"不要把过渡元素直接套用“最外层电子数=族序数”。","visualSteps":["判断主族","数电子层","数最外层电子","定周期和主族","性质复核"]},{"label":"位置、结构、性质互推","rule":"题目可能给位置推结构，也可能给离子结构、化合价或氢化物反推位置。每得到一个结论，都用另一条条件核对。","examples":["最高正价、最低负价、常见离子电荷可作为交叉证据。","【示范：由2、8、7定位Cl】3个电子层确定第3周期，7个最外层电子确定第ⅦA族；易得1e⁻形成Cl⁻。再用最高价、最低负价和氢化物等信息交叉核对。"],"caution":"O、F在常见最高正价规律中有例外，高一比较时必须看具体范围。","visualSteps":["位置、结构、性质互推","数电子层","数最外层电子","定周期和主族","性质复核"]}]},{"title":"同周期为什么这样变化","summary":"电子层数相同，核电荷逐步增加是主要矛盾。","items":[{"label":"原子半径总体减小","rule":"新增电子仍进入同一电子层，而质子数增加使核对电子的吸引增强，所以半径总体减小。","examples":["第3周期通常Na>Mg>Al>Si>P>S>Cl。","【示范：第3周期Na到Cl】电子层数相同而核电荷逐渐增大，核吸引增强，原子半径总体减小；失电子变难、得电子倾向增强，所以金属性减弱、非金属性增强。"],"visualSteps":["原子半径总体减小","同一周期","核电荷增加","半径总体减小","金属性到非金属性"]},{"label":"金属性减弱、非金属性增强","rule":"半径减小、核吸引增强后，原子失电子越来越难、得电子能力总体增强。","examples":["Na与冷水剧烈反应，Mg与冷水反应较慢；Cl的非金属性强于S。","【示范：第3周期Na到Cl】电子层数相同而核电荷逐渐增大，核吸引增强，原子半径总体减小；失电子变难、得电子倾向增强，所以金属性减弱、非金属性增强。"],"visualSteps":["金属性减弱、非金属性增强","同一周期","核电荷增加","半径总体减小","金属性到非金属性"]},{"label":"化合物性质递变","rule":"最高价氧化物对应水化物通常由强碱性逐渐过渡到两性、再到酸性增强；气态氢化物稳定性总体增强。","examples":["NaOH强碱，Al(OH)₃两性，HClO₄酸性很强。","【示范：第3周期Na到Cl】电子层数相同而核电荷逐渐增大，核吸引增强，原子半径总体减小；失电子变难、得电子倾向增强，所以金属性减弱、非金属性增强。"],"caution":"这里比较的是对应的最高价含氧化合物体系，不是任意氧化物。","visualSteps":["化合物性质递变","同一周期","核电荷增加","半径总体减小","金属性到非金属性"]}]},{"title":"同主族为什么这样变化","summary":"从上到下电子层增加，距离和屏蔽效应成为主要矛盾。","items":[{"label":"原子半径增大","rule":"每往下一周期多一个电子层，最外层电子离核更远，内层电子屏蔽更强。","examples":["【示范：卤素从F到I】从F到I电子层依次增加，半径增大、屏蔽增强，得电子能力总体减弱；因此非金属性和单质氧化性总体F₂>Cl₂>Br₂>I₂，而同族因最外层7e⁻仍有相似性。"],"visualSteps":["原子半径增大","电子层增加","半径增大","非金属性减弱","相似中有递变"]},{"label":"金属性增强、非金属性减弱","rule":"核对最外层电子的有效吸引减弱，失电子更容易、得电子能力总体减弱。","examples":["碱金属从Li到Cs金属性增强；卤素从F到I非金属性减弱。","【示范：卤素从F到I】从F到I电子层依次增加，半径增大、屏蔽增强，得电子能力总体减弱；因此非金属性和单质氧化性总体F₂>Cl₂>Br₂>I₂，而同族因最外层7e⁻仍有相似性。"],"visualSteps":["金属性增强、非金属性减弱","电子层增加","半径增大","非金属性减弱","相似中有递变"]},{"label":"相似性与递变性并存","rule":"同主族因最外层电子数相同而化学性质相似，又因电子层数不同而强弱递变。","examples":["卤素单质都能表现氧化性，但总体F₂>Cl₂>Br₂>I₂。","【示范：卤素从F到I】从F到I电子层依次增加，半径增大、屏蔽增强，得电子能力总体减弱；因此非金属性和单质氧化性总体F₂>Cl₂>Br₂>I₂，而同族因最外层7e⁻仍有相似性。"],"visualSteps":["相似性与递变性并存","电子层增加","半径增大","非金属性减弱","相似中有递变"]}]},{"title":"考试比较的五步法","summary":"先限定对象，再选规律，再用事实证明。","items":[{"label":"第1步：定位","rule":"写出元素在同周期、同主族还是跨区比较；不先定位就不能机械套箭头。","examples":["【示范：比较Na、Mg、Al并给证据】三者同周期，结构原因推出金属性Na>Mg>Al；再用与水或酸反应的难易、最高价氧化物对应水化物的碱性变化作证据。比较同电子离子时则改用“核电荷越大，半径越小”。"],"visualSteps":["第1步：定位","先定位对象","说结构原因","选择对应指标","用事实验证"]},{"label":"第2步：找结构原因","rule":"比较电子层数、核电荷和最外层电子，不只背结论。","examples":["【示范：比较Na、Mg、Al并给证据】三者同周期，结构原因推出金属性Na>Mg>Al；再用与水或酸反应的难易、最高价氧化物对应水化物的碱性变化作证据。比较同电子离子时则改用“核电荷越大，半径越小”。"],"visualSteps":["第2步：找结构原因","先定位对象","说结构原因","选择对应指标","用事实验证"]},{"label":"第3步：选择指标","rule":"题目问金属性、非金属性、半径、化合物酸碱性还是反应强弱，证据不能混用。","examples":["【示范：比较Na、Mg、Al并给证据】三者同周期，结构原因推出金属性Na>Mg>Al；再用与水或酸反应的难易、最高价氧化物对应水化物的碱性变化作证据。比较同电子离子时则改用“核电荷越大，半径越小”。"],"visualSteps":["第3步：选择指标","先定位对象","说结构原因","选择对应指标","用事实验证"]},{"label":"第4—5步：用事实验证并查例外","rule":"用可观察反应或稳定性支持结论，再检查离子、同电子微粒、O/F等特殊对象。","examples":["同电子离子：核电荷越大，半径越小。","【示范：比较Na、Mg、Al并给证据】三者同周期，结构原因推出金属性Na>Mg>Al；再用与水或酸反应的难易、最高价氧化物对应水化物的碱性变化作证据。比较同电子离子时则改用“核电荷越大，半径越小”。"],"visualSteps":["第4—5步：用事实验证并查例外","先定位对象","说结构原因","选择对应指标","用事实验证"]}]}],"workedExamples":[{"substance":"²³₁₁Na的结构账","path":"Na有11个质子、12个中子；中性原子有11个电子，分层为2、8、1。失去最外层1个电子形成Na⁺，质子数不变，所以仍是钠元素。","labels":["核内质子","质量数减质子数","电子分层","得失电子"]},{"substance":"由2、8、7定位Cl","path":"3个电子层确定第3周期，7个最外层电子确定第ⅦA族；易得1e⁻形成Cl⁻。再用最高价、最低负价和氢化物等信息交叉核对。","labels":["数电子层","数最外层电子","定周期和主族","性质复核"]},{"substance":"第3周期Na到Cl","path":"电子层数相同而核电荷逐渐增大，核吸引增强，原子半径总体减小；失电子变难、得电子倾向增强，所以金属性减弱、非金属性增强。","labels":["同一周期","核电荷增加","半径总体减小","金属性到非金属性"]},{"substance":"卤素从F到I","path":"从F到I电子层依次增加，半径增大、屏蔽增强，得电子能力总体减弱；因此非金属性和单质氧化性总体F₂>Cl₂>Br₂>I₂，而同族因最外层7e⁻仍有相似性。","labels":["电子层增加","半径增大","非金属性减弱","相似中有递变"]},{"substance":"比较Na、Mg、Al并给证据","path":"三者同周期，结构原因推出金属性Na>Mg>Al；再用与水或酸反应的难易、最高价氧化物对应水化物的碱性变化作证据。比较同电子离子时则改用“核电荷越大，半径越小”。","labels":["先定位对象","说结构原因","选择对应指标","用事实验证"]},{"substance":"由2、8、7推出Cl","path":"3个电子层→第3周期；最外层7个电子→第ⅦA族；易得1e⁻→常形成Cl⁻；与同周期S相比，核吸引更强、非金属性更强。","labels":["结构","位置","性质","事实验证"]},{"substance":"比较Na、Mg、Al金属性","path":"三者同在第3周期，电子层数相同，核电荷依次增大，半径总体减小，失电子能力减弱，所以金属性Na>Mg>Al。可用与水或酸反应的难易作证据。","labels":["先限定同周期","解释而非只背箭头","证据必须匹配"]}],"checkpoints":["我能由电子层数和最外层电子数定位主族元素。","我能解释同周期半径总体减小的原因。","我能区分“规律结论”和“证明结论的实验事实”。","我比较离子半径时会先看电子层和电子数。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_PERIODIC' and skill_id = 'H1_PERIODIC';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H1_REDOX","version":2,"intro":"氧化还原看起来名词很多，其实所有判断都从同一件事出发：反应前后有没有元素化合价变化。化合价变化只是表面证据，电子转移才是本质。","overview":["有元素化合价升降，就是氧化还原反应；没有升降就不是。","升价=失电子=被氧化=发生氧化反应；对应物质是还原剂。","降价=得电子=被还原=发生还原反应；对应物质是氧化剂。","同一反应中失电子总数一定等于得电子总数，这是配平和计算的总开关。"],"sections":[{"title":"先会正确标化合价","summary":"标错一个价，后面所有身份都会跟着错。","items":[{"label":"单质与常见固定价","rule":"单质中元素为0价；化合物中H通常+1、O通常-2；ⅠA族常+1、ⅡA族常+2。","examples":["Na、O₂、Cl₂均为0价；NaCl中Na为+1、Cl为-1。","【示范：SO₄²⁻和Na₂O₂怎样标价】SO₄²⁻中设S为x，有x+4×(-2)=-2，得S=+6；Na₂O₂中Na为+1，总和为0，得O=-1，说明过氧化物是常见例外。"],"visualSteps":["单质与常见固定价","先用固定价","列代数和","解未知价","查特殊物质"]},{"label":"总和规则","rule":"中性化合物中各元素化合价代数和为0；多原子离子中代数和等于离子电荷。","examples":["SO₄²⁻中S+4×(-2)=-2，所以S为+6。","【示范：SO₄²⁻和Na₂O₂怎样标价】SO₄²⁻中设S为x，有x+4×(-2)=-2，得S=+6；Na₂O₂中Na为+1，总和为0，得O=-1，说明过氧化物是常见例外。"],"visualSteps":["总和规则","先用固定价","列代数和","解未知价","查特殊物质"]},{"label":"常见例外","rule":"过氧化物中O为-1；金属氢化物中H可为-1；具体题目还要服从已知结构和电荷。","examples":["Na₂O₂中O为-1。","【示范：SO₄²⁻和Na₂O₂怎样标价】SO₄²⁻中设S为x，有x+4×(-2)=-2，得S=+6；Na₂O₂中Na为+1，总和为0，得O=-1，说明过氧化物是常见例外。"],"visualSteps":["常见例外","先用固定价","列代数和","解未知价","查特殊物质"]}]},{"title":"把四组概念接成一条线","summary":"过程词和物质身份词要一一对应。","items":[{"label":"化合价升高的一侧","rule":"元素失电子，被氧化，发生氧化反应；含该元素并提供电子的反应物叫还原剂；生成物叫氧化产物。","examples":["Fe²⁺→Fe³⁺+e⁻，Fe²⁺是还原剂。","【示范：Fe²⁺和Cl₂的身份链】Fe²⁺→Fe³⁺+e⁻：升价、失电子、被氧化，Fe²⁺是还原剂；Cl₂+2e⁻→2Cl⁻：降价、得电子、被还原，Cl₂是氧化剂。"],"visualSteps":["化合价升高的一侧","升价失电子","还原剂被氧化","降价得电子","氧化剂被还原"]},{"label":"化合价降低的一侧","rule":"元素得电子，被还原，发生还原反应；接受电子的反应物叫氧化剂；生成物叫还原产物。","examples":["Cl₂+2e⁻→2Cl⁻，Cl₂是氧化剂。","【示范：Fe²⁺和Cl₂的身份链】Fe²⁺→Fe³⁺+e⁻：升价、失电子、被氧化，Fe²⁺是还原剂；Cl₂+2e⁻→2Cl⁻：降价、得电子、被还原，Cl₂是氧化剂。"],"visualSteps":["化合价降低的一侧","升价失电子","还原剂被氧化","降价得电子","氧化剂被还原"]},{"label":"口诀必须有逻辑","rule":"“升失氧、降得还”只能帮助回忆，最终要能说出电子去了哪里。","caution":"氧化剂自身发生还原反应；还原剂自身发生氧化反应。","examples":["【示范：Fe²⁺和Cl₂的身份链】Fe²⁺→Fe³⁺+e⁻：升价、失电子、被氧化，Fe²⁺是还原剂；Cl₂+2e⁻→2Cl⁻：降价、得电子、被还原，Cl₂是氧化剂。"],"visualSteps":["口诀必须有逻辑","升价失电子","还原剂被氧化","降价得电子","氧化剂被还原"]}]},{"title":"电子转移与表示","summary":"不管用双线桥还是半反应，电子总数必须守恒。","items":[{"label":"电子数怎么算","rule":"单个原子的化合价变化数×发生变化的原子个数×该物质计量数，得到转移电子数。","examples":["1 mol Cl₂由0价变-1价，共得到2 mol e⁻。","【示范：2Na+Cl₂→2NaCl的双线桥】Na由0升至+1，2个Na共失2e⁻；Cl由0降至-1，一个Cl₂共得2e⁻。在线桥上标“失2e⁻”与“得2e⁻”，二者相等。"],"visualSteps":["电子数怎么算","标反应前后价态","计算变价原子数","标得失电子","电子总数相等"]},{"label":"双线桥思路","rule":"从反应物的变价元素连到生成物同种元素，标出“升/降、失/得、电子数”。电子不写正负号。","examples":["【示范：2Na+Cl₂→2NaCl的双线桥】Na由0升至+1，2个Na共失2e⁻；Cl由0降至-1，一个Cl₂共得2e⁻。在线桥上标“失2e⁻”与“得2e⁻”，二者相等。"],"visualSteps":["双线桥思路","标反应前后价态","计算变价原子数","标得失电子","电子总数相等"]},{"label":"半反应思路","rule":"分别写氧化半反应和还原半反应，使原子、电荷守恒后相加；酸碱介质中的H⁺、OH⁻、H₂O按条件补齐。","caution":"基础阶段先把变价原子和电子配平，再补其他元素。","examples":["【示范：2Na+Cl₂→2NaCl的双线桥】Na由0升至+1，2个Na共失2e⁻；Cl由0降至-1，一个Cl₂共得2e⁻。在线桥上标“失2e⁻”与“得2e⁻”，二者相等。"],"visualSteps":["半反应思路","标反应前后价态","计算变价原子数","标得失电子","电子总数相等"]}]},{"title":"氧化还原方程式配平","summary":"先电子，后原子，最后电荷和条件。","items":[{"label":"第1步：找变价","rule":"标出反应前后真正发生价态变化的元素，写出升降数。","examples":["【示范：FeS₂被O₂氧化】FeS₂中Fe由+2到+3失1e⁻，两个S由-1到+6共失14e⁻，每个FeS₂共失15e⁻；O₂中两个O共得4e⁻。最小公倍数60，先定4FeS₂和15O₂；再按酸性介质补齐，得到4FeS₂+15O₂+2H₂O=4Fe³⁺+8SO₄²⁻+4H⁺，左右总电荷均为0，并满足原子与电子守恒。"],"visualSteps":["第1步：找变价","标价","升降电子数","最小公倍数","补齐并守恒校验"]},{"label":"第2步：电子守恒","rule":"求升降电子数的最小公倍数，确定氧化剂、还原剂和对应产物的系数。","examples":["【示范：FeS₂被O₂氧化】FeS₂中Fe由+2到+3失1e⁻，两个S由-1到+6共失14e⁻，每个FeS₂共失15e⁻；O₂中两个O共得4e⁻。最小公倍数60，先定4FeS₂和15O₂；再按酸性介质补齐，得到4FeS₂+15O₂+2H₂O=4Fe³⁺+8SO₄²⁻+4H⁺，左右总电荷均为0，并满足原子与电子守恒。"],"visualSteps":["第2步：电子守恒","标价","升降电子数","最小公倍数","补齐并守恒校验"]},{"label":"第3步：补齐并检查","rule":"再配其他元素，最后检查原子守恒、电荷守恒、电子守恒和反应条件。","examples":["酸性MnO₄⁻与Fe²⁺反应中MnO₄⁻:Fe²⁺=1:5。","【示范：FeS₂被O₂氧化】FeS₂中Fe由+2到+3失1e⁻，两个S由-1到+6共失14e⁻，每个FeS₂共失15e⁻；O₂中两个O共得4e⁻。最小公倍数60，先定4FeS₂和15O₂；再按酸性介质补齐，得到4FeS₂+15O₂+2H₂O=4Fe³⁺+8SO₄²⁻+4H⁺，左右总电荷均为0，并满足原子与电子守恒。"],"visualSteps":["第3步：补齐并检查","标价","升降电子数","最小公倍数","补齐并守恒校验"]}]},{"title":"强弱比较、先后反应与守恒","summary":"复杂题仍然只是在电子转移主线上加条件。","items":[{"label":"氧化性和还原性","rule":"一般可由一个自发反应判断：氧化剂的氧化性强于氧化产物，还原剂的还原性强于还原产物。","examples":["【示范：MnO₄⁻先氧化谁】酸性体系中MnO₄⁻遇Fe²⁺和其他还原性粒子时，先由题给反应或强弱关系判断顺序；定量时把各还原剂失电子总数与MnO₄⁻得电子总数相等，不必追逐全部中间产物。"],"visualSteps":["氧化性和还原性","比较氧化还原能力","判断先后","汇总失电子","总电子守恒"]},{"label":"反应先后","rule":"同一氧化剂遇多种还原剂，通常先与还原性较强者反应；反之同理，但题给条件和动力学现象优先。","examples":["【示范：MnO₄⁻先氧化谁】酸性体系中MnO₄⁻遇Fe²⁺和其他还原性粒子时，先由题给反应或强弱关系判断顺序；定量时把各还原剂失电子总数与MnO₄⁻得电子总数相等，不必追逐全部中间产物。"],"visualSteps":["反应先后","比较氧化还原能力","判断先后","汇总失电子","总电子守恒"]},{"label":"多步电子守恒","rule":"中间产物可以不逐一求量，只要初态到终态的总失电子数等于总得电子数。","examples":["工艺流程和滴定计算常用总电子守恒。","【示范：MnO₄⁻先氧化谁】酸性体系中MnO₄⁻遇Fe²⁺和其他还原性粒子时，先由题给反应或强弱关系判断顺序；定量时把各还原剂失电子总数与MnO₄⁻得电子总数相等，不必追逐全部中间产物。"],"visualSteps":["多步电子守恒","比较氧化还原能力","判断先后","汇总失电子","总电子守恒"]}]}],"workedExamples":[{"substance":"SO₄²⁻和Na₂O₂怎样标价","path":"SO₄²⁻中设S为x，有x+4×(-2)=-2，得S=+6；Na₂O₂中Na为+1，总和为0，得O=-1，说明过氧化物是常见例外。","labels":["先用固定价","列代数和","解未知价","查特殊物质"]},{"substance":"Fe²⁺和Cl₂的身份链","path":"Fe²⁺→Fe³⁺+e⁻：升价、失电子、被氧化，Fe²⁺是还原剂；Cl₂+2e⁻→2Cl⁻：降价、得电子、被还原，Cl₂是氧化剂。","labels":["升价失电子","还原剂被氧化","降价得电子","氧化剂被还原"]},{"substance":"2Na+Cl₂→2NaCl的双线桥","path":"Na由0升至+1，2个Na共失2e⁻；Cl由0降至-1，一个Cl₂共得2e⁻。在线桥上标“失2e⁻”与“得2e⁻”，二者相等。","labels":["标反应前后价态","计算变价原子数","标得失电子","电子总数相等"]},{"substance":"FeS₂被O₂氧化","path":"FeS₂中Fe由+2到+3失1e⁻，两个S由-1到+6共失14e⁻，每个FeS₂共失15e⁻；O₂中两个O共得4e⁻。最小公倍数60，先定4FeS₂和15O₂；再按酸性介质补齐，得到4FeS₂+15O₂+2H₂O=4Fe³⁺+8SO₄²⁻+4H⁺，左右总电荷均为0，并满足原子与电子守恒。","labels":["标价","升降电子数","最小公倍数","补齐并守恒校验"]},{"substance":"MnO₄⁻先氧化谁","path":"酸性体系中MnO₄⁻遇Fe²⁺和其他还原性粒子时，先由题给反应或强弱关系判断顺序；定量时把各还原剂失电子总数与MnO₄⁻得电子总数相等，不必追逐全部中间产物。","labels":["比较氧化还原能力","判断先后","汇总失电子","总电子守恒"]},{"substance":"2Na+Cl₂→2NaCl","path":"Na由0升到+1，每个Na失1e⁻，2个Na共失2e⁻；Cl由0降到-1，一个Cl₂含2个Cl，共得2e⁻。Na是还原剂，Cl₂是氧化剂。","labels":["升失氧","降得还","得失电子相等"]},{"substance":"酸性MnO₄⁻氧化Fe²⁺","path":"Mn从+7降到+2，每个Mn得5e⁻；Fe从+2升到+3，每个Fe失1e⁻，因此1个MnO₄⁻对应5个Fe²⁺，再用H⁺、H₂O补H和O并检查电荷。","labels":["先定1:5","再补H和O","查电荷"]}],"checkpoints":["我能不靠“含氧”判断氧化还原反应。","我能把氧化剂、还原剂、氧化产物、还原产物说完整。","我会计算1 mol物质实际转移多少mol电子。","我能用电子守恒解释配平系数。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_REDOX' and skill_id = 'H1_REDOX';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H1_ELECTROLYTE","version":2,"intro":"这一模块把“电解质分类—电离—离子反应—离子方程式”连成一条线：先知道溶液里真正有哪些粒子，再判断哪些粒子发生了反应。","overview":["电解质判断先限化合物，再看物质本身能否在水中或熔融时产生离子。","强电解质在水中近乎完全电离，弱电解质部分电离；强弱与溶解性不是同一标准。","离子反应发生的常见推动力：生成沉淀、气体、弱电解质，或发生氧化还原等。","离子方程式按“写—拆—删—查”完成，并根据少量、过量和反应顺序确定产物。"],"sections":[{"title":"先看水溶液中真正存在的粒子","summary":"宏观上是一杯溶液，微观上可能有分子、离子和水分子共存。","items":[{"label":"强电解质","rule":"在水溶液中近乎完全电离，书写电离方程式时用“=”。常见强酸、强碱和大多数盐属于此类。","examples":["NaCl=Na⁺+Cl⁻；H₂SO₄在基础离子方程式中按强酸处理。","【示范：NaCl、CH₃COOH和蔗糖的粒子图】NaCl在水中以Na⁺、Cl⁻为主，是强电解质；CH₃COOH分子与少量H⁺、CH₃COO⁻共存，是弱电解质；蔗糖主要以分子存在，是非电解质。"],"visualSteps":["强电解质","强电解质完全电离","弱电解质部分电离","非电解质不电离","画真实粒子"]},{"label":"弱电解质","rule":"在水中只部分电离，存在动态平衡，书写时用可逆号。","examples":["CH₃COOH⇌H⁺+CH₃COO⁻；NH₃·H₂O⇌NH₄⁺+OH⁻。","【示范：NaCl、CH₃COOH和蔗糖的粒子图】NaCl在水中以Na⁺、Cl⁻为主，是强电解质；CH₃COOH分子与少量H⁺、CH₃COO⁻共存，是弱电解质；蔗糖主要以分子存在，是非电解质。"],"visualSteps":["弱电解质","强电解质完全电离","弱电解质部分电离","非电解质不电离","画真实粒子"]},{"label":"强弱与溶解性独立","rule":"强弱说已溶解部分的电离程度；溶解性说有多少物质进入溶液。","examples":["BaSO₄难溶，但溶解的部分完全电离，属于强电解质。","【示范：NaCl、CH₃COOH和蔗糖的粒子图】NaCl在水中以Na⁺、Cl⁻为主，是强电解质；CH₃COOH分子与少量H⁺、CH₃COO⁻共存，是弱电解质；蔗糖主要以分子存在，是非电解质。"],"visualSteps":["强弱与溶解性独立","强电解质完全电离","弱电解质部分电离","非电解质不电离","画真实粒子"]}]},{"title":"离子反应为什么能够发生","summary":"本质是某些离子浓度显著减小或电子发生转移。","items":[{"label":"生成沉淀","rule":"离子结合成难溶物并从溶液的自由离子体系中离开。","examples":["Ba²⁺+SO₄²⁻=BaSO₄↓。","【示范：盐酸与NaOH为什么反应】混合后H⁺与OH⁻结合成难电离的H₂O，二者浓度显著降低；Na⁺、Cl⁻没有实质变化，是旁观离子。"],"visualSteps":["生成沉淀","列出溶液粒子","找显著减少粒子","生成弱电解质","识别旁观离子"]},{"label":"生成气体或弱电解质","rule":"生成气体逸出，或生成水、弱酸、弱碱等难电离物质，推动反应进行。","examples":["H⁺+HCO₃⁻=CO₂↑+H₂O；H⁺+OH⁻=H₂O。","【示范：盐酸与NaOH为什么反应】混合后H⁺与OH⁻结合成难电离的H₂O，二者浓度显著降低；Na⁺、Cl⁻没有实质变化，是旁观离子。"],"visualSteps":["生成气体或弱电解质","列出溶液粒子","找显著减少粒子","生成弱电解质","识别旁观离子"]},{"label":"氧化还原、络合等其他原因","rule":"离子之间发生电子转移，或形成稳定的复杂粒子，也可推动反应。","examples":["Fe+2Fe³⁺=3Fe²⁺。","【示范：盐酸与NaOH为什么反应】混合后H⁺与OH⁻结合成难电离的H₂O，二者浓度显著降低；Na⁺、Cl⁻没有实质变化，是旁观离子。"],"caution":"陌生反应以题目给出的事实和信息为准。","visualSteps":["氧化还原、络合等其他原因","列出溶液粒子","找显著减少粒子","生成弱电解质","识别旁观离子"]}]},{"title":"离子方程式“写—拆—删—查”","summary":"每一步都解决一个明确问题。","items":[{"label":"写：写对分子方程式","rule":"先保证反应物、产物、条件和计量数正确；分子方程式错，后面无法补救。","examples":["【示范：HCl+NaOH的写拆删查】先写HCl+NaOH=NaCl+H₂O；把可溶强电解质拆为离子；删去两边相同的Na⁺、Cl⁻；得到H⁺+OH⁻=H₂O，并查事实、原子、电荷和最简系数。"],"visualSteps":["写：写对分子方程式","写对分子式","拆强电解质","删旁观离子","四重检查"]},{"label":"拆：只拆该拆的","rule":"水溶液中的可溶强电解质拆成离子；沉淀、气体、弱电解质、单质和氧化物通常保留化学式。","examples":["CH₃COOH、H₂O、CO₂、CaCO₃不拆。","【示范：HCl+NaOH的写拆删查】先写HCl+NaOH=NaCl+H₂O；把可溶强电解质拆为离子；删去两边相同的Na⁺、Cl⁻；得到H⁺+OH⁻=H₂O，并查事实、原子、电荷和最简系数。"],"visualSteps":["拆：只拆该拆的","写对分子式","拆强电解质","删旁观离子","四重检查"]},{"label":"删：删除旁观离子","rule":"删去反应前后形式和数目都相同的离子，保留真正改变的粒子。","examples":["【示范：HCl+NaOH的写拆删查】先写HCl+NaOH=NaCl+H₂O；把可溶强电解质拆为离子；删去两边相同的Na⁺、Cl⁻；得到H⁺+OH⁻=H₂O，并查事实、原子、电荷和最简系数。"],"visualSteps":["删：删除旁观离子","写对分子式","拆强电解质","删旁观离子","四重检查"]},{"label":"查：四重检查","rule":"检查反应事实、原子守恒、电荷守恒和系数最简；氧化还原还要查电子守恒。","examples":["【示范：HCl+NaOH的写拆删查】先写HCl+NaOH=NaCl+H₂O；把可溶强电解质拆为离子；删去两边相同的Na⁺、Cl⁻；得到H⁺+OH⁻=H₂O，并查事实、原子、电荷和最简系数。"],"visualSteps":["查：四重检查","写对分子式","拆强电解质","删旁观离子","四重检查"]}]},{"title":"离子共存题的判断顺序","summary":"“能大量共存”就是在给定条件下不能发生显著反应。","items":[{"label":"先读隐含条件","rule":"无色、透明、强酸性、强碱性、由水电离的H⁺浓度等条件先翻译成粒子限制。","examples":["无色排除明显有色离子；强酸性相当于有大量H⁺。","【示范：无色酸性溶液能否共存】先把“无色”排除有色离子，把“酸性”转成有大量H⁺；再逐对检查沉淀、气体、弱电解质和氧化还原。HCO₃⁻会与H⁺生成CO₂、H₂O，不能大量共存。"],"visualSteps":["先读隐含条件","翻译隐含条件","逐对检查","写净离子反应","所有离子同时成立"]},{"label":"再逐对排查反应","rule":"依次查沉淀、气体、弱电解质、氧化还原和题目给出的特殊反应。","examples":["【示范：无色酸性溶液能否共存】先把“无色”排除有色离子，把“酸性”转成有大量H⁺；再逐对检查沉淀、气体、弱电解质和氧化还原。HCO₃⁻会与H⁺生成CO₂、H₂O，不能大量共存。"],"visualSteps":["再逐对排查反应","翻译隐含条件","逐对检查","写净离子反应","所有离子同时成立"]},{"label":"注意“少量存在”和“大量共存”","rule":"痕量不等于能大量共存；题目要求的是所有给定离子在相同溶液中都有较大浓度。","examples":["【示范：无色酸性溶液能否共存】先把“无色”排除有色离子，把“酸性”转成有大量H⁺；再逐对检查沉淀、气体、弱电解质和氧化还原。HCO₃⁻会与H⁺生成CO₂、H₂O，不能大量共存。"],"visualSteps":["注意“少量存在”和“大量共存”","翻译隐含条件","逐对检查","写净离子反应","所有离子同时成立"]}]},{"title":"少量、过量和反应顺序","summary":"用量不同会改变终点，必须先找限制量。","items":[{"label":"少量试剂","rule":"把少量物质的化学计量数定为满足完全反应，再判断过量物质剩余。","examples":["少量CO₂通入NaOH溶液主要生成CO₃²⁻。","【示范：CO₂少量与过量通入NaOH】少量CO₂时OH⁻足量，终点以CO₃²⁻为主：CO₂+2OH⁻=CO₃²⁻+H₂O；过量CO₂继续把CO₃²⁻转为HCO₃⁻，总式为CO₂+OH⁻=HCO₃⁻。"],"visualSteps":["少量试剂","定少量为1","判断谁过量","分阶段反应","按终点合并"]},{"label":"过量试剂","rule":"继续反应可能生成新的粒子，离子方程式要写到题设终点。","examples":["过量CO₂通入NaOH溶液可主要生成HCO₃⁻。","【示范：CO₂少量与过量通入NaOH】少量CO₂时OH⁻足量，终点以CO₃²⁻为主：CO₂+2OH⁻=CO₃²⁻+H₂O；过量CO₂继续把CO₃²⁻转为HCO₃⁻，总式为CO₂+OH⁻=HCO₃⁻。"],"visualSteps":["过量试剂","定少量为1","判断谁过量","分阶段反应","按终点合并"]},{"label":"多反应竞争","rule":"先发生更有利或题设指定的反应；必要时分阶段写方程式，再按用量合并。","caution":"不能见到所有可能反应就一次性全部相加。","examples":["【示范：CO₂少量与过量通入NaOH】少量CO₂时OH⁻足量，终点以CO₃²⁻为主：CO₂+2OH⁻=CO₃²⁻+H₂O；过量CO₂继续把CO₃²⁻转为HCO₃⁻，总式为CO₂+OH⁻=HCO₃⁻。"],"visualSteps":["多反应竞争","定少量为1","判断谁过量","分阶段反应","按终点合并"]}]}],"workedExamples":[{"substance":"NaCl、CH₃COOH和蔗糖的粒子图","path":"NaCl在水中以Na⁺、Cl⁻为主，是强电解质；CH₃COOH分子与少量H⁺、CH₃COO⁻共存，是弱电解质；蔗糖主要以分子存在，是非电解质。","labels":["强电解质完全电离","弱电解质部分电离","非电解质不电离","画真实粒子"]},{"substance":"盐酸与NaOH为什么反应","path":"混合后H⁺与OH⁻结合成难电离的H₂O，二者浓度显著降低；Na⁺、Cl⁻没有实质变化，是旁观离子。","labels":["列出溶液粒子","找显著减少粒子","生成弱电解质","识别旁观离子"]},{"substance":"HCl+NaOH的写拆删查","path":"先写HCl+NaOH=NaCl+H₂O；把可溶强电解质拆为离子；删去两边相同的Na⁺、Cl⁻；得到H⁺+OH⁻=H₂O，并查事实、原子、电荷和最简系数。","labels":["写对分子式","拆强电解质","删旁观离子","四重检查"]},{"substance":"无色酸性溶液能否共存","path":"先把“无色”排除有色离子，把“酸性”转成有大量H⁺；再逐对检查沉淀、气体、弱电解质和氧化还原。HCO₃⁻会与H⁺生成CO₂、H₂O，不能大量共存。","labels":["翻译隐含条件","逐对检查","写净离子反应","所有离子同时成立"]},{"substance":"CO₂少量与过量通入NaOH","path":"少量CO₂时OH⁻足量，终点以CO₃²⁻为主：CO₂+2OH⁻=CO₃²⁻+H₂O；过量CO₂继续把CO₃²⁻转为HCO₃⁻，总式为CO₂+OH⁻=HCO₃⁻。","labels":["定少量为1","判断谁过量","分阶段反应","按终点合并"]},{"substance":"盐酸与NaOH","path":"分子方程式HCl+NaOH=NaCl+H₂O；HCl、NaOH、NaCl拆成离子；删去Na⁺、Cl⁻，得到H⁺+OH⁻=H₂O；原子和电荷都守恒。","labels":["写","拆","删","查"]},{"substance":"NaHCO₃与盐酸","path":"NaHCO₃、HCl、NaCl在水中拆写，但HCO₃⁻作为多原子离子整体保留；碳酸分解为CO₂和H₂O，最终HCO₃⁻+H⁺=CO₂↑+H₂O。","labels":["HCO₃⁻不能错拆","气体保留分子式","查电荷0=0"]}],"checkpoints":["我能解释强弱电解质与溶解性的区别。","我能列出离子反应发生的主要条件。","我知道哪些物质在离子方程式中通常不拆。","我遇到少量、过量时会先找限制量。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_ELECTROLYTE' and skill_id = 'H1_ELECTROLYTE';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H1_MOLE_INTRO","version":2,"intro":"物质的量是一座桥：左边连接肉眼可称量的质量，右边连接看不见的微粒数。当前先只掌握n、N、m、M四个量，不提前使用气体摩尔体积和溶液浓度。","overview":["物质的量符号n，单位mol；它表示含有一定数目指定微粒的集合。","1 mol指定微粒约含Nₐ=6.02×10²³个微粒；必须写清是分子、原子、离子还是电子。","N=nNₐ连接物质的量和微粒数；n=m/M连接物质的量和质量。","摩尔质量M有单位g·mol⁻¹；数值常与相对分子质量相同，但概念和单位不同。"],"sections":[{"title":"先明白“1 mol”在数什么","summary":"mol像“打”一样是计数单位，但数量巨大，专门描述微观粒子。","items":[{"label":"物质的量n","rule":"表示含有一定数目粒子的集合体，是七个基本物理量之一；单位是摩尔，符号mol。","examples":["0.5 mol H₂O、2 mol Na⁺。","【示范：1 mol H₂O到底数什么】1 mol H₂O表示约6.02×10²³个水分子；每个水分子含2个H原子和1个O原子，所以含2 mol H原子、1 mol O原子，共3 mol原子。"],"caution":"不能说“1 mol就是6.02×10²³”，应说1 mol指定微粒约含6.02×10²³个。","visualSteps":["物质的量n","先说微粒名称","1 mol对应Nₐ","按化学式下标","分子与原子不混"]},{"label":"阿伏加德罗常数Nₐ","rule":"1 mol任何指定微粒所含微粒数，单位mol⁻¹；中学计算常取约6.02×10²³ mol⁻¹。","examples":["【示范：1 mol H₂O到底数什么】1 mol H₂O表示约6.02×10²³个水分子；每个水分子含2个H原子和1个O原子，所以含2 mol H原子、1 mol O原子，共3 mol原子。"],"visualSteps":["阿伏加德罗常数Nₐ","先说微粒名称","1 mol对应Nₐ","按化学式下标","分子与原子不混"]},{"label":"对象必须写清","rule":"同样1 mol物质，所问分子、原子、离子或电子的数目可能不同。","examples":["1 mol H₂O含1 mol水分子、2 mol H原子、1 mol O原子。","【示范：1 mol H₂O到底数什么】1 mol H₂O表示约6.02×10²³个水分子；每个水分子含2个H原子和1个O原子，所以含2 mol H原子、1 mol O原子，共3 mol原子。"],"visualSteps":["对象必须写清","先说微粒名称","1 mol对应Nₐ","按化学式下标","分子与原子不混"]}]},{"title":"n和N怎样互换","summary":"先确定物质的量，再乘或除Nₐ。","items":[{"label":"由n求N","rule":"N=nNₐ。若化学式中一个粒子含k个目标粒子，还要再乘k。","examples":["0.5 mol O₂含0.5Nₐ个O₂分子，含1.0Nₐ个O原子。","【示范：3.01×10²³个CO₂】n(CO₂)=N/Nₐ=3.01×10²³÷6.02×10²³=0.50 mol；若问O原子，则n(O)=2×0.50=1.00 mol。"],"visualSteps":["由n求N","确认对象","N除以Nₐ","按下标换对象","带单位"]},{"label":"由N求n","rule":"n=N/Nₐ。先保证N数的是题目指定的同一种粒子。","examples":["【示范：3.01×10²³个CO₂】n(CO₂)=N/Nₐ=3.01×10²³÷6.02×10²³=0.50 mol；若问O原子，则n(O)=2×0.50=1.00 mol。"],"visualSteps":["由N求n","确认对象","N除以Nₐ","按下标换对象","带单位"]},{"label":"化学式下标是倍数","rule":"下标只告诉一个化学式单位中含几个目标原子或离子，不能漏乘。","examples":["1 mol Na₂SO₄含2 mol Na⁺和1 mol SO₄²⁻。","【示范：3.01×10²³个CO₂】n(CO₂)=N/Nₐ=3.01×10²³÷6.02×10²³=0.50 mol；若问O原子，则n(O)=2×0.50=1.00 mol。"],"visualSteps":["化学式下标是倍数","确认对象","N除以Nₐ","按下标换对象","带单位"]}]},{"title":"摩尔质量与质量换算","summary":"先分清“相对质量”与“每摩尔质量”。","items":[{"label":"摩尔质量M","rule":"单位物质的量的物质所具有的质量，M=m/n，常用单位g·mol⁻¹。","examples":["H₂O的M=18 g·mol⁻¹。","【示范：36 g H₂O】M(H₂O)=18 g·mol⁻¹，n=36÷18=2 mol。相对分子质量18没有单位；摩尔质量18 g·mol⁻¹有单位。"],"visualSteps":["摩尔质量M","算相对质量","写摩尔质量单位","m除以M","得到物质的量"]},{"label":"与相对分子质量的区别","rule":"相对分子质量是无量纲的相对值；摩尔质量是物理量，有单位。二者在以g·mol⁻¹表示时数值常相同。","examples":["【示范：36 g H₂O】M(H₂O)=18 g·mol⁻¹，n=36÷18=2 mol。相对分子质量18没有单位；摩尔质量18 g·mol⁻¹有单位。"],"visualSteps":["与相对分子质量的区别","算相对质量","写摩尔质量单位","m除以M","得到物质的量"]},{"label":"质量—物质的量","rule":"n=m/M，m=nM。写公式前先统一g与g·mol⁻¹。","examples":["36 g H₂O：n=36/18=2 mol。","【示范：36 g H₂O】M(H₂O)=18 g·mol⁻¹，n=36÷18=2 mol。相对分子质量18没有单位；摩尔质量18 g·mol⁻¹有单位。"],"visualSteps":["质量—物质的量","算相对质量","写摩尔质量单位","m除以M","得到物质的量"]}]},{"title":"基础题的固定四步","summary":"每一步都能防一个常见错误。","items":[{"label":"1. 圈对象","rule":"题目问的是分子、原子、离子、质子、电子还是化学式单位。","examples":["【示范：0.25 mol Al₂(SO₄)₃的四步】圈对象为SO₄²⁻；桥梁是化学式下标；每个化学式单位含3个SO₄²⁻，故n=0.25×3=0.75 mol；若求个数再乘Nₐ并检查数量级。"],"visualSteps":["1. 圈对象","圈对象","找桥梁","处理倍数","查单位数量级"]},{"label":"2. 找桥梁","rule":"已知质量就先用n=m/M；已知粒子数就先用n=N/Nₐ。","examples":["【示范：0.25 mol Al₂(SO₄)₃的四步】圈对象为SO₄²⁻；桥梁是化学式下标；每个化学式单位含3个SO₄²⁻，故n=0.25×3=0.75 mol；若求个数再乘Nₐ并检查数量级。"],"visualSteps":["2. 找桥梁","圈对象","找桥梁","处理倍数","查单位数量级"]},{"label":"3. 处理倍数","rule":"根据化学式下标或离子电荷关系换成目标粒子的物质的量。","examples":["【示范：0.25 mol Al₂(SO₄)₃的四步】圈对象为SO₄²⁻；桥梁是化学式下标；每个化学式单位含3个SO₄²⁻，故n=0.25×3=0.75 mol；若求个数再乘Nₐ并检查数量级。"],"visualSteps":["3. 处理倍数","圈对象","找桥梁","处理倍数","查单位数量级"]},{"label":"4. 查单位和数量级","rule":"n用mol、M用g·mol⁻¹，微粒数通常是10²³量级。","examples":["【示范：0.25 mol Al₂(SO₄)₃的四步】圈对象为SO₄²⁻；桥梁是化学式下标；每个化学式单位含3个SO₄²⁻，故n=0.25×3=0.75 mol；若求个数再乘Nₐ并检查数量级。"],"visualSteps":["4. 查单位和数量级","圈对象","找桥梁","处理倍数","查单位数量级"]}]}],"workedExamples":[{"substance":"1 mol H₂O到底数什么","path":"1 mol H₂O表示约6.02×10²³个水分子；每个水分子含2个H原子和1个O原子，所以含2 mol H原子、1 mol O原子，共3 mol原子。","labels":["先说微粒名称","1 mol对应Nₐ","按化学式下标","分子与原子不混"]},{"substance":"3.01×10²³个CO₂","path":"n(CO₂)=N/Nₐ=3.01×10²³÷6.02×10²³=0.50 mol；若问O原子，则n(O)=2×0.50=1.00 mol。","labels":["确认对象","N除以Nₐ","按下标换对象","带单位"]},{"substance":"36 g H₂O","path":"M(H₂O)=18 g·mol⁻¹，n=36÷18=2 mol。相对分子质量18没有单位；摩尔质量18 g·mol⁻¹有单位。","labels":["算相对质量","写摩尔质量单位","m除以M","得到物质的量"]},{"substance":"0.25 mol Al₂(SO₄)₃的四步","path":"圈对象为SO₄²⁻；桥梁是化学式下标；每个化学式单位含3个SO₄²⁻，故n=0.25×3=0.75 mol；若求个数再乘Nₐ并检查数量级。","labels":["圈对象","找桥梁","处理倍数","查单位数量级"]},{"substance":"36 g H₂O含多少个水分子","path":"M(H₂O)=18 g·mol⁻¹；n=36/18=2 mol；每1 mol水含Nₐ个水分子，所以N=2Nₐ≈1.204×10²⁴个。","labels":["m→n","n→N","对象是水分子"]},{"substance":"0.25 mol Al₂(SO₄)₃含多少mol SO₄²⁻","path":"一个化学式单位含3个SO₄²⁻，所以硫酸根离子的物质的量=0.25×3=0.75 mol。若求个数，再乘Nₐ。","labels":["先看下标3","目标是硫酸根离子","不必先求质量"]}],"checkpoints":["我能说清n、N、Nₐ、m、M各自表示什么。","我写摩尔质量时不会漏掉g·mol⁻¹。","我会先圈出目标微粒再计算。","我不会在当前基础模块提前套22.4 L·mol⁻¹。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_MOLE_INTRO' and skill_id = 'H1_MOLE_INTRO';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H1_MOLE","version":2,"intro":"完整物质的量计算只有一个中心n。无论题目给质量、微粒数、气体体积还是溶液浓度，都先回到n，再按化学方程式的计量关系走向所求量。","overview":["四条主桥：n=m/M，N=nNₐ，气体n=V/Vₘ，溶液n=cV。","使用Vₘ必须同时检查物质是气体、温度和压强条件；22.4 L·mol⁻¹只对应标准状况下的近似值。","使用c=n/V时，溶液体积必须以L代入，不是溶剂体积。","反应计算先把已知量化成n，再用配平方程式系数比转移。"],"sections":[{"title":"以n为中心的换算网络","summary":"看到任何量都问：怎样先到n？","items":[{"label":"质量桥m↔n","rule":"n=m/M，m=nM。M按化学式计算，单位通常为g·mol⁻¹。","examples":["【示范：11.2 L标况O₂的换算网络】标况下n(O₂)=11.2/22.4=0.50 mol；m=0.50×32=16 g；N(O₂)=0.50Nₐ；N(O原子)=1.00Nₐ。所有量先汇到n再分流。"],"visualSteps":["质量桥m↔n","V到n","n到m","n到N","按下标换粒子"]},{"label":"粒子桥N↔n","rule":"N=nNₐ；再结合化学式下标、离子数或电子数处理目标粒子。","examples":["【示范：11.2 L标况O₂的换算网络】标况下n(O₂)=11.2/22.4=0.50 mol；m=0.50×32=16 g；N(O₂)=0.50Nₐ；N(O原子)=1.00Nₐ。所有量先汇到n再分流。"],"visualSteps":["粒子桥N↔n","V到n","n到m","n到N","按下标换粒子"]},{"label":"气体桥V↔n","rule":"在指定温度和压强下n=V/Vₘ；标准状况下Vₘ≈22.4 L·mol⁻¹。","caution":"非标准状况不能擅自用22.4；水在标准状况下不是气体。","examples":["【示范：11.2 L标况O₂的换算网络】标况下n(O₂)=11.2/22.4=0.50 mol；m=0.50×32=16 g；N(O₂)=0.50Nₐ；N(O原子)=1.00Nₐ。所有量先汇到n再分流。"],"visualSteps":["气体桥V↔n","V到n","n到m","n到N","按下标换粒子"]},{"label":"溶液桥c、V↔n","rule":"n=cV，c=n/V。V指溶液体积并以L计。","examples":["500 mL=0.500 L。","【示范：11.2 L标况O₂的换算网络】标况下n(O₂)=11.2/22.4=0.50 mol；m=0.50×32=16 g；N(O₂)=0.50Nₐ；N(O原子)=1.00Nₐ。所有量先汇到n再分流。"],"visualSteps":["溶液桥c、V↔n","V到n","n到m","n到N","按下标换粒子"]}]},{"title":"气体题先查条件","summary":"气体摩尔体积不是所有气体在所有条件下都相同。","items":[{"label":"标准状况","rule":"中学常指0 ℃、101 kPa；此时理想近似下1 mol气体体积约22.4 L。","examples":["【示范：标况11.2 L水是陷阱】22.4 L·mol⁻¹只用于该状态下的气体；0 ℃、101 kPa时水不是气体，不能用11.2/22.4。若同温同压比较两种气体，体积比才等于物质的量比。"],"visualSteps":["标准状况","查温压","查物态","再用Vₘ","同温同压比较"]},{"label":"阿伏加德罗定律","rule":"同温同压下，相同体积的任何气体含相同数目的分子；气体体积比等于物质的量比。","examples":["【示范：标况11.2 L水是陷阱】22.4 L·mol⁻¹只用于该状态下的气体；0 ℃、101 kPa时水不是气体，不能用11.2/22.4。若同温同压比较两种气体，体积比才等于物质的量比。"],"visualSteps":["阿伏加德罗定律","查温压","查物态","再用Vₘ","同温同压比较"]},{"label":"气体混合物","rule":"总物质的量等于各组分物质的量之和；平均摩尔质量=总质量/总物质的量。","examples":["【示范：标况11.2 L水是陷阱】22.4 L·mol⁻¹只用于该状态下的气体；0 ℃、101 kPa时水不是气体，不能用11.2/22.4。若同温同压比较两种气体，体积比才等于物质的量比。"],"visualSteps":["气体混合物","查温压","查物态","再用Vₘ","同温同压比较"]}]},{"title":"物质的量浓度与配制","summary":"浓度描述单位体积溶液中溶质的物质的量。","items":[{"label":"定义与单位","rule":"c=n/V，常用单位mol·L⁻¹。这里V是最终溶液体积，不是加入水的体积。","examples":["【示范：配500 mL 0.200 mol·L⁻¹ NaCl】需n=cV=0.200×0.500=0.100 mol，m=5.85 g；按称量、溶解、转移、洗涤、定容、摇匀操作。定容看最终溶液体积，不看加水体积。"],"visualSteps":["定义与单位","计算用量","称量溶解","转移洗涤","定容摇匀"]},{"label":"稀释与混合","rule":"同一溶质且无反应时，稀释前后溶质的量不变，可用c₁V₁=c₂V₂；发生反应时不能直接套。","examples":["【示范：配500 mL 0.200 mol·L⁻¹ NaCl】需n=cV=0.200×0.500=0.100 mol，m=5.85 g；按称量、溶解、转移、洗涤、定容、摇匀操作。定容看最终溶液体积，不看加水体积。"],"visualSteps":["稀释与混合","计算用量","称量溶解","转移洗涤","定容摇匀"]},{"label":"一定浓度溶液配制","rule":"计算—称量/量取—溶解—转移—洗涤—定容—摇匀；容量瓶只能配制规定体积。","caution":"定容仰视或俯视会改变最终体积，从而改变浓度。","examples":["【示范：配500 mL 0.200 mol·L⁻¹ NaCl】需n=cV=0.200×0.500=0.100 mol，m=5.85 g；按称量、溶解、转移、洗涤、定容、摇匀操作。定容看最终溶液体积，不看加水体积。"],"visualSteps":["一定浓度溶液配制","计算用量","称量溶解","转移洗涤","定容摇匀"]}]},{"title":"化学方程式怎样连接不同物质","summary":"配平系数给出的就是物质的量之比。","items":[{"label":"先配平方程式","rule":"只有正确配平后，系数比才能作为n之比。","examples":["【示范：Fe与HCl的限制量】对Fe+2HCl=FeCl₂+H₂，分别计算n(Fe)/1与n(HCl)/2，较小者决定反应进度；按系数求H₂，再用质量、气体体积或粒子数桥梁转换，并用元素守恒验算。"],"visualSteps":["先配平方程式","配平方程式","比较n/系数","按系数转移","守恒验算"]},{"label":"找限制量","rule":"有两个或更多反应物时，分别计算能支持的反应进度，先耗尽者是限制量。","examples":["【示范：Fe与HCl的限制量】对Fe+2HCl=FeCl₂+H₂，分别计算n(Fe)/1与n(HCl)/2，较小者决定反应进度；按系数求H₂，再用质量、气体体积或粒子数桥梁转换，并用元素守恒验算。"],"visualSteps":["找限制量","配平方程式","比较n/系数","按系数转移","守恒验算"]},{"label":"按系数转移","rule":"已知物质的n÷其系数=所求物质的n÷其系数；再转换成题目要求的质量、体积或粒子数。","examples":["【示范：Fe与HCl的限制量】对Fe+2HCl=FeCl₂+H₂，分别计算n(Fe)/1与n(HCl)/2，较小者决定反应进度；按系数求H₂，再用质量、气体体积或粒子数桥梁转换，并用元素守恒验算。"],"visualSteps":["按系数转移","配平方程式","比较n/系数","按系数转移","守恒验算"]},{"label":"守恒法辅助","rule":"质量守恒、元素守恒、电子守恒和电荷守恒能绕开复杂中间步骤，并用于验算。","examples":["【示范：Fe与HCl的限制量】对Fe+2HCl=FeCl₂+H₂，分别计算n(Fe)/1与n(HCl)/2，较小者决定反应进度；按系数求H₂，再用质量、气体体积或粒子数桥梁转换，并用元素守恒验算。"],"visualSteps":["守恒法辅助","配平方程式","比较n/系数","按系数转移","守恒验算"]}]},{"title":"阿伏加德罗常数判断题的检查表","summary":"每个选项都按对象、条件、反应、倍数四关检查。","items":[{"label":"对象关","rule":"问的是分子、原子、离子、质子、中子、电子还是化学键。","examples":["【示范：NA判断题逐关过】判断“标况22.4 L Cl₂含原子数2Nₐ”：对象是Cl原子，状态和物态成立，n(Cl₂)=1 mol，下标倍数2，且无其他反应，所以结论正确。遇溶液、弱电解质或可逆反应还要加查相应条件。"],"visualSteps":["对象关","对象","状态","溶液与反应","结构倍数"]},{"label":"条件关","rule":"气体是否处在指定状态，物质在该状态是否为气体，溶液是否给了体积。","examples":["【示范：NA判断题逐关过】判断“标况22.4 L Cl₂含原子数2Nₐ”：对象是Cl原子，状态和物态成立，n(Cl₂)=1 mol，下标倍数2，且无其他反应，所以结论正确。遇溶液、弱电解质或可逆反应还要加查相应条件。"],"visualSteps":["条件关","对象","状态","溶液与反应","结构倍数"]},{"label":"反应关","rule":"可逆反应是否完全、弱电解质是否完全电离、盐类是否水解、物质是否发生歧化或聚合。","examples":["【示范：NA判断题逐关过】判断“标况22.4 L Cl₂含原子数2Nₐ”：对象是Cl原子，状态和物态成立，n(Cl₂)=1 mol，下标倍数2，且无其他反应，所以结论正确。遇溶液、弱电解质或可逆反应还要加查相应条件。"],"visualSteps":["反应关","对象","状态","溶液与反应","结构倍数"]},{"label":"倍数关","rule":"化学式下标、价电子数、键数和离子电荷带来的倍数是否算全。","examples":["【示范：NA判断题逐关过】判断“标况22.4 L Cl₂含原子数2Nₐ”：对象是Cl原子，状态和物态成立，n(Cl₂)=1 mol，下标倍数2，且无其他反应，所以结论正确。遇溶液、弱电解质或可逆反应还要加查相应条件。"],"visualSteps":["倍数关","对象","状态","溶液与反应","结构倍数"]}]}],"workedExamples":[{"substance":"11.2 L标况O₂的换算网络","path":"标况下n(O₂)=11.2/22.4=0.50 mol；m=0.50×32=16 g；N(O₂)=0.50Nₐ；N(O原子)=1.00Nₐ。所有量先汇到n再分流。","labels":["V到n","n到m","n到N","按下标换粒子"]},{"substance":"标况11.2 L水是陷阱","path":"22.4 L·mol⁻¹只用于该状态下的气体；0 ℃、101 kPa时水不是气体，不能用11.2/22.4。若同温同压比较两种气体，体积比才等于物质的量比。","labels":["查温压","查物态","再用Vₘ","同温同压比较"]},{"substance":"配500 mL 0.200 mol·L⁻¹ NaCl","path":"需n=cV=0.200×0.500=0.100 mol，m=5.85 g；按称量、溶解、转移、洗涤、定容、摇匀操作。定容看最终溶液体积，不看加水体积。","labels":["计算用量","称量溶解","转移洗涤","定容摇匀"]},{"substance":"Fe与HCl的限制量","path":"对Fe+2HCl=FeCl₂+H₂，分别计算n(Fe)/1与n(HCl)/2，较小者决定反应进度；按系数求H₂，再用质量、气体体积或粒子数桥梁转换，并用元素守恒验算。","labels":["配平方程式","比较n/系数","按系数转移","守恒验算"]},{"substance":"NA判断题逐关过","path":"判断“标况22.4 L Cl₂含原子数2Nₐ”：对象是Cl原子，状态和物态成立，n(Cl₂)=1 mol，下标倍数2，且无其他反应，所以结论正确。遇溶液、弱电解质或可逆反应还要加查相应条件。","labels":["对象","状态","溶液与反应","结构倍数"]},{"substance":"5.85 g NaCl配成500 mL溶液","path":"M(NaCl)=58.5 g·mol⁻¹，n=5.85/58.5=0.100 mol；V=0.500 L；c=0.100/0.500=0.200 mol·L⁻¹。","labels":["m→n","mL→L","n/V"]},{"substance":"标准状况下11.2 L O₂含多少个O原子","path":"O₂是标况气体，n(O₂)=11.2/22.4=0.5 mol；每个O₂含2个O原子，所以n(O原子)=1.0 mol，N=Nₐ。","labels":["先查气体条件","分子到原子乘2","结果约6.02×10²³"]}],"checkpoints":["我能从m、N、V、c中的任意一个量回到n。","我使用22.4前会检查状态和物态。","我能说明溶液体积与溶剂体积的区别。","我能用配平方程式的系数比完成反应计量。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_MOLE' and skill_id = 'H1_MOLE';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H1_NACL","version":2,"intro":"元素化合物不要背成孤立反应。每遇到一种物质都问四件事：中心元素是什么价态、物质属于什么类别、在什么条件下反应、中心元素最后去了哪里。","overview":["钠单质处于0价，强还原性来自容易失去最外层1个电子；保存和取用都要隔绝水和空气。","Na₂O与Na₂O₂必须分开：前者O为-2，后者O为-1，过氧化钠具有氧化性并能供氧。","Na₂CO₃与NaHCO₃用溶解性、碱性、热稳定性和与酸反应现象比较。","Cl₂既是有毒黄绿色气体，又是强氧化剂；氯水是多粒子混合体系。","漂白和消毒的核心通常是HClO等含氯氧化性粒子，现象解释必须写清水和光照条件。"],"sections":[{"title":"钠：从原子结构理解强还原性","summary":"第3周期ⅠA族，最外层1个电子，易失电子形成Na⁺。","items":[{"label":"物理性质与保存","rule":"银白色、质软、密度小、熔点较低；易与空气和水反应，通常保存在煤油或石蜡油中。","examples":["【示范：钠投入滴酚酞的水】Na浮在水面、熔成小球、四处游动并可能发声，溶液变红；分别由密度小、反应放热、H₂推动、生成NaOH解释。方程式2Na+2H₂O=2NaOH+H₂↑。"],"visualSteps":["物理性质与保存","观察现象","逐项解释","写方程式","说明保存原因"]},{"label":"与水反应","rule":"2Na+2H₂O=2NaOH+H₂↑。浮、熔、游、响、红分别可由密度、放热熔化、气体推动、反应剧烈和生成碱解释。","examples":["【示范：钠投入滴酚酞的水】Na浮在水面、熔成小球、四处游动并可能发声，溶液变红；分别由密度小、反应放热、H₂推动、生成NaOH解释。方程式2Na+2H₂O=2NaOH+H₂↑。"],"visualSteps":["与水反应","观察现象","逐项解释","写方程式","说明保存原因"]},{"label":"与氧气反应","rule":"产物受条件影响：常温表面生成氧化物，加热时主要生成Na₂O₂。","caution":"方程式产物必须结合题目给出的温度和现象。","examples":["【示范：钠投入滴酚酞的水】Na浮在水面、熔成小球、四处游动并可能发声，溶液变红；分别由密度小、反应放热、H₂推动、生成NaOH解释。方程式2Na+2H₂O=2NaOH+H₂↑。"],"visualSteps":["与氧气反应","观察现象","逐项解释","写方程式","说明保存原因"]}]},{"title":"氧化钠与过氧化钠","summary":"先看氧的价态，再看反应类型。","items":[{"label":"Na₂O","rule":"碱性氧化物，和水生成NaOH，和酸生成盐和水。","examples":["Na₂O+H₂O=2NaOH。","【示范：Na₂O与Na₂O₂遇水】Na₂O中O为-2，与水生成NaOH；Na₂O₂中O为-1，与水生成NaOH和O₂。后者既要守原子，也要用氧元素歧化的电子转移检查。"],"visualSteps":["Na₂O","辨氧化物/过氧化物","标氧价态","写产物","原子电子守恒"]},{"label":"Na₂O₂","rule":"过氧化物，O为-1价；与水或CO₂反应能生成O₂，兼具供氧和氧化作用。","examples":["2Na₂O₂+2H₂O=4NaOH+O₂↑；2Na₂O₂+2CO₂=2Na₂CO₃+O₂。","【示范：Na₂O与Na₂O₂遇水】Na₂O中O为-2，与水生成NaOH；Na₂O₂中O为-1，与水生成NaOH和O₂。后者既要守原子，也要用氧元素歧化的电子转移检查。"],"visualSteps":["Na₂O₂","辨氧化物/过氧化物","标氧价态","写产物","原子电子守恒"]},{"label":"电子转移判断","rule":"Na₂O₂中-1价氧可一部分升为0价、一部分降为-2价，具体反应要按产物判断电子转移。","examples":["【示范：Na₂O与Na₂O₂遇水】Na₂O中O为-2，与水生成NaOH；Na₂O₂中O为-1，与水生成NaOH和O₂。后者既要守原子，也要用氧元素歧化的电子转移检查。"],"visualSteps":["电子转移判断","辨氧化物/过氧化物","标氧价态","写产物","原子电子守恒"]}]},{"title":"碳酸钠与碳酸氢钠","summary":"同一中心元素、不同酸根形式，性质不完全相同。","items":[{"label":"溶液碱性与水解","rule":"相同条件下Na₂CO₃水解程度更明显，溶液碱性通常强于NaHCO₃。","examples":["【示范：Na₂CO₃与NaHCO₃鉴别和转化】等浓度溶液中Na₂CO₃碱性较强；加热只有NaHCO₃明显分解放出CO₂；Na₂CO₃吸收CO₂和H₂O变NaHCO₃，NaHCO₃受热或加适量碱转回。"],"visualSteps":["溶液碱性与水解","比较水解","比较热稳定","选鉴别方法","写相互转化"]},{"label":"与酸反应","rule":"两者都能与酸放出CO₂；相同物质的量完全反应时耗H⁺量不同。","examples":["CO₃²⁻+2H⁺=CO₂↑+H₂O；HCO₃⁻+H⁺=CO₂↑+H₂O。","【示范：Na₂CO₃与NaHCO₃鉴别和转化】等浓度溶液中Na₂CO₃碱性较强；加热只有NaHCO₃明显分解放出CO₂；Na₂CO₃吸收CO₂和H₂O变NaHCO₃，NaHCO₃受热或加适量碱转回。"],"visualSteps":["与酸反应","比较水解","比较热稳定","选鉴别方法","写相互转化"]},{"label":"热稳定性","rule":"Na₂CO₃较稳定；NaHCO₃受热分解：2NaHCO₃→Na₂CO₃+CO₂↑+H₂O。","examples":["【示范：Na₂CO₃与NaHCO₃鉴别和转化】等浓度溶液中Na₂CO₃碱性较强；加热只有NaHCO₃明显分解放出CO₂；Na₂CO₃吸收CO₂和H₂O变NaHCO₃，NaHCO₃受热或加适量碱转回。"],"visualSteps":["热稳定性","比较水解","比较热稳定","选鉴别方法","写相互转化"]},{"label":"相互转化","rule":"Na₂CO₃吸收CO₂和H₂O可转化为NaHCO₃；NaHCO₃受热或与适量碱反应可转回Na₂CO₃。","examples":["【示范：Na₂CO₃与NaHCO₃鉴别和转化】等浓度溶液中Na₂CO₃碱性较强；加热只有NaHCO₃明显分解放出CO₂；Na₂CO₃吸收CO₂和H₂O变NaHCO₃，NaHCO₃受热或加适量碱转回。"],"visualSteps":["相互转化","比较水解","比较热稳定","选鉴别方法","写相互转化"]}]},{"title":"氯气与氯水","summary":"把Cl₂的0价和氯水中的多种粒子分开。","items":[{"label":"氯气的性质","rule":"黄绿色、有刺激性、有毒、密度比空气大，可溶于水；强氧化性来自Cl₂易得电子形成Cl⁻。","examples":["与Fe反应通常生成FeCl₃。","【示范：新制氯水的多重性质】Cl₂+H₂O⇌HCl+HClO。H⁺体现酸性，Cl⁻可被Ag⁺检验，Cl₂/HClO体现氧化性，HClO使有色物褪色；光照使HClO分解，久置后性质改变。"],"visualSteps":["氯气的性质","建立平衡","列所有粒子","粒子对应性质","判断久置变化"]},{"label":"与水的反应","rule":"Cl₂+H₂O⇌HCl+HClO，是歧化反应：Cl从0价分别变为-1和+1。","examples":["【示范：新制氯水的多重性质】Cl₂+H₂O⇌HCl+HClO。H⁺体现酸性，Cl⁻可被Ag⁺检验，Cl₂/HClO体现氧化性，HClO使有色物褪色；光照使HClO分解，久置后性质改变。"],"visualSteps":["与水的反应","建立平衡","列所有粒子","粒子对应性质","判断久置变化"]},{"label":"新制氯水的粒子","rule":"通常含Cl₂、H₂O、HClO分子以及H⁺、Cl⁻、ClO⁻、OH⁻等离子；不同性质由不同粒子负责。","caution":"氯水是混合物，液氯是液态Cl₂纯净物。","examples":["【示范：新制氯水的多重性质】Cl₂+H₂O⇌HCl+HClO。H⁺体现酸性，Cl⁻可被Ag⁺检验，Cl₂/HClO体现氧化性，HClO使有色物褪色；光照使HClO分解，久置后性质改变。"],"visualSteps":["新制氯水的粒子","建立平衡","列所有粒子","粒子对应性质","判断久置变化"]},{"label":"光照变化","rule":"HClO见光分解，久置氯水中有效成分减少，体系逐渐更接近稀盐酸。","examples":["【示范：新制氯水的多重性质】Cl₂+H₂O⇌HCl+HClO。H⁺体现酸性，Cl⁻可被Ag⁺检验，Cl₂/HClO体现氧化性，HClO使有色物褪色；光照使HClO分解，久置后性质改变。"],"visualSteps":["光照变化","建立平衡","列所有粒子","粒子对应性质","判断久置变化"]}]},{"title":"漂白、消毒、制备和检验","summary":"从氧化性与实验安全理解用途。","items":[{"label":"漂白与消毒","rule":"HClO等氧化性含氯物种能破坏有色物质或微生物结构；漂白通常不可逆。","caution":"干燥Cl₂不能使干燥有色布条明显褪色，水参与形成HClO。","examples":["【示范：从制氯到检氯离子】实验室由MnO₂与浓盐酸加热制Cl₂，先除HCl和水蒸气干扰，再根据密度/溶解性收集并吸收尾气；检Cl⁻时取样、加稀硝酸酸化、再加AgNO₃，见白色AgCl沉淀。"],"visualSteps":["漂白与消毒","发生装置","净化收集","尾气处理","取样检验"]},{"label":"实验室制Cl₂","rule":"常用强氧化剂氧化浓盐酸中的Cl⁻，装置要包含发生、净化、干燥、收集和尾气吸收。","examples":["MnO₂+4HCl(浓)加热→MnCl₂+Cl₂↑+2H₂O。","【示范：从制氯到检氯离子】实验室由MnO₂与浓盐酸加热制Cl₂，先除HCl和水蒸气干扰，再根据密度/溶解性收集并吸收尾气；检Cl⁻时取样、加稀硝酸酸化、再加AgNO₃，见白色AgCl沉淀。"],"visualSteps":["实验室制Cl₂","发生装置","净化收集","尾气处理","取样检验"]},{"label":"Cl⁻检验","rule":"先用稀硝酸排除干扰，再加AgNO₃，产生不溶于稀硝酸的白色AgCl沉淀。","caution":"含Cl元素不等于含Cl⁻；ClO⁻中的氯不能直接用该方法等同检出。","examples":["【示范：从制氯到检氯离子】实验室由MnO₂与浓盐酸加热制Cl₂，先除HCl和水蒸气干扰，再根据密度/溶解性收集并吸收尾气；检Cl⁻时取样、加稀硝酸酸化、再加AgNO₃，见白色AgCl沉淀。"],"visualSteps":["Cl⁻检验","发生装置","净化收集","尾气处理","取样检验"]}]}],"workedExamples":[{"substance":"钠投入滴酚酞的水","path":"Na浮在水面、熔成小球、四处游动并可能发声，溶液变红；分别由密度小、反应放热、H₂推动、生成NaOH解释。方程式2Na+2H₂O=2NaOH+H₂↑。","labels":["观察现象","逐项解释","写方程式","说明保存原因"]},{"substance":"Na₂O与Na₂O₂遇水","path":"Na₂O中O为-2，与水生成NaOH；Na₂O₂中O为-1，与水生成NaOH和O₂。后者既要守原子，也要用氧元素歧化的电子转移检查。","labels":["辨氧化物/过氧化物","标氧价态","写产物","原子电子守恒"]},{"substance":"Na₂CO₃与NaHCO₃鉴别和转化","path":"等浓度溶液中Na₂CO₃碱性较强；加热只有NaHCO₃明显分解放出CO₂；Na₂CO₃吸收CO₂和H₂O变NaHCO₃，NaHCO₃受热或加适量碱转回。","labels":["比较水解","比较热稳定","选鉴别方法","写相互转化"]},{"substance":"新制氯水的多重性质","path":"Cl₂+H₂O⇌HCl+HClO。H⁺体现酸性，Cl⁻可被Ag⁺检验，Cl₂/HClO体现氧化性，HClO使有色物褪色；光照使HClO分解，久置后性质改变。","labels":["建立平衡","列所有粒子","粒子对应性质","判断久置变化"]},{"substance":"从制氯到检氯离子","path":"实验室由MnO₂与浓盐酸加热制Cl₂，先除HCl和水蒸气干扰，再根据密度/溶解性收集并吸收尾气；检Cl⁻时取样、加稀硝酸酸化、再加AgNO₃，见白色AgCl沉淀。","labels":["发生装置","净化收集","尾气处理","取样检验"]},{"substance":"钠投入滴有酚酞的水","path":"Na密度小先浮起；反应放热使其熔成小球；生成H₂推动游动并可能发声；生成NaOH使酚酞变红。每个现象都对应一个原因。","labels":["浮","熔","游响","红"]},{"substance":"新制氯水使有色纸条褪色","path":"Cl₂先与水建立平衡生成HCl和HClO；HClO具有强氧化性，破坏发色结构。若纸条干燥且无水，HClO难以形成，漂白现象不明显。","labels":["水参与","HClO负责","氧化漂白"]}],"checkpoints":["我能用价态和类别区分Na₂O、Na₂O₂。","我能比较Na₂CO₃、NaHCO₃的四类性质。","我能列出新制氯水的主要粒子并说明各自作用。","我能写出Cl⁻检验的试剂、现象和结论边界。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_NACL' and skill_id = 'H1_NACL';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H2_THERMO","version":2,"intro":"化学反应既有物质变化，也有能量变化。反应热题先确定“体系从什么状态变到什么状态”，再处理反应式的方向、倍数和物态，最后才代数计算。","overview":["ΔH=生成物总焓−反应物总焓；放热反应ΔH<0，吸热反应ΔH>0。","断键吸收能量、成键释放能量；ΔH≈反应物断键吸能−生成物成键放能。","热化学方程式中系数、物态、温度压强和ΔH是一个整体。","盖斯定律只看始态与终态：反应式怎样线性组合，ΔH就怎样同步运算。"],"sections":[{"title":"反应热和焓变从哪里来","summary":"能量守恒没有失效，能量只是在体系与环境之间转移。","items":[{"label":"体系与环境","rule":"研究的反应物和生成物构成体系，其余部分是环境。体系向环境释放热量叫放热，体系从环境吸收热量叫吸热。","examples":["【示范：H₂燃烧的能量账】把H₂和O₂看作体系：生成液态水时体系向环境放热，H(生成物)<H(反应物)，所以ΔH<0。能量图的峰表示活化能，始末高度差才是ΔH。"],"visualSteps":["体系与环境","划分体系环境","判断热量方向","生成物减反应物","区分活化能"]},{"label":"焓变ΔH","rule":"在常压条件下，反应热可用焓变表示。ΔH=H(生成物)−H(反应物)，单位常为kJ·mol⁻¹。","caution":"这里“每摩尔”对应热化学方程式所表示的反应进度。","examples":["【示范：H₂燃烧的能量账】把H₂和O₂看作体系：生成液态水时体系向环境放热，H(生成物)<H(反应物)，所以ΔH<0。能量图的峰表示活化能，始末高度差才是ΔH。"],"visualSteps":["焓变ΔH","划分体系环境","判断热量方向","生成物减反应物","区分活化能"]},{"label":"能量图","rule":"生成物能量低于反应物时ΔH<0；高于反应物时ΔH>0。活化能是跨越能垒所需能量，不等于ΔH。","examples":["【示范：H₂燃烧的能量账】把H₂和O₂看作体系：生成液态水时体系向环境放热，H(生成物)<H(反应物)，所以ΔH<0。能量图的峰表示活化能，始末高度差才是ΔH。"],"visualSteps":["能量图","划分体系环境","判断热量方向","生成物减反应物","区分活化能"]}]},{"title":"从化学键理解吸热和放热","summary":"旧键断裂和新键形成同时发生。","items":[{"label":"断键吸热","rule":"把原子从已有化学键中分开需要输入能量。","examples":["【示范：H₂+Cl₂→2HCl的键能估算】先断1 mol H—H和1 mol Cl—Cl键吸热，再形成2 mol H—Cl键放热；ΔH≈断键总能量−成键总能量。若成键放热的绝对值更大，结果为负。"],"visualSteps":["断键吸热","数断裂键","数形成键","断键减成键","判正负"]},{"label":"成键放热","rule":"原子重新形成更稳定的化学键时会向外界释放能量。","examples":["【示范：H₂+Cl₂→2HCl的键能估算】先断1 mol H—H和1 mol Cl—Cl键吸热，再形成2 mol H—Cl键放热；ΔH≈断键总能量−成键总能量。若成键放热的绝对值更大，结果为负。"],"visualSteps":["成键放热","数断裂键","数形成键","断键减成键","判正负"]},{"label":"键能估算","rule":"ΔH≈反应物中断裂化学键的总键能−生成物中形成化学键的总键能。","caution":"键能法通常是平均键能估算，具体物质的实验焓变更精确。","examples":["【示范：H₂+Cl₂→2HCl的键能估算】先断1 mol H—H和1 mol Cl—Cl键吸热，再形成2 mol H—Cl键放热；ΔH≈断键总能量−成键总能量。若成键放热的绝对值更大，结果为负。"],"visualSteps":["键能估算","数断裂键","数形成键","断键减成键","判正负"]}]},{"title":"热化学方程式怎样读写","summary":"方程式每一个细节都会影响ΔH。","items":[{"label":"物态必须写","rule":"同一物质气、液、固态焓不同，因此必须标(g)、(l)、(s)、(aq)。","examples":["H₂O(l)与H₂O(g)对应的反应热不同。","【示范：同一个热化学方程式三种写法】H₂(g)+1/2O₂(g)=H₂O(l) ΔH=-a；反向写时ΔH=+a；整体乘2时ΔH=-2a。若H₂O写成气态，状态变化使ΔH数值不同。"],"visualSteps":["物态必须写","物态完整","方向变号","倍乘同步","单位与条件"]},{"label":"系数可以是分数","rule":"系数表示物质的量和反应进度，可以用分数；整式倍乘k，ΔH也乘k。","examples":["【示范：同一个热化学方程式三种写法】H₂(g)+1/2O₂(g)=H₂O(l) ΔH=-a；反向写时ΔH=+a；整体乘2时ΔH=-2a。若H₂O写成气态，状态变化使ΔH数值不同。"],"visualSteps":["系数可以是分数","物态完整","方向变号","倍乘同步","单位与条件"]},{"label":"反向要变号","rule":"反应逆写，始终态交换，ΔH数值大小不变而符号相反。","examples":["【示范：同一个热化学方程式三种写法】H₂(g)+1/2O₂(g)=H₂O(l) ΔH=-a；反向写时ΔH=+a；整体乘2时ΔH=-2a。若H₂O写成气态，状态变化使ΔH数值不同。"],"visualSteps":["反向要变号","物态完整","方向变号","倍乘同步","单位与条件"]},{"label":"条件与数值完整","rule":"温度、压强若影响状态或数值应注明，ΔH要带正负号和单位。","examples":["【示范：同一个热化学方程式三种写法】H₂(g)+1/2O₂(g)=H₂O(l) ΔH=-a；反向写时ΔH=+a；整体乘2时ΔH=-2a。若H₂O写成气态，状态变化使ΔH数值不同。"],"visualSteps":["条件与数值完整","物态完整","方向变号","倍乘同步","单位与条件"]}]},{"title":"盖斯定律与反应热计算","summary":"把目标反应看成已知反应式的拼图。","items":[{"label":"先写目标反应","rule":"把目标反应物、生成物、物态和系数写完整，避免只在脑中拼。","examples":["【示范：两步反应拼目标反应】先写目标C+1/2O₂=CO；将C+O₂=CO₂与CO₂=CO+1/2O₂相加，消去CO₂。第二个式子若来自已知式的逆反应，ΔH先变号，再作代数和。"],"visualSteps":["先写目标反应","写目标","逐式反向/倍乘","消去中间物","核对总式"]},{"label":"逐式变形","rule":"某式倒转则ΔH变号；某式乘k则ΔH乘k；多式相加后相同物质代数消去。","examples":["【示范：两步反应拼目标反应】先写目标C+1/2O₂=CO；将C+O₂=CO₂与CO₂=CO+1/2O₂相加，消去CO₂。第二个式子若来自已知式的逆反应，ΔH先变号，再作代数和。"],"visualSteps":["逐式变形","写目标","逐式反向/倍乘","消去中间物","核对总式"]},{"label":"最后整体核对","rule":"合成后的总反应必须与目标反应完全一致，ΔH再做同样的代数和。","examples":["【示范：两步反应拼目标反应】先写目标C+1/2O₂=CO；将C+O₂=CO₂与CO₂=CO+1/2O₂相加，消去CO₂。第二个式子若来自已知式的逆反应，ΔH先变号，再作代数和。"],"visualSteps":["最后整体核对","写目标","逐式反向/倍乘","消去中间物","核对总式"]},{"label":"其他常见计算","rule":"可结合燃烧热、中和热、键能或能量图，但定义的反应物量和生成物状态必须满足题设。","examples":["【示范：两步反应拼目标反应】先写目标C+1/2O₂=CO；将C+O₂=CO₂与CO₂=CO+1/2O₂相加，消去CO₂。第二个式子若来自已知式的逆反应，ΔH先变号，再作代数和。"],"visualSteps":["其他常见计算","写目标","逐式反向/倍乘","消去中间物","核对总式"]}]},{"title":"实验测反应热的逻辑","summary":"测温差只是手段，目标是体系释放或吸收的热量。","items":[{"label":"核心关系","rule":"一定近似下q=mcΔT，再按反应进度换算摩尔反应热。","examples":["【示范：量热杯测中和热】记录酸碱混合前温度和混合后最高温度，用q=mcΔT求溶液吸热，再取相反号并按实际反应的n换算摩尔反应热。若保温差导致散热，ΔT偏小，测得放热绝对值偏小。"],"visualSteps":["核心关系","准确测温","q=mcΔT","按反应进度换算","误差沿公式判断"]},{"label":"减少散热","rule":"使用保温容器、迅速混合、及时读最高或最低温度，减少与环境热交换。","examples":["【示范：量热杯测中和热】记录酸碱混合前温度和混合后最高温度，用q=mcΔT求溶液吸热，再取相反号并按实际反应的n换算摩尔反应热。若保温差导致散热，ΔT偏小，测得放热绝对值偏小。"],"visualSteps":["减少散热","准确测温","q=mcΔT","按反应进度换算","误差沿公式判断"]},{"label":"误差方向","rule":"若放热实验散热，测得温升偏小，计算的放热绝对值通常偏小。","caution":"ΔH为负时要区分“数值偏大”和“绝对值偏小”。","examples":["【示范：量热杯测中和热】记录酸碱混合前温度和混合后最高温度，用q=mcΔT求溶液吸热，再取相反号并按实际反应的n换算摩尔反应热。若保温差导致散热，ΔT偏小，测得放热绝对值偏小。"],"visualSteps":["误差方向","准确测温","q=mcΔT","按反应进度换算","误差沿公式判断"]}]}],"workedExamples":[{"substance":"H₂燃烧的能量账","path":"把H₂和O₂看作体系：生成液态水时体系向环境放热，H(生成物)<H(反应物)，所以ΔH<0。能量图的峰表示活化能，始末高度差才是ΔH。","labels":["划分体系环境","判断热量方向","生成物减反应物","区分活化能"]},{"substance":"H₂+Cl₂→2HCl的键能估算","path":"先断1 mol H—H和1 mol Cl—Cl键吸热，再形成2 mol H—Cl键放热；ΔH≈断键总能量−成键总能量。若成键放热的绝对值更大，结果为负。","labels":["数断裂键","数形成键","断键减成键","判正负"]},{"substance":"同一个热化学方程式三种写法","path":"H₂(g)+1/2O₂(g)=H₂O(l) ΔH=-a；反向写时ΔH=+a；整体乘2时ΔH=-2a。若H₂O写成气态，状态变化使ΔH数值不同。","labels":["物态完整","方向变号","倍乘同步","单位与条件"]},{"substance":"两步反应拼目标反应","path":"先写目标C+1/2O₂=CO；将C+O₂=CO₂与CO₂=CO+1/2O₂相加，消去CO₂。第二个式子若来自已知式的逆反应，ΔH先变号，再作代数和。","labels":["写目标","逐式反向/倍乘","消去中间物","核对总式"]},{"substance":"量热杯测中和热","path":"记录酸碱混合前温度和混合后最高温度，用q=mcΔT求溶液吸热，再取相反号并按实际反应的n换算摩尔反应热。若保温差导致散热，ΔT偏小，测得放热绝对值偏小。","labels":["准确测温","q=mcΔT","按反应进度换算","误差沿公式判断"]},{"substance":"反应式整体乘2","path":"若H₂(g)+1/2O₂(g)=H₂O(l) ΔH=-a kJ·mol⁻¹，则2H₂(g)+O₂(g)=2H₂O(l)表示双倍反应进度，ΔH=-2a kJ·mol⁻¹。","labels":["方向不变","系数×2","ΔH×2"]},{"substance":"用盖斯定律求C生成CO","path":"目标C+1/2O₂=CO。用C+O₂=CO₂减去CO+1/2O₂=CO₂；第二式需反向，故目标ΔH=ΔH₁−ΔH₂。","labels":["先写目标","反向变号","相加消去CO₂"]}],"checkpoints":["我能从能量图判断ΔH正负。","我会同时检查热化学方程式的物态、方向和倍数。","我能解释催化剂为什么不改变ΔH。","我能把盖斯定律写成反应式和ΔH同步运算。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H2_THERMO' and skill_id = 'H2_THERMO';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H2_RATE","version":2,"intro":"化学反应速率回答“反应有多快”，不是“最后能进行到什么程度”。先学会用浓度变化表示平均速率，再用有效碰撞解释浓度、压强、温度、催化剂等因素。","overview":["平均速率v=|Δc|/Δt，通常取正值；必须写明用哪一种物质表示。","同一反应中，不同物质表示的速率之比等于化学计量数之比。","浓度或气体分压影响碰撞频率；温度显著影响活化分子比例；催化剂降低反应途径的活化能。","速率变化与平衡移动要分开：反应可以变快但平衡组成不变。"],"sections":[{"title":"速率的定义和计算","summary":"先统一物质、时间和单位，再比较。","items":[{"label":"平均反应速率","rule":"一段时间内某物质浓度变化的绝对值与时间间隔之比，v=|Δc|/Δt。","examples":["常用单位mol·L⁻¹·s⁻¹或mol·L⁻¹·min⁻¹。","【示范：用浓度变化算平均速率】某反应中A在20 s内由0.80降至0.40 mol·L⁻¹，则v(A)=|0.40-0.80|/20=0.020 mol·L⁻¹·s⁻¹。反应物也取正值；固体本身不用浓度变化表示。"],"visualSteps":["平均反应速率","确定时间段","浓度变化取绝对值","除以时间","单位完整"]},{"label":"反应物和生成物都取正值","rule":"反应物浓度下降、生成物浓度上升；中学比较速率时通常取变化量绝对值。","examples":["【示范：用浓度变化算平均速率】某反应中A在20 s内由0.80降至0.40 mol·L⁻¹，则v(A)=|0.40-0.80|/20=0.020 mol·L⁻¹·s⁻¹。反应物也取正值；固体本身不用浓度变化表示。"],"visualSteps":["反应物和生成物都取正值","确定时间段","浓度变化取绝对值","除以时间","单位完整"]},{"label":"固体和纯液体","rule":"其“浓度”视为常数，通常不用它们的浓度变化表示速率；可用气体体积、质量等实验量间接反映。","examples":["【示范：用浓度变化算平均速率】某反应中A在20 s内由0.80降至0.40 mol·L⁻¹，则v(A)=|0.40-0.80|/20=0.020 mol·L⁻¹·s⁻¹。反应物也取正值；固体本身不用浓度变化表示。"],"visualSteps":["固体和纯液体","确定时间段","浓度变化取绝对值","除以时间","单位完整"]}]},{"title":"不同物质的速率怎样换算","summary":"系数不同，数值不同，但描述的是同一个反应进程。","items":[{"label":"计量数关系","rule":"对aA+bB→cC+dD，有v(A):v(B):v(C):v(D)=a:b:c:d。","examples":["【示范：N₂+3H₂→2NH₃的速率换算】若v(N₂)=0.20 mol·L⁻¹·s⁻¹，则v(H₂)=0.60、v(NH₃)=0.40；比较“反应快慢”时可把各自速率除以对应计量数，得到同一个归一化速率。"],"visualSteps":["计量数关系","读计量系数","按比例换算","统一单位","必要时归一化"]},{"label":"归一化比较","rule":"若要比较不同反应或不同表示物，应使用v/计量数或题目定义的统一反应速率。","examples":["【示范：N₂+3H₂→2NH₃的速率换算】若v(N₂)=0.20 mol·L⁻¹·s⁻¹，则v(H₂)=0.60、v(NH₃)=0.40；比较“反应快慢”时可把各自速率除以对应计量数，得到同一个归一化速率。"],"visualSteps":["归一化比较","读计量系数","按比例换算","统一单位","必要时归一化"]},{"label":"三段式辅助","rule":"列起始浓度、变化浓度、某时刻浓度，再由变化量和时间计算。","examples":["【示范：N₂+3H₂→2NH₃的速率换算】若v(N₂)=0.20 mol·L⁻¹·s⁻¹，则v(H₂)=0.60、v(NH₃)=0.40；比较“反应快慢”时可把各自速率除以对应计量数，得到同一个归一化速率。"],"visualSteps":["三段式辅助","读计量系数","按比例换算","统一单位","必要时归一化"]}]},{"title":"有效碰撞模型","summary":"只有方向合适且能量足够的碰撞才可能导致反应。","items":[{"label":"活化分子与有效碰撞","rule":"具有足够能量的粒子更可能跨越能垒；碰撞方向也要合适。","examples":["【示范：为什么升温通常明显加快反应】升温后粒子平均动能增大，超过活化能的粒子比例明显增加，且合适方向的有效碰撞增多；所以不能只写“分子运动变快”。"],"visualSteps":["活化分子与有效碰撞","粒子能量变化","活化分子比例","有效碰撞次数","宏观速率"]},{"label":"活化能","rule":"从反应物状态到过渡区域所需跨越的最低能垒。活化能越低，在同温度下通常越易反应。","examples":["【示范：为什么升温通常明显加快反应】升温后粒子平均动能增大，超过活化能的粒子比例明显增加，且合适方向的有效碰撞增多；所以不能只写“分子运动变快”。"],"visualSteps":["活化能","粒子能量变化","活化分子比例","有效碰撞次数","宏观速率"]},{"label":"微观解释要求","rule":"回答影响因素时要说清“哪个量改变—有效碰撞怎样改变—速率怎样变”。","examples":["【示范：为什么升温通常明显加快反应】升温后粒子平均动能增大，超过活化能的粒子比例明显增加，且合适方向的有效碰撞增多；所以不能只写“分子运动变快”。"],"visualSteps":["微观解释要求","粒子能量变化","活化分子比例","有效碰撞次数","宏观速率"]}]},{"title":"常见因素逐一解释","summary":"不要用同一句“分子运动加快”解释所有因素。","items":[{"label":"浓度","rule":"溶液反应物浓度增大，单位体积内反应粒子数增多，碰撞频率通常增大。","examples":["【示范：大理石与盐酸的控制变量组】分别改变HCl浓度、温度、大理石颗粒大小；每组只改一个因素并用相同体积CO₂所需时间比较。粉碎增大接触面积，升温提高活化分子比例，增浓度提高碰撞频率。"],"visualSteps":["浓度","一次只改一项","浓度","温度","接触面积"]},{"label":"气体压强","rule":"恒温压缩使气体体积减小、反应组分浓度或分压增大，速率通常增大；恒容加惰性气体时反应组分浓度不变。","examples":["【示范：大理石与盐酸的控制变量组】分别改变HCl浓度、温度、大理石颗粒大小；每组只改一个因素并用相同体积CO₂所需时间比较。粉碎增大接触面积，升温提高活化分子比例，增浓度提高碰撞频率。"],"visualSteps":["气体压强","一次只改一项","浓度","温度","接触面积"]},{"label":"温度","rule":"升温使粒子平均动能增大，更重要的是活化分子百分数显著增大，有效碰撞增多。","examples":["【示范：大理石与盐酸的控制变量组】分别改变HCl浓度、温度、大理石颗粒大小；每组只改一个因素并用相同体积CO₂所需时间比较。粉碎增大接触面积，升温提高活化分子比例，增浓度提高碰撞频率。"],"visualSteps":["温度","一次只改一项","浓度","温度","接触面积"]},{"label":"催化剂","rule":"提供活化能较低的新途径，同时加快正、逆反应；不改变反应物和生成物能量差，也不改变平衡常数。","examples":["【示范：大理石与盐酸的控制变量组】分别改变HCl浓度、温度、大理石颗粒大小；每组只改一个因素并用相同体积CO₂所需时间比较。粉碎增大接触面积，升温提高活化分子比例，增浓度提高碰撞频率。"],"visualSteps":["催化剂","一次只改一项","浓度","温度","接触面积"]},{"label":"接触面积","rule":"固体粉碎后接触面积增大，暴露的反应位点增多，非均相反应通常加快。","examples":["【示范：大理石与盐酸的控制变量组】分别改变HCl浓度、温度、大理石颗粒大小；每组只改一个因素并用相同体积CO₂所需时间比较。粉碎增大接触面积，升温提高活化分子比例，增浓度提高碰撞频率。"],"visualSteps":["接触面积","一次只改一项","浓度","温度","接触面积"]}]},{"title":"图像与探究实验","summary":"图像先读轴，实验先控变量。","items":[{"label":"浓度—时间图","rule":"曲线斜率绝对值反映瞬时速率；曲线越陡，速率越快；达到平台不一定说明反应物耗尽，也可能达到平衡。","examples":["【示范：读浓度图和能量图】浓度—时间曲线起初最陡，说明初速最大，后来变平说明速率减慢；能量图加催化剂后峰降低但始末位置不变。探究时用相同反应进度所需时间作可比指标。"],"visualSteps":["浓度—时间图","先认横纵轴","斜率看速率","峰高看活化能","控制变量"]},{"label":"能量—反应历程图","rule":"峰高对应活化能；有催化剂的路径峰更低，始态终态和ΔH不变。","examples":["【示范：读浓度图和能量图】浓度—时间曲线起初最陡，说明初速最大，后来变平说明速率减慢；能量图加催化剂后峰降低但始末位置不变。探究时用相同反应进度所需时间作可比指标。"],"visualSteps":["能量—反应历程图","先认横纵轴","斜率看速率","峰高看活化能","控制变量"]},{"label":"控制变量","rule":"探究某因素时只改变该因素，其他条件尽量相同；用相同反应进度所需时间或单位时间变化量比较。","examples":["【示范：读浓度图和能量图】浓度—时间曲线起初最陡，说明初速最大，后来变平说明速率减慢；能量图加催化剂后峰降低但始末位置不变。探究时用相同反应进度所需时间作可比指标。"],"visualSteps":["控制变量","先认横纵轴","斜率看速率","峰高看活化能","控制变量"]}]}],"workedExamples":[{"substance":"用浓度变化算平均速率","path":"某反应中A在20 s内由0.80降至0.40 mol·L⁻¹，则v(A)=|0.40-0.80|/20=0.020 mol·L⁻¹·s⁻¹。反应物也取正值；固体本身不用浓度变化表示。","labels":["确定时间段","浓度变化取绝对值","除以时间","单位完整"]},{"substance":"N₂+3H₂→2NH₃的速率换算","path":"若v(N₂)=0.20 mol·L⁻¹·s⁻¹，则v(H₂)=0.60、v(NH₃)=0.40；比较“反应快慢”时可把各自速率除以对应计量数，得到同一个归一化速率。","labels":["读计量系数","按比例换算","统一单位","必要时归一化"]},{"substance":"为什么升温通常明显加快反应","path":"升温后粒子平均动能增大，超过活化能的粒子比例明显增加，且合适方向的有效碰撞增多；所以不能只写“分子运动变快”。","labels":["粒子能量变化","活化分子比例","有效碰撞次数","宏观速率"]},{"substance":"大理石与盐酸的控制变量组","path":"分别改变HCl浓度、温度、大理石颗粒大小；每组只改一个因素并用相同体积CO₂所需时间比较。粉碎增大接触面积，升温提高活化分子比例，增浓度提高碰撞频率。","labels":["一次只改一项","浓度","温度","接触面积"]},{"substance":"读浓度图和能量图","path":"浓度—时间曲线起初最陡，说明初速最大，后来变平说明速率减慢；能量图加催化剂后峰降低但始末位置不变。探究时用相同反应进度所需时间作可比指标。","labels":["先认横纵轴","斜率看速率","峰高看活化能","控制变量"]},{"substance":"恒容充入He","path":"容器体积和反应组分物质的量不变，所以反应组分浓度、分压均不变，正逆速率不因He直接改变；总压增大不等于有效压缩。","labels":["看分压而非总压","恒容","速率基本不变"]}],"checkpoints":["我能用v=|Δc|/Δt计算并写对单位。","我会用计量数换算不同物质表示的速率。","我能分别解释浓度、温度和催化剂的微观原因。","我不会把“反应加快”自动说成“平衡向右移动”。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H2_RATE' and skill_id = 'H2_RATE';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H2_EQUIL","version":2,"intro":"化学平衡只出现在一定条件下的可逆反应中。达到平衡不是反应停止，而是正逆反应仍在进行且速率相等；条件改变后，先看瞬间速率，再看移动方向和新平衡。","overview":["平衡标志：同一物理量正逆方向对应的速率相等，各组分含量保持不变。","移动方向由v正与v逆的瞬间大小决定：v正>v逆向右，v正<v逆向左。","浓度、压强、温度可改变平衡；催化剂只缩短到达平衡的时间。","勒夏特列原理说的是“减弱改变”，不是“完全抵消改变”。"],"sections":[{"title":"可逆反应与动态平衡","summary":"先确定这个体系是否真的可以谈平衡。","items":[{"label":"可逆反应","rule":"同一条件下既能向正方向又能向逆方向进行，用可逆号表示；反应物和生成物共存。","examples":["【示范：N₂和H₂怎样建立平衡】密闭容器中开始只有N₂、H₂，v正大而v逆近0；NH₃增加后v逆上升，直到v正=v逆且都不为0，N₂、H₂、NH₃浓度保持不变。"],"visualSteps":["可逆反应","可逆反应共存","正逆速率变化","速率相等","组成不变"]},{"label":"平衡建立","rule":"起初v正较大、v逆较小；随组成变化，v正减小、v逆增大，直到相等。","examples":["【示范：N₂和H₂怎样建立平衡】密闭容器中开始只有N₂、H₂，v正大而v逆近0；NH₃增加后v逆上升，直到v正=v逆且都不为0，N₂、H₂、NH₃浓度保持不变。"],"visualSteps":["平衡建立","可逆反应共存","正逆速率变化","速率相等","组成不变"]},{"label":"动态与定态","rule":"平衡时v正=v逆且均不为0，宏观组成保持不变。","caution":"“各物质浓度相等”不是平衡必要条件。","examples":["【示范：N₂和H₂怎样建立平衡】密闭容器中开始只有N₂、H₂，v正大而v逆近0；NH₃增加后v逆上升，直到v正=v逆且都不为0，N₂、H₂、NH₃浓度保持不变。"],"visualSteps":["动态与定态","可逆反应共存","正逆速率变化","速率相等","组成不变"]}]},{"title":"怎样判断达到平衡","summary":"标志必须指向同一反应的正逆过程相等或某组成量不再变化。","items":[{"label":"直接标志","rule":"v正=v逆，但若用不同物质表示，要按计量数换算后再比较。","examples":["【示范：颜色不再变化能否判平衡】对2NO₂⇌N₂O₄，若温度体积固定，颜色持续不变可表示NO₂浓度不再变，是平衡标志；若某总量在整个反应中本来就不变，则它“不变”不能作标志。"],"visualSteps":["直接标志","选会随进程变化的量","保持不变","排除恒定总量","回到v正=v逆"]},{"label":"间接标志","rule":"某反应物或生成物的浓度、物质的量分数、颜色等保持不变。","examples":["【示范：颜色不再变化能否判平衡】对2NO₂⇌N₂O₄，若温度体积固定，颜色持续不变可表示NO₂浓度不再变，是平衡标志；若某总量在整个反应中本来就不变，则它“不变”不能作标志。"],"visualSteps":["间接标志","选会随进程变化的量","保持不变","排除恒定总量","回到v正=v逆"]},{"label":"不可靠表述","rule":"总物质的量、总压、密度或平均摩尔质量只有在该反应中会随进程改变时，保持不变才可作标志。","examples":["【示范：颜色不再变化能否判平衡】对2NO₂⇌N₂O₄，若温度体积固定，颜色持续不变可表示NO₂浓度不再变，是平衡标志；若某总量在整个反应中本来就不变，则它“不变”不能作标志。"],"visualSteps":["不可靠表述","选会随进程变化的量","保持不变","排除恒定总量","回到v正=v逆"]}]},{"title":"条件改变后的三层判断","summary":"瞬间、移动过程、新平衡不能混成一句话。","items":[{"label":"第一层：瞬间速率","rule":"浓度变化会直接改变涉及该物质方向的速率；温度通常同时改变正逆速率且影响程度可不同；催化剂同时加快正逆反应，在原平衡点二者仍相等，不引起平衡移动。","examples":["【示范：升温后的三层过程】放热正反应升温瞬间正逆速率都增大，但逆反应增幅更大，出现v逆>v正；组成向逆向改变，直到新平衡v正=v逆。"],"visualSteps":["第一层：瞬间速率","瞬间速率跳变","判断净方向","组成逐步变化","建立新平衡"]},{"label":"第二层：移动方向","rule":"比较条件改变瞬间的v正和v逆；较大的一侧决定净反应方向。","examples":["【示范：升温后的三层过程】放热正反应升温瞬间正逆速率都增大，但逆反应增幅更大，出现v逆>v正；组成向逆向改变，直到新平衡v正=v逆。"],"visualSteps":["第二层：移动方向","瞬间速率跳变","判断净方向","组成逐步变化","建立新平衡"]},{"label":"第三层：新平衡","rule":"组成逐渐变化直到v正再次等于v逆；新平衡速率和旧平衡不一定相同。","examples":["【示范：升温后的三层过程】放热正反应升温瞬间正逆速率都增大，但逆反应增幅更大，出现v逆>v正；组成向逆向改变，直到新平衡v正=v逆。"],"visualSteps":["第三层：新平衡","瞬间速率跳变","判断净方向","组成逐步变化","建立新平衡"]}]},{"title":"浓度、压强、温度和催化剂","summary":"先明确改变作用在哪个变量上。","items":[{"label":"浓度","rule":"增加反应物或移走生成物通常使平衡向正方向移动；纯固体或纯液体的量在仍有固相时通常不写成浓度影响。","examples":["【示范：N₂+3H₂⇌2NH₃逐个改条件】加N₂通常右移；恒温压缩向气体计量数少的右侧移动；升温因正向放热而左移；催化剂只缩短达平衡时间；恒容加He时反应气体分压不变，通常不移。"],"visualSteps":["浓度","浓度","压强","温度","催化剂与惰性气体"]},{"label":"压强","rule":"恒温改变体积时，只对有气体参加且两侧气体计量数和不同的平衡有方向性影响；增压偏向气体物质的量较少一侧。","examples":["【示范：N₂+3H₂⇌2NH₃逐个改条件】加N₂通常右移；恒温压缩向气体计量数少的右侧移动；升温因正向放热而左移；催化剂只缩短达平衡时间；恒容加He时反应气体分压不变，通常不移。"],"visualSteps":["压强","浓度","压强","温度","催化剂与惰性气体"]},{"label":"温度","rule":"把热量看作反应的一项：升温有利于吸热方向，降温有利于放热方向；温度还会改变K。","examples":["【示范：N₂+3H₂⇌2NH₃逐个改条件】加N₂通常右移；恒温压缩向气体计量数少的右侧移动；升温因正向放热而左移；催化剂只缩短达平衡时间；恒容加He时反应气体分压不变，通常不移。"],"visualSteps":["温度","浓度","压强","温度","催化剂与惰性气体"]},{"label":"催化剂","rule":"同等意义上加快正逆反应，使更快达到平衡，但不改变平衡组成和K。","examples":["【示范：N₂+3H₂⇌2NH₃逐个改条件】加N₂通常右移；恒温压缩向气体计量数少的右侧移动；升温因正向放热而左移；催化剂只缩短达平衡时间；恒容加He时反应气体分压不变，通常不移。"],"visualSteps":["催化剂","浓度","压强","温度","催化剂与惰性气体"]},{"label":"惰性气体","rule":"恒容加入时反应组分浓度/分压不变，通常不移动；恒压加入导致体积增大、分压减小，等效于减压再判断。","examples":["【示范：N₂+3H₂⇌2NH₃逐个改条件】加N₂通常右移；恒温压缩向气体计量数少的右侧移动；升温因正向放热而左移；催化剂只缩短达平衡时间；恒容加He时反应气体分压不变，通常不移。"],"visualSteps":["惰性气体","浓度","压强","温度","催化剂与惰性气体"]}]},{"title":"勒夏特列原理与工业条件","summary":"平衡、速率、成本和安全往往需要折中。","items":[{"label":"减弱而非抵消","rule":"体系移动会减弱外界改变，但不可能把改变后的量完全恢复到原值。","examples":["【示范：合成氨条件为什么要折中】低温有利于放热正反应的平衡转化率，却使速率慢；高压有利于右移但设备成本和风险上升；催化剂提高速率而不改平衡组成，所以工业条件兼顾产率、速率、成本和安全。"],"visualSteps":["减弱而非抵消","减弱外界改变","适用可逆平衡","速率限度分开","工业多目标"]},{"label":"不能脱离可逆平衡","rule":"原理用于已达到或可达到平衡的体系，不用于解释所有化学现象。","examples":["【示范：合成氨条件为什么要折中】低温有利于放热正反应的平衡转化率，却使速率慢；高压有利于右移但设备成本和风险上升；催化剂提高速率而不改平衡组成，所以工业条件兼顾产率、速率、成本和安全。"],"visualSteps":["不能脱离可逆平衡","减弱外界改变","适用可逆平衡","速率限度分开","工业多目标"]},{"label":"工业折中","rule":"选择温度、压强和催化剂时要兼顾平衡转化率、反应速率、设备成本和安全；不要求死背精确工业参数。","examples":["【示范：合成氨条件为什么要折中】低温有利于放热正反应的平衡转化率，却使速率慢；高压有利于右移但设备成本和风险上升；催化剂提高速率而不改平衡组成，所以工业条件兼顾产率、速率、成本和安全。"],"visualSteps":["工业折中","减弱外界改变","适用可逆平衡","速率限度分开","工业多目标"]}]}],"workedExamples":[{"substance":"N₂和H₂怎样建立平衡","path":"密闭容器中开始只有N₂、H₂，v正大而v逆近0；NH₃增加后v逆上升，直到v正=v逆且都不为0，N₂、H₂、NH₃浓度保持不变。","labels":["可逆反应共存","正逆速率变化","速率相等","组成不变"]},{"substance":"颜色不再变化能否判平衡","path":"对2NO₂⇌N₂O₄，若温度体积固定，颜色持续不变可表示NO₂浓度不再变，是平衡标志；若某总量在整个反应中本来就不变，则它“不变”不能作标志。","labels":["选会随进程变化的量","保持不变","排除恒定总量","回到v正=v逆"]},{"substance":"升温后的三层过程","path":"放热正反应升温瞬间正逆速率都增大，但逆反应增幅更大，出现v逆>v正；组成向逆向改变，直到新平衡v正=v逆。","labels":["瞬间速率跳变","判断净方向","组成逐步变化","建立新平衡"]},{"substance":"N₂+3H₂⇌2NH₃逐个改条件","path":"加N₂通常右移；恒温压缩向气体计量数少的右侧移动；升温因正向放热而左移；催化剂只缩短达平衡时间；恒容加He时反应气体分压不变，通常不移。","labels":["浓度","压强","温度","催化剂与惰性气体"]},{"substance":"合成氨条件为什么要折中","path":"低温有利于放热正反应的平衡转化率，却使速率慢；高压有利于右移但设备成本和风险上升；催化剂提高速率而不改平衡组成，所以工业条件兼顾产率、速率、成本和安全。","labels":["减弱外界改变","适用可逆平衡","速率限度分开","工业多目标"]},{"substance":"放热反应升高温度","path":"升温瞬间正逆速率都增大，但吸热的逆反应增大得更多，于是v逆>v正，平衡向逆方向移动；达到新平衡后K减小。","labels":["先瞬间速率","再移动","温度改变K"]},{"substance":"N₂+3H₂⇌2NH₃恒温压缩","path":"体积减小使各气体分压增大；平衡移动会减弱压强增加，故向气体计量数较少的右侧移动。催化剂只加快到达新平衡。","labels":["左4份气体","右2份气体","增压右移"]}],"checkpoints":["我能解释“动态平衡”而不是说反应停止。","我会把瞬间速率、移动方向、新平衡分开描述。","我知道压强影响的适用条件。","我能区分恒容和恒压加入惰性气体。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H2_EQUIL' and skill_id = 'H2_EQUIL';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H2_K","version":2,"intro":"平衡常数K把“平衡时各组分的数量关系”写成一个数。对确定反应式，K在一定温度下固定；Q描述任意时刻的组成，比较Q和K即可判断体系向哪边变化。","overview":["K表达式按平衡浓度或分压的计量数次方相乘；纯固体、纯液体通常不写。","一定温度、确定反应式下K不因初始浓度、压强或催化剂改变。","Q<K向正方向，Q>K向逆方向，Q=K处于平衡。","三段式按“起始—变化—平衡”列量，变化量必须服从化学计量数。"],"sections":[{"title":"K表达式从反应式直接生成","summary":"先写清反应式，再写K。","items":[{"label":"浓度平衡常数Kc","rule":"对aA+bB⇌cC+dD，Kc=c(C)^c·c(D)^d/[c(A)^a·c(B)^b]，所有浓度取平衡值。","examples":["【示范：为A+B⇌2C写K】Kc=c²(C)/[c(A)c(B)]，代入的都是平衡浓度；纯固体、纯液体通常不写。反应倒转时K变1/K，系数整体乘2时K变K²。"],"visualSteps":["浓度平衡常数Kc","由反应式写表达式","平衡浓度","物态筛选","式子变K跟着变"]},{"label":"省略纯固体和纯液体","rule":"它们的有效浓度视为常数，已包含在K中。","examples":["CaCO₃(s)⇌CaO(s)+CO₂(g)，Kc=c(CO₂)。","【示范：为A+B⇌2C写K】Kc=c²(C)/[c(A)c(B)]，代入的都是平衡浓度；纯固体、纯液体通常不写。反应倒转时K变1/K，系数整体乘2时K变K²。"],"visualSteps":["省略纯固体和纯液体","由反应式写表达式","平衡浓度","物态筛选","式子变K跟着变"]},{"label":"反应式变化","rule":"反应逆写，K变为1/K；系数乘n，K变为Kⁿ；反应相加，对应K相乘。","examples":["【示范：为A+B⇌2C写K】Kc=c²(C)/[c(A)c(B)]，代入的都是平衡浓度；纯固体、纯液体通常不写。反应倒转时K变1/K，系数整体乘2时K变K²。"],"visualSteps":["反应式变化","由反应式写表达式","平衡浓度","物态筛选","式子变K跟着变"]}]},{"title":"K能说明什么、不能说明什么","summary":"K描述限度，不直接描述速度。","items":[{"label":"K大小与平衡倾向","rule":"在同一形式、同一温度下，K较大通常表示平衡时生成物相对占优。","examples":["【示范：K大不等于反应快】两个反应在同温下都可能有很大的K，但其中一个因活化能高而几乎观察不到；加入催化剂可使其更快达到平衡，却不会改变K。"],"visualSteps":["K大小与平衡倾向","K看限度","速率看动力学","温度决定K","催化剂不改K"]},{"label":"K只随温度改变","rule":"浓度、体积、压强、催化剂能改变组成或达到平衡的时间，但同温下K不变。","examples":["【示范：K大不等于反应快】两个反应在同温下都可能有很大的K，但其中一个因活化能高而几乎观察不到；加入催化剂可使其更快达到平衡，却不会改变K。"],"visualSteps":["K只随温度改变","K看限度","速率看动力学","温度决定K","催化剂不改K"]},{"label":"K不等于反应速率","rule":"K很大的反应仍可能因为活化能高而进行缓慢；催化剂可加快但不改变K。","examples":["【示范：K大不等于反应快】两个反应在同温下都可能有很大的K，但其中一个因活化能高而几乎观察不到；加入催化剂可使其更快达到平衡，却不会改变K。"],"visualSteps":["K不等于反应速率","K看限度","速率看动力学","温度决定K","催化剂不改K"]}]},{"title":"反应商Q判断方向","summary":"把“当前值”代入与K同形式的表达式。","items":[{"label":"Q<K","rule":"当前生成物相对不足，净反应向正方向，使Q增大到K。","examples":["【示范：Q与K的三种位置】对A+B⇌C，若K=10：Q=2时Q<K向右；Q=20时Q>K向左；Q=10时满足平衡关系。Q必须与K使用同一个反应式和同一种表达形式。"],"visualSteps":["Q<K","写同形Q","算当前值","与K比较","判净方向"]},{"label":"Q>K","rule":"当前生成物相对过多，净反应向逆方向，使Q减小到K。","examples":["【示范：Q与K的三种位置】对A+B⇌C，若K=10：Q=2时Q<K向右；Q=20时Q>K向左；Q=10时满足平衡关系。Q必须与K使用同一个反应式和同一种表达形式。"],"visualSteps":["Q>K","写同形Q","算当前值","与K比较","判净方向"]},{"label":"Q=K","rule":"在该温度下组成满足平衡关系；若体系条件允许，则处于平衡。","examples":["【示范：Q与K的三种位置】对A+B⇌C，若K=10：Q=2时Q<K向右；Q=20时Q>K向左；Q=10时满足平衡关系。Q必须与K使用同一个反应式和同一种表达形式。"],"visualSteps":["Q=K","写同形Q","算当前值","与K比较","判净方向"]}]},{"title":"三段式计算","summary":"所有量必须用同一基准，变化量服从系数比。","items":[{"label":"起始行","rule":"写反应开始时各物质的浓度或物质的量；没有的物质写0。","examples":["【示范：A⇌B的三段式】初始c(A)=1.0、c(B)=0，设转化x，则变化为-x、+x，平衡为1.0-x、x；若K=4，解x/(1.0-x)=4得x=0.80，并检查0≤x≤1.0。"],"visualSteps":["起始行","起始行","变化按系数","平衡行","验根"]},{"label":"变化行","rule":"设一个反应进度x，按计量数写±ax、±bx、±cx、±dx。","examples":["【示范：A⇌B的三段式】初始c(A)=1.0、c(B)=0，设转化x，则变化为-x、+x，平衡为1.0-x、x；若K=4，解x/(1.0-x)=4得x=0.80，并检查0≤x≤1.0。"],"visualSteps":["变化行","起始行","变化按系数","平衡行","验根"]},{"label":"平衡行","rule":"起始量加变化量，代入K；解出的x必须使所有实际量非负。","examples":["【示范：A⇌B的三段式】初始c(A)=1.0、c(B)=0，设转化x，则变化为-x、+x，平衡为1.0-x、x；若K=4，解x/(1.0-x)=4得x=0.80，并检查0≤x≤1.0。"],"visualSteps":["平衡行","起始行","变化按系数","平衡行","验根"]},{"label":"容器体积","rule":"若用物质的量列三段式而K要求浓度，要除以体积；恒容且能约去时才可简化。","examples":["【示范：A⇌B的三段式】初始c(A)=1.0、c(B)=0，设转化x，则变化为-x、+x，平衡为1.0-x、x；若K=4，解x/(1.0-x)=4得x=0.80，并检查0≤x≤1.0。"],"visualSteps":["容器体积","起始行","变化按系数","平衡行","验根"]}]},{"title":"转化率、产率与条件变化","summary":"先定义分母，再计算百分比。","items":[{"label":"转化率","rule":"某反应物的转化率=已转化量/初始量×100%。","examples":["【示范：改变体积后比较新旧平衡】先由原平衡求K；改变体积瞬间用新浓度求Q，再以Q-K判方向。温度未变时K不变，但平衡组成和反应物转化率可能改变。"],"visualSteps":["转化率","先锁温度","算瞬时Q","比较Q和K","求转化率"]},{"label":"平衡组成","rule":"可由平衡浓度、物质的量分数、体积分数等表达；气体同温同压下体积分数等于物质的量分数。","examples":["【示范：改变体积后比较新旧平衡】先由原平衡求K；改变体积瞬间用新浓度求Q，再以Q-K判方向。温度未变时K不变，但平衡组成和反应物转化率可能改变。"],"visualSteps":["平衡组成","先锁温度","算瞬时Q","比较Q和K","求转化率"]},{"label":"比较新旧平衡","rule":"先判断K是否因温度改变，再用Q-K或平衡移动判断；不能把“转化率改变”误说成“K改变”。","examples":["【示范：改变体积后比较新旧平衡】先由原平衡求K；改变体积瞬间用新浓度求Q，再以Q-K判方向。温度未变时K不变，但平衡组成和反应物转化率可能改变。"],"visualSteps":["比较新旧平衡","先锁温度","算瞬时Q","比较Q和K","求转化率"]}]}],"workedExamples":[{"substance":"为A+B⇌2C写K","path":"Kc=c²(C)/[c(A)c(B)]，代入的都是平衡浓度；纯固体、纯液体通常不写。反应倒转时K变1/K，系数整体乘2时K变K²。","labels":["由反应式写表达式","平衡浓度","物态筛选","式子变K跟着变"]},{"substance":"K大不等于反应快","path":"两个反应在同温下都可能有很大的K，但其中一个因活化能高而几乎观察不到；加入催化剂可使其更快达到平衡，却不会改变K。","labels":["K看限度","速率看动力学","温度决定K","催化剂不改K"]},{"substance":"Q与K的三种位置","path":"对A+B⇌C，若K=10：Q=2时Q<K向右；Q=20时Q>K向左；Q=10时满足平衡关系。Q必须与K使用同一个反应式和同一种表达形式。","labels":["写同形Q","算当前值","与K比较","判净方向"]},{"substance":"A⇌B的三段式","path":"初始c(A)=1.0、c(B)=0，设转化x，则变化为-x、+x，平衡为1.0-x、x；若K=4，解x/(1.0-x)=4得x=0.80，并检查0≤x≤1.0。","labels":["起始行","变化按系数","平衡行","验根"]},{"substance":"改变体积后比较新旧平衡","path":"先由原平衡求K；改变体积瞬间用新浓度求Q，再以Q-K判方向。温度未变时K不变，但平衡组成和反应物转化率可能改变。","labels":["先锁温度","算瞬时Q","比较Q和K","求转化率"]},{"substance":"A⇌B，K=4的基础三段式","path":"设初始c(A)=1.0、c(B)=0，转化x，则平衡为1.0−x和x；K=x/(1.0−x)=4，解得x=0.80 mol·L⁻¹，A转化率80%。","labels":["起始","变化","平衡","验x范围"]},{"substance":"Q与K判断","path":"若反应A+B⇌C的K=10，而某时刻Q=c(C)/[c(A)c(B)]=2，则Q<K，体系向右进行，直至Q增大到10。","labels":["表达式同形","当前Q","方向"]}],"checkpoints":["我能正确决定哪些物质写入K表达式。","我能说明K为什么不随浓度改变。","我能用Q与K判断方向。","我能列完整三段式并检查数学根是否有物理意义。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H2_K' and skill_id = 'H2_K';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H2_WEAK","version":2,"intro":"弱电解质不是“不电离”，而是只部分电离并建立动态平衡。做题时要同时跟踪分子、离子、电离程度和粒子浓度，不能把“电离度增大”自动等同于“离子浓度增大”。","overview":["强弱电解质看电离程度，不看溶液浓度、导电强弱或溶解度。","弱酸HA⇌H⁺+A⁻，弱碱建立类似平衡；平衡可受浓度、温度和同离子影响。","稀释通常促进电离，电离度增大，但单位体积离子浓度可能下降。","Ka、Kb在一定温度下固定；数值越大通常表示相应酸或碱越强。"],"sections":[{"title":"强电解质与弱电解质","summary":"强弱是电离程度的分类。","items":[{"label":"强电解质","rule":"在水溶液中近乎完全电离，溶液中主要以离子存在；用等号书写。","examples":["【示范：HCl与CH₃COOH对比】HCl在水中近乎完全电离，写等号；CH₃COOH分子与H⁺、CH₃COO⁻共存，写可逆号。CaCO₃难溶但溶解部分完全电离，仍属强电解质。"],"visualSteps":["强电解质","看电离程度","强写等号","弱写可逆号","强弱不看溶解度"]},{"label":"弱电解质","rule":"只部分电离，溶液中弱电解质分子与离子共存；用可逆号书写。","examples":["CH₃COOH⇌H⁺+CH₃COO⁻。","【示范：HCl与CH₃COOH对比】HCl在水中近乎完全电离，写等号；CH₃COOH分子与H⁺、CH₃COO⁻共存，写可逆号。CaCO₃难溶但溶解部分完全电离，仍属强电解质。"],"visualSteps":["弱电解质","看电离程度","强写等号","弱写可逆号","强弱不看溶解度"]},{"label":"常见误判","rule":"难溶盐可以是强电解质；浓弱酸仍是弱电解质；稀强酸仍是强电解质。","caution":"强弱不等于导电能力大小。","examples":["【示范：HCl与CH₃COOH对比】HCl在水中近乎完全电离，写等号；CH₃COOH分子与H⁺、CH₃COO⁻共存，写可逆号。CaCO₃难溶但溶解部分完全电离，仍属强电解质。"],"visualSteps":["常见误判","看电离程度","强写等号","弱写可逆号","强弱不看溶解度"]}]},{"title":"电离平衡怎样建立","summary":"正向电离与逆向结合同时进行。","items":[{"label":"动态过程","rule":"开始以电离为主；离子增多后结合速率上升，最终电离速率等于结合速率。","examples":["【示范：醋酸电离怎样达到平衡】刚加水时以CH₃COOH电离为主；H⁺、CH₃COO⁻增多后结合速率增大，最终正逆速率相等，各粒子浓度不再宏观变化。多元弱酸通常逐级更难电离。"],"visualSteps":["动态过程","正向先快","逆向逐渐增强","动态平衡","分步电离"]},{"label":"平衡特征","rule":"一定条件下各粒子浓度保持不变，但微观过程没有停止。","examples":["【示范：醋酸电离怎样达到平衡】刚加水时以CH₃COOH电离为主；H⁺、CH₃COO⁻增多后结合速率增大，最终正逆速率相等，各粒子浓度不再宏观变化。多元弱酸通常逐级更难电离。"],"visualSteps":["平衡特征","正向先快","逆向逐渐增强","动态平衡","分步电离"]},{"label":"多元弱酸","rule":"通常分步电离且一级比一级困难；基础判断先抓第一步，具体题按题给常数或信息处理。","examples":["【示范：醋酸电离怎样达到平衡】刚加水时以CH₃COOH电离为主；H⁺、CH₃COO⁻增多后结合速率增大，最终正逆速率相等，各粒子浓度不再宏观变化。多元弱酸通常逐级更难电离。"],"visualSteps":["多元弱酸","正向先快","逆向逐渐增强","动态平衡","分步电离"]}]},{"title":"外界条件怎样影响","summary":"先判断平衡方向，再判断具体浓度和电离度。","items":[{"label":"加水稀释","rule":"平衡通常向粒子数较多的电离方向移动，电离度增大；但所有粒子都被稀释，c(H⁺)等不一定增大。","examples":["醋酸稀释：α增大，c(H⁺)通常减小，pH增大。","【示范：由Ka比较和计算弱酸】对HA⇌H⁺+A⁻，Ka=c(H⁺)c(A⁻)/c(HA)。同温同类条件下Ka较大通常酸性较强；用起始—变化—平衡列浓度，近似前要验证x相对初浓度足够小。"],"visualSteps":["加水稀释","写表达式","同温比较","三段式","近似后验算"]},{"label":"加入同离子","rule":"加入含H⁺或A⁻的物质使平衡左移，抑制弱酸电离。","examples":["【示范：由Ka比较和计算弱酸】对HA⇌H⁺+A⁻，Ka=c(H⁺)c(A⁻)/c(HA)。同温同类条件下Ka较大通常酸性较强；用起始—变化—平衡列浓度，近似前要验证x相对初浓度足够小。"],"visualSteps":["加入同离子","写表达式","同温比较","三段式","近似后验算"]},{"label":"消耗某离子","rule":"若反应移走H⁺或A⁻，平衡右移，促进电离。","examples":["【示范：由Ka比较和计算弱酸】对HA⇌H⁺+A⁻，Ka=c(H⁺)c(A⁻)/c(HA)。同温同类条件下Ka较大通常酸性较强；用起始—变化—平衡列浓度，近似前要验证x相对初浓度足够小。"],"visualSteps":["消耗某离子","写表达式","同温比较","三段式","近似后验算"]},{"label":"温度","rule":"电离一般伴随热效应，温度影响方向由ΔH决定，同时会改变Ka或Kb。","examples":["【示范：由Ka比较和计算弱酸】对HA⇌H⁺+A⁻，Ka=c(H⁺)c(A⁻)/c(HA)。同温同类条件下Ka较大通常酸性较强；用起始—变化—平衡列浓度，近似前要验证x相对初浓度足够小。"],"visualSteps":["温度","写表达式","同温比较","三段式","近似后验算"]}]},{"title":"电离常数Ka、Kb","summary":"常数把平衡组成定量化。","items":[{"label":"表达式","rule":"对HA⇌H⁺+A⁻，Ka=c(H⁺)c(A⁻)/c(HA)，均取平衡浓度。","examples":["【示范：稀释和加同离子的区别】0.10 mol·L⁻¹醋酸加水时电离度增大但c(H⁺)通常减小；加入CH₃COONa带入同离子A⁻，Q>Ka使平衡左移，电离受抑。温度改变时Ka才改变。"],"visualSteps":["表达式","先看瞬间浓度","比较Q与Ka","判断平衡移动","区分浓度与电离度"]},{"label":"强弱比较","rule":"同温度、同类型条件下Ka越大，电离倾向越强，酸性通常越强。","examples":["【示范：稀释和加同离子的区别】0.10 mol·L⁻¹醋酸加水时电离度增大但c(H⁺)通常减小；加入CH₃COONa带入同离子A⁻，Q>Ka使平衡左移，电离受抑。温度改变时Ka才改变。"],"visualSteps":["强弱比较","先看瞬间浓度","比较Q与Ka","判断平衡移动","区分浓度与电离度"]},{"label":"常数只随温度","rule":"稀释、加入同离子会改变各粒子浓度和电离度，但温度不变时Ka不变。","examples":["【示范：稀释和加同离子的区别】0.10 mol·L⁻¹醋酸加水时电离度增大但c(H⁺)通常减小；加入CH₃COONa带入同离子A⁻，Q>Ka使平衡左移，电离受抑。温度改变时Ka才改变。"],"visualSteps":["常数只随温度","先看瞬间浓度","比较Q与Ka","判断平衡移动","区分浓度与电离度"]}]},{"title":"证明弱酸的实验逻辑","summary":"要排除“只说明它是酸”的证据。","items":[{"label":"同浓度比较pH或导电性","rule":"同浓度一元酸中，弱酸电离少，c(H⁺)较小、pH较大；需控制温度和浓度。","examples":["【示范：证明醋酸是弱酸】不能只测一瓶醋酸pH<7。可测已知浓度醋酸发现c(H⁺)远小于形式浓度，或比较等浓度盐酸/醋酸pH，并用醋酸钠溶液显碱性作共轭水解证据。"],"visualSteps":["同浓度比较pH或导电性","明确待证结论","设计可区分证据","控制浓度温度","排除替代解释"]},{"label":"测定pH后稀释","rule":"若稀释倍数与c(H⁺)变化不成简单强酸比例，可支持存在电离平衡。","examples":["【示范：证明醋酸是弱酸】不能只测一瓶醋酸pH<7。可测已知浓度醋酸发现c(H⁺)远小于形式浓度，或比较等浓度盐酸/醋酸pH，并用醋酸钠溶液显碱性作共轭水解证据。"],"visualSteps":["测定pH后稀释","明确待证结论","设计可区分证据","控制浓度温度","排除替代解释"]},{"label":"与强碱反应","rule":"能中和NaOH只能说明具有酸性，不能单独证明是弱酸。","caution":"证据结论不能超出实验能排除的范围。","examples":["【示范：证明醋酸是弱酸】不能只测一瓶醋酸pH<7。可测已知浓度醋酸发现c(H⁺)远小于形式浓度，或比较等浓度盐酸/醋酸pH，并用醋酸钠溶液显碱性作共轭水解证据。"],"visualSteps":["与强碱反应","明确待证结论","设计可区分证据","控制浓度温度","排除替代解释"]}]}],"workedExamples":[{"substance":"HCl与CH₃COOH对比","path":"HCl在水中近乎完全电离，写等号；CH₃COOH分子与H⁺、CH₃COO⁻共存，写可逆号。CaCO₃难溶但溶解部分完全电离，仍属强电解质。","labels":["看电离程度","强写等号","弱写可逆号","强弱不看溶解度"]},{"substance":"醋酸电离怎样达到平衡","path":"刚加水时以CH₃COOH电离为主；H⁺、CH₃COO⁻增多后结合速率增大，最终正逆速率相等，各粒子浓度不再宏观变化。多元弱酸通常逐级更难电离。","labels":["正向先快","逆向逐渐增强","动态平衡","分步电离"]},{"substance":"由Ka比较和计算弱酸","path":"对HA⇌H⁺+A⁻，Ka=c(H⁺)c(A⁻)/c(HA)。同温同类条件下Ka较大通常酸性较强；用起始—变化—平衡列浓度，近似前要验证x相对初浓度足够小。","labels":["写表达式","同温比较","三段式","近似后验算"]},{"substance":"稀释和加同离子的区别","path":"0.10 mol·L⁻¹醋酸加水时电离度增大但c(H⁺)通常减小；加入CH₃COONa带入同离子A⁻，Q>Ka使平衡左移，电离受抑。温度改变时Ka才改变。","labels":["先看瞬间浓度","比较Q与Ka","判断平衡移动","区分浓度与电离度"]},{"substance":"证明醋酸是弱酸","path":"不能只测一瓶醋酸pH<7。可测已知浓度醋酸发现c(H⁺)远小于形式浓度，或比较等浓度盐酸/醋酸pH，并用醋酸钠溶液显碱性作共轭水解证据。","labels":["明确待证结论","设计可区分证据","控制浓度温度","排除替代解释"]},{"substance":"0.1 mol·L⁻¹醋酸加水","path":"体积先增大，所有粒子瞬间被稀释；Q小于Ka，平衡右移，电离度α增大。但稀释效应通常占主导，平衡后的c(H⁺)仍下降，所以pH升高。","labels":["瞬间稀释","平衡右移","α增大","c(H⁺)下降"]},{"substance":"加入CH₃COONa","path":"CH₃COONa完全电离带来大量CH₃COO⁻，使Q>Ka，醋酸电离平衡左移；醋酸电离被抑制，c(H⁺)下降。","labels":["同离子","Q>Ka","左移"]}],"checkpoints":["我能区分电解质强弱、溶解性和导电性。","我能解释稀释后电离度与离子浓度为何可能反向变化。","我会写Ka表达式并说明它只随温度改变。","我知道哪些实验只能证明酸性，不能证明弱酸。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H2_WEAK' and skill_id = 'H2_WEAK';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H2_PH_HYDRO","version":2,"intro":"水溶液问题先找粒子来源：强酸强碱完全电离，弱酸弱碱部分电离，盐可能水解，水本身也微弱电离。计算靠平衡常数，浓度关系靠电荷守恒、物料守恒和质子守恒。","overview":["水的离子积Kw=c(H⁺)c(OH⁻)，一定温度下固定；中性本质是c(H⁺)=c(OH⁻)。","pH=−lg c(H⁺)；只有25 ℃时才常用pH+pOH=14。","盐类水解看“弱者的离子”：弱酸根水解显碱性，弱碱阳离子水解显酸性。","任何溶液都满足电荷守恒；含某一来源物质的全部形态满足物料守恒。","滴定先做物质的量反应，再判断过量粒子与平衡，指示剂变色范围应落在pH突跃内。"],"sections":[{"title":"水的电离与Kw","summary":"纯水中也有极少量H⁺和OH⁻。","items":[{"label":"水的自偶电离","rule":"2H₂O⇌H₃O⁺+OH⁻，中学常简写H₂O⇌H⁺+OH⁻。","examples":["【示范：25 ℃纯水与升温后的中性水】25 ℃纯水c(H⁺)=c(OH⁻)=10⁻⁷ mol·L⁻¹，pH=7；升温使Kw变大时两者仍相等，所以仍中性，但pH可以小于7。"],"visualSteps":["水的自偶电离","写Kw","中性看浓度相等","温度改变Kw","不死背pH=7"]},{"label":"离子积","rule":"Kw=c(H⁺)c(OH⁻)，只随温度改变；25 ℃时约为1.0×10⁻¹⁴。","examples":["【示范：25 ℃纯水与升温后的中性水】25 ℃纯水c(H⁺)=c(OH⁻)=10⁻⁷ mol·L⁻¹，pH=7；升温使Kw变大时两者仍相等，所以仍中性，但pH可以小于7。"],"visualSteps":["离子积","写Kw","中性看浓度相等","温度改变Kw","不死背pH=7"]},{"label":"酸碱影响","rule":"加入酸或碱都使水的电离平衡左移；某些盐水解消耗H⁺或OH⁻，可促进水的电离。","examples":["【示范：25 ℃纯水与升温后的中性水】25 ℃纯水c(H⁺)=c(OH⁻)=10⁻⁷ mol·L⁻¹，pH=7；升温使Kw变大时两者仍相等，所以仍中性，但pH可以小于7。"],"visualSteps":["酸碱影响","写Kw","中性看浓度相等","温度改变Kw","不死背pH=7"]},{"label":"中性不等于pH=7","rule":"任何温度下中性都是c(H⁺)=c(OH⁻)；只有Kw=10⁻¹⁴时对应pH=7。","examples":["【示范：25 ℃纯水与升温后的中性水】25 ℃纯水c(H⁺)=c(OH⁻)=10⁻⁷ mol·L⁻¹，pH=7；升温使Kw变大时两者仍相等，所以仍中性，但pH可以小于7。"],"visualSteps":["中性不等于pH=7","写Kw","中性看浓度相等","温度改变Kw","不死背pH=7"]}]},{"title":"pH计算先分体系","summary":"不要看到pH就直接套同一个公式。","items":[{"label":"强酸强碱","rule":"先由完全电离求c(H⁺)或c(OH⁻)，再由Kw换算另一种离子，最后取负对数。","examples":["【示范：三类pH计算】强酸先由完全电离求H⁺；强碱先求OH⁻再用Kw换H⁺；酸碱混合先按n(H⁺)、n(OH⁻)中和，再用剩余量除总体积。弱酸弱碱则需Ka/Kb。"],"visualSteps":["强酸强碱","判体系","完全反应优先","求剩余浓度","负对数"]},{"label":"酸碱混合","rule":"先按n(H⁺)与n(OH⁻)中和，求剩余量，再除以混合后总体积。","caution":"体积能否直接相加以题目常规近似或已知条件为准。","examples":["【示范：三类pH计算】强酸先由完全电离求H⁺；强碱先求OH⁻再用Kw换H⁺；酸碱混合先按n(H⁺)、n(OH⁻)中和，再用剩余量除总体积。弱酸弱碱则需Ka/Kb。"],"visualSteps":["酸碱混合","判体系","完全反应优先","求剩余浓度","负对数"]},{"label":"弱酸弱碱或盐","rule":"要考虑电离或水解平衡，若题给Ka、Kb或Kh则按平衡计算；不可以当完全电离。","examples":["【示范：三类pH计算】强酸先由完全电离求H⁺；强碱先求OH⁻再用Kw换H⁺；酸碱混合先按n(H⁺)、n(OH⁻)中和，再用剩余量除总体积。弱酸弱碱则需Ka/Kb。"],"visualSteps":["弱酸弱碱或盐","判体系","完全反应优先","求剩余浓度","负对数"]},{"label":"极稀溶液","rule":"当外加酸碱浓度接近水自身电离量时，不能忽略水的贡献。","examples":["【示范：三类pH计算】强酸先由完全电离求H⁺；强碱先求OH⁻再用Kw换H⁺；酸碱混合先按n(H⁺)、n(OH⁻)中和，再用剩余量除总体积。弱酸弱碱则需Ka/Kb。"],"visualSteps":["极稀溶液","判体系","完全反应优先","求剩余浓度","负对数"]}]},{"title":"盐类水解从离子来源判断","summary":"强酸强碱对应离子通常不水解，弱者的共轭离子会水解。","items":[{"label":"强酸弱碱盐","rule":"阳离子水解产生H⁺，溶液通常显酸性。","examples":["NH₄⁺+H₂O⇌NH₃·H₂O+H⁺。","【示范：NH₄Cl和CH₃COONa水解】NH₄⁺是弱碱的共轭酸，水解产生H⁺，NH₄Cl显酸性；CH₃COO⁻是弱酸的共轭碱，水解产生OH⁻，CH₃COONa显碱性。加对应酸碱或升温要再看平衡。"],"visualSteps":["强酸弱碱盐","先完全电离","找弱者离子","写水解","判断酸碱性"]},{"label":"强碱弱酸盐","rule":"阴离子水解产生OH⁻，溶液通常显碱性。","examples":["CH₃COO⁻+H₂O⇌CH₃COOH+OH⁻。","【示范：NH₄Cl和CH₃COONa水解】NH₄⁺是弱碱的共轭酸，水解产生H⁺，NH₄Cl显酸性；CH₃COO⁻是弱酸的共轭碱，水解产生OH⁻，CH₃COONa显碱性。加对应酸碱或升温要再看平衡。"],"visualSteps":["强碱弱酸盐","先完全电离","找弱者离子","写水解","判断酸碱性"]},{"label":"弱酸弱碱盐","rule":"酸碱性取决于相应Ka与Kb强弱，不能只靠类别一句话判断。","examples":["【示范：NH₄Cl和CH₃COONa水解】NH₄⁺是弱碱的共轭酸，水解产生H⁺，NH₄Cl显酸性；CH₃COO⁻是弱酸的共轭碱，水解产生OH⁻，CH₃COONa显碱性。加对应酸碱或升温要再看平衡。"],"visualSteps":["弱酸弱碱盐","先完全电离","找弱者离子","写水解","判断酸碱性"]},{"label":"水解应用","rule":"可解释盐溶液酸碱性、泡沫灭火、某些盐的保存与制备、除杂和离子浓度关系。","examples":["【示范：NH₄Cl和CH₃COONa水解】NH₄⁺是弱碱的共轭酸，水解产生H⁺，NH₄Cl显酸性；CH₃COO⁻是弱酸的共轭碱，水解产生OH⁻，CH₃COONa显碱性。加对应酸碱或升温要再看平衡。"],"visualSteps":["水解应用","先完全电离","找弱者离子","写水解","判断酸碱性"]}]},{"title":"三大守恒","summary":"守恒关系先写来源，再写各形态，最后检查电荷系数。","items":[{"label":"电荷守恒","rule":"溶液总体电中性：所有阳离子电荷浓度之和=所有阴离子电荷浓度之和；多价离子要乘电荷数。","examples":["【示范：CH₃COONa的三大守恒】物料守恒c(Na⁺)=c(CH₃COO⁻)+c(CH₃COOH)；电荷守恒c(Na⁺)+c(H⁺)=c(CH₃COO⁻)+c(OH⁻)；质子守恒可由两式组合得到。"],"visualSteps":["电荷守恒","列全部粒子","按来源守物料","按电荷系数守电荷","组合质子关系"]},{"label":"物料守恒","rule":"某一组分进入溶液的总量等于它以各种形态存在的浓度之和。","examples":["Na₂CO₃溶液中与碳有关的总量含CO₃²⁻、HCO₃⁻、H₂CO₃等形态。","【示范：CH₃COONa的三大守恒】物料守恒c(Na⁺)=c(CH₃COO⁻)+c(CH₃COOH)；电荷守恒c(Na⁺)+c(H⁺)=c(CH₃COO⁻)+c(OH⁻)；质子守恒可由两式组合得到。"],"visualSteps":["物料守恒","列全部粒子","按来源守物料","按电荷系数守电荷","组合质子关系"]},{"label":"质子守恒","rule":"可由水解或电离前后的质子得失关系建立，也可由电荷守恒与物料守恒组合得到。","examples":["【示范：CH₃COONa的三大守恒】物料守恒c(Na⁺)=c(CH₃COO⁻)+c(CH₃COOH)；电荷守恒c(Na⁺)+c(H⁺)=c(CH₃COO⁻)+c(OH⁻)；质子守恒可由两式组合得到。"],"visualSteps":["质子守恒","列全部粒子","按来源守物料","按电荷系数守电荷","组合质子关系"]}]},{"title":"酸碱中和滴定","summary":"滴定曲线每个点都对应不同的主要粒子。","items":[{"label":"滴定前","rule":"溶液的pH由待测液本身的电离或水解情况决定。","examples":["【示范：强酸滴定弱碱的整条曲线】滴定前由弱碱电离定pH；滴定中先做中和再处理共轭体系；计量点只剩弱碱的共轭酸盐，通常显酸性；过量后由强酸主导。指示剂变色区应落在突跃内。"],"visualSteps":["滴定前","滴定前","混合区","计量点","过量区与终点"]},{"label":"滴定中","rule":"先做强反应的物质的量计算，再处理剩余弱电解质、共轭离子及水解。","examples":["【示范：强酸滴定弱碱的整条曲线】滴定前由弱碱电离定pH；滴定中先做中和再处理共轭体系；计量点只剩弱碱的共轭酸盐，通常显酸性；过量后由强酸主导。指示剂变色区应落在突跃内。"],"visualSteps":["滴定中","滴定前","混合区","计量点","过量区与终点"]},{"label":"化学计量点","rule":"酸碱恰好按化学计量反应，但pH不一定为7，取决于产物是否水解和温度。","examples":["【示范：强酸滴定弱碱的整条曲线】滴定前由弱碱电离定pH；滴定中先做中和再处理共轭体系；计量点只剩弱碱的共轭酸盐，通常显酸性；过量后由强酸主导。指示剂变色区应落在突跃内。"],"visualSteps":["化学计量点","滴定前","混合区","计量点","过量区与终点"]},{"label":"指示剂和操作","rule":"变色范围应落在突跃范围；读数、润洗、气泡和终点判断会造成方向明确的误差。","examples":["【示范：强酸滴定弱碱的整条曲线】滴定前由弱碱电离定pH；滴定中先做中和再处理共轭体系；计量点只剩弱碱的共轭酸盐，通常显酸性；过量后由强酸主导。指示剂变色区应落在突跃内。"],"visualSteps":["指示剂和操作","滴定前","混合区","计量点","过量区与终点"]}]}],"workedExamples":[{"substance":"25 ℃纯水与升温后的中性水","path":"25 ℃纯水c(H⁺)=c(OH⁻)=10⁻⁷ mol·L⁻¹，pH=7；升温使Kw变大时两者仍相等，所以仍中性，但pH可以小于7。","labels":["写Kw","中性看浓度相等","温度改变Kw","不死背pH=7"]},{"substance":"三类pH计算","path":"强酸先由完全电离求H⁺；强碱先求OH⁻再用Kw换H⁺；酸碱混合先按n(H⁺)、n(OH⁻)中和，再用剩余量除总体积。弱酸弱碱则需Ka/Kb。","labels":["判体系","完全反应优先","求剩余浓度","负对数"]},{"substance":"NH₄Cl和CH₃COONa水解","path":"NH₄⁺是弱碱的共轭酸，水解产生H⁺，NH₄Cl显酸性；CH₃COO⁻是弱酸的共轭碱，水解产生OH⁻，CH₃COONa显碱性。加对应酸碱或升温要再看平衡。","labels":["先完全电离","找弱者离子","写水解","判断酸碱性"]},{"substance":"CH₃COONa的三大守恒","path":"物料守恒c(Na⁺)=c(CH₃COO⁻)+c(CH₃COOH)；电荷守恒c(Na⁺)+c(H⁺)=c(CH₃COO⁻)+c(OH⁻)；质子守恒可由两式组合得到。","labels":["列全部粒子","按来源守物料","按电荷系数守电荷","组合质子关系"]},{"substance":"强酸滴定弱碱的整条曲线","path":"滴定前由弱碱电离定pH；滴定中先做中和再处理共轭体系；计量点只剩弱碱的共轭酸盐，通常显酸性；过量后由强酸主导。指示剂变色区应落在突跃内。","labels":["滴定前","混合区","计量点","过量区与终点"]},{"substance":"25 ℃、pH=3的强酸","path":"c(H⁺)=10⁻³ mol·L⁻¹；Kw=10⁻¹⁴，所以c(OH⁻)=10⁻¹¹ mol·L⁻¹。不能把pH=3理解为c(H⁺)=3。","labels":["负对数","Kw换算","单位mol·L⁻¹"]},{"substance":"NH₄Cl为何显酸性","path":"NH₄Cl完全电离为NH₄⁺和Cl⁻；Cl⁻来自强酸，水解很弱；NH₄⁺是弱碱NH₃·H₂O的共轭酸，和水反应生成H⁺，所以溶液显酸性。","labels":["先电离","找弱者","写水解","判断酸碱性"]}],"checkpoints":["我能说明中性为什么不总是pH=7。","我会先中和再算酸碱混合。","我能写电荷守恒并正确乘多价离子系数。","我能判断化学计量点pH是否等于7。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H2_PH_HYDRO' and skill_id = 'H2_PH_HYDRO';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H2_KSP","version":2,"intro":"“难溶”不是“完全不溶”。难溶电解质在水中仍有极少量溶解，并与沉淀过程形成动态平衡。Ksp描述平衡限度，Qsp描述当前状态。","overview":["先写溶解平衡，再按离子计量数写Ksp表达式；固体不写。","Qsp<Ksp继续溶解，Qsp=Ksp达到平衡，Qsp>Ksp析出沉淀。","同离子使溶解平衡左移，酸碱或络合消耗离子可促进溶解。","Ksp只随温度改变；溶解度还受化学式计量数、同离子、pH等影响。"],"sections":[{"title":"沉淀溶解平衡","summary":"固体表面的溶解和溶液中的结晶同时发生。","items":[{"label":"动态平衡","rule":"一定温度下，溶解速率等于沉淀速率，溶液中离子浓度保持不变，但微观过程不停。","examples":["【示范：AgCl的动态溶解平衡】AgCl(s)⇌Ag⁺(aq)+Cl⁻(aq)。饱和时溶解和结晶速率相等，溶液中仍有Ag⁺、Cl⁻，不能把“难溶”理解成“完全没有离子”。"],"visualSteps":["动态平衡","写可逆平衡","溶解与结晶并存","达到饱和","难溶不等于零"]},{"label":"难溶与微溶","rule":"溶解度小不代表离子浓度为0；是否“有沉淀”还取决于总量和Qsp。","examples":["【示范：AgCl的动态溶解平衡】AgCl(s)⇌Ag⁺(aq)+Cl⁻(aq)。饱和时溶解和结晶速率相等，溶液中仍有Ag⁺、Cl⁻，不能把“难溶”理解成“完全没有离子”。"],"visualSteps":["难溶与微溶","写可逆平衡","溶解与结晶并存","达到饱和","难溶不等于零"]},{"label":"固体量影响","rule":"只要固相仍存在，增加同种固体通常不改变饱和溶液中平衡离子浓度。","examples":["【示范：AgCl的动态溶解平衡】AgCl(s)⇌Ag⁺(aq)+Cl⁻(aq)。饱和时溶解和结晶速率相等，溶液中仍有Ag⁺、Cl⁻，不能把“难溶”理解成“完全没有离子”。"],"visualSteps":["固体量影响","写可逆平衡","溶解与结晶并存","达到饱和","难溶不等于零"]}]},{"title":"Ksp表达式","summary":"化学式下标既进入离子浓度关系，也成为表达式指数。","items":[{"label":"1:1型","rule":"AgCl(s)⇌Ag⁺+Cl⁻，Ksp=c(Ag⁺)c(Cl⁻)。","examples":["【示范：CaF₂怎样写Ksp】CaF₂(s)⇌Ca²⁺+2F⁻，Ksp=c(Ca²⁺)c²(F⁻)，固体不写；若改写成2CaF₂⇌2Ca²⁺+4F⁻，对应常数会改变。"],"visualSteps":["1:1型","先写溶解式","离子系数作指数","固体省略","反应式变常数变"]},{"label":"1:2型","rule":"CaF₂(s)⇌Ca²⁺+2F⁻，Ksp=c(Ca²⁺)c(F⁻)²。","examples":["【示范：CaF₂怎样写Ksp】CaF₂(s)⇌Ca²⁺+2F⁻，Ksp=c(Ca²⁺)c²(F⁻)，固体不写；若改写成2CaF₂⇌2Ca²⁺+4F⁻，对应常数会改变。"],"visualSteps":["1:2型","先写溶解式","离子系数作指数","固体省略","反应式变常数变"]},{"label":"Ksp与溶解度","rule":"在纯水中可用溶解度s建立离子浓度，但不同化学计量类型不能直接按Ksp大小比较溶解度。","examples":["【示范：CaF₂怎样写Ksp】CaF₂(s)⇌Ca²⁺+2F⁻，Ksp=c(Ca²⁺)c²(F⁻)，固体不写；若改写成2CaF₂⇌2Ca²⁺+4F⁻，对应常数会改变。"],"visualSteps":["Ksp与溶解度","先写溶解式","离子系数作指数","固体省略","反应式变常数变"]}]},{"title":"Qsp决定当前方向","summary":"把当前离子浓度代入与Ksp相同形式。","items":[{"label":"Qsp<Ksp","rule":"溶液未饱和；若有该固体，会继续溶解。","examples":["【示范：混合Ag⁺和Cl⁻判沉淀】先用混合后的总体积求瞬时c(Ag⁺)、c(Cl⁻)，算Qsp。Qsp<Ksp未饱和；等于Ksp饱和；大于Ksp则析出AgCl直至回到Ksp。"],"visualSteps":["Qsp<Ksp","混合稀释","计算Qsp","比较Ksp","判断方向"]},{"label":"Qsp=Ksp","rule":"溶液达到饱和状态，宏观上处于沉淀溶解平衡。","examples":["【示范：混合Ag⁺和Cl⁻判沉淀】先用混合后的总体积求瞬时c(Ag⁺)、c(Cl⁻)，算Qsp。Qsp<Ksp未饱和；等于Ksp饱和；大于Ksp则析出AgCl直至回到Ksp。"],"visualSteps":["Qsp=Ksp","混合稀释","计算Qsp","比较Ksp","判断方向"]},{"label":"Qsp>Ksp","rule":"离子浓度组合过大，体系析出沉淀，直至Qsp降到Ksp。","examples":["【示范：混合Ag⁺和Cl⁻判沉淀】先用混合后的总体积求瞬时c(Ag⁺)、c(Cl⁻)，算Qsp。Qsp<Ksp未饱和；等于Ksp饱和；大于Ksp则析出AgCl直至回到Ksp。"],"visualSteps":["Qsp>Ksp","混合稀释","计算Qsp","比较Ksp","判断方向"]},{"label":"混合瞬间","rule":"混合两种溶液后先按总体积求瞬时离子浓度，再算Qsp；不能直接用混合前浓度。","examples":["【示范：混合Ag⁺和Cl⁻判沉淀】先用混合后的总体积求瞬时c(Ag⁺)、c(Cl⁻)，算Qsp。Qsp<Ksp未饱和；等于Ksp饱和；大于Ksp则析出AgCl直至回到Ksp。"],"visualSteps":["混合瞬间","混合稀释","计算Qsp","比较Ksp","判断方向"]}]},{"title":"怎样促进沉淀或溶解","summary":"平衡移动只是方向，最终还要看Qsp。","items":[{"label":"同离子效应","rule":"加入含共同离子的可溶物，Qsp增大或平衡左移，溶解度通常减小。","examples":["【示范：让Mg(OH)₂沉淀或溶解】加OH⁻使Qsp增大可促沉淀；加酸消耗OH⁻使平衡右移、促进溶解；加入Mg²⁺产生同离子效应抑制溶解。若有络合剂消耗Mg²⁺也可促进溶解。"],"visualSteps":["同离子效应","改变某离子浓度","Qsp随之改变","判断移动","区分同离子/消耗"]},{"label":"消耗离子","rule":"加酸消耗弱酸根、加碱消耗某些金属离子或形成稳定配合物，可使平衡右移、促进溶解。","examples":["【示范：让Mg(OH)₂沉淀或溶解】加OH⁻使Qsp增大可促沉淀；加酸消耗OH⁻使平衡右移、促进溶解；加入Mg²⁺产生同离子效应抑制溶解。若有络合剂消耗Mg²⁺也可促进溶解。"],"visualSteps":["消耗离子","改变某离子浓度","Qsp随之改变","判断移动","区分同离子/消耗"]},{"label":"沉淀转化","rule":"一种沉淀可转化为更难溶或在当前条件下更稳定的沉淀；要综合平衡常数和离子浓度。","examples":["【示范：让Mg(OH)₂沉淀或溶解】加OH⁻使Qsp增大可促沉淀；加酸消耗OH⁻使平衡右移、促进溶解；加入Mg²⁺产生同离子效应抑制溶解。若有络合剂消耗Mg²⁺也可促进溶解。"],"visualSteps":["沉淀转化","改变某离子浓度","Qsp随之改变","判断移动","区分同离子/消耗"]},{"label":"分步沉淀","rule":"逐步改变沉淀剂浓度或pH，使不同离子先后达到Qsp>Ksp，实现分离。","examples":["【示范：让Mg(OH)₂沉淀或溶解】加OH⁻使Qsp增大可促沉淀；加酸消耗OH⁻使平衡右移、促进溶解；加入Mg²⁺产生同离子效应抑制溶解。若有络合剂消耗Mg²⁺也可促进溶解。"],"visualSteps":["分步沉淀","改变某离子浓度","Qsp随之改变","判断移动","区分同离子/消耗"]}]},{"title":"计算与表达规范","summary":"每一步都写清平衡前还是平衡后。","items":[{"label":"设溶解度s","rule":"由化学计量数写各离子平衡浓度，再代入Ksp求s。","examples":["【示范：由Ksp求CaF₂溶解度】设摩尔溶解度s，则c(Ca²⁺)=s、c(F⁻)=2s，Ksp=s(2s)²=4s³。不同类型不能只按Ksp数值大小直接比较溶解度；“沉淀完全”按题给残余浓度标准。"],"visualSteps":["设溶解度s","设s","按计量数写浓度","代Ksp","说明比较边界"]},{"label":"沉淀完全的含义","rule":"分析中“沉淀完全”常表示残余离子浓度低于题给标准，不是数学上的0。","examples":["【示范：由Ksp求CaF₂溶解度】设摩尔溶解度s，则c(Ca²⁺)=s、c(F⁻)=2s，Ksp=s(2s)²=4s³。不同类型不能只按Ksp数值大小直接比较溶解度；“沉淀完全”按题给残余浓度标准。"],"visualSteps":["沉淀完全的含义","设s","按计量数写浓度","代Ksp","说明比较边界"]},{"label":"选择沉淀剂","rule":"既要使目标离子充分沉淀，又要避免其他离子共同沉淀，并考虑后续分离。","examples":["【示范：由Ksp求CaF₂溶解度】设摩尔溶解度s，则c(Ca²⁺)=s、c(F⁻)=2s，Ksp=s(2s)²=4s³。不同类型不能只按Ksp数值大小直接比较溶解度；“沉淀完全”按题给残余浓度标准。"],"visualSteps":["选择沉淀剂","设s","按计量数写浓度","代Ksp","说明比较边界"]}]}],"workedExamples":[{"substance":"AgCl的动态溶解平衡","path":"AgCl(s)⇌Ag⁺(aq)+Cl⁻(aq)。饱和时溶解和结晶速率相等，溶液中仍有Ag⁺、Cl⁻，不能把“难溶”理解成“完全没有离子”。","labels":["写可逆平衡","溶解与结晶并存","达到饱和","难溶不等于零"]},{"substance":"CaF₂怎样写Ksp","path":"CaF₂(s)⇌Ca²⁺+2F⁻，Ksp=c(Ca²⁺)c²(F⁻)，固体不写；若改写成2CaF₂⇌2Ca²⁺+4F⁻，对应常数会改变。","labels":["先写溶解式","离子系数作指数","固体省略","反应式变常数变"]},{"substance":"混合Ag⁺和Cl⁻判沉淀","path":"先用混合后的总体积求瞬时c(Ag⁺)、c(Cl⁻)，算Qsp。Qsp<Ksp未饱和；等于Ksp饱和；大于Ksp则析出AgCl直至回到Ksp。","labels":["混合稀释","计算Qsp","比较Ksp","判断方向"]},{"substance":"让Mg(OH)₂沉淀或溶解","path":"加OH⁻使Qsp增大可促沉淀；加酸消耗OH⁻使平衡右移、促进溶解；加入Mg²⁺产生同离子效应抑制溶解。若有络合剂消耗Mg²⁺也可促进溶解。","labels":["改变某离子浓度","Qsp随之改变","判断移动","区分同离子/消耗"]},{"substance":"由Ksp求CaF₂溶解度","path":"设摩尔溶解度s，则c(Ca²⁺)=s、c(F⁻)=2s，Ksp=s(2s)²=4s³。不同类型不能只按Ksp数值大小直接比较溶解度；“沉淀完全”按题给残余浓度标准。","labels":["设s","按计量数写浓度","代Ksp","说明比较边界"]},{"substance":"判断AgCl是否沉淀","path":"混合后若c(Ag⁺)=1.0×10⁻⁴、c(Cl⁻)=2.0×10⁻⁵ mol·L⁻¹，则Qsp=2.0×10⁻⁹。与题给Ksp比较：若Qsp>Ksp就会析出AgCl。","labels":["用混合后浓度","算Qsp","比较Ksp"]},{"substance":"CaF₂在纯水中的s","path":"设摩尔溶解度为s，则c(Ca²⁺)=s、c(F⁻)=2s，所以Ksp=s(2s)²=4s³；由此求s。","labels":["化学式1:2","F⁻为2s","指数平方"]}],"checkpoints":["我能解释难溶物为什么仍有溶解平衡。","我会按化学式写Ksp和离子浓度倍数。","我能用Qsp与Ksp判断方向。","我不会直接用不同类型盐的Ksp大小比较溶解度。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H2_KSP' and skill_id = 'H2_KSP';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H2_ELECTRO","version":2,"intro":"电化学题先看能量来源：自发氧化还原产生电流的是原电池，外加电源推动非自发反应的是电解池。无论哪种装置，阳极氧化、阴极还原永远不变。","overview":["原电池：负极氧化、正极还原，电子经外电路由负极流向正极。","电解池：阳极接电源正极并氧化，阴极接电源负极并还原。","电子只走金属导线；溶液和盐桥中靠离子移动维持电中性。","写电极反应时先判断介质和实际放电粒子，再配原子、电荷和电子。","所有定量都可回到电子守恒：各电极转移电子的物质的量相等。"],"sections":[{"title":"原电池从零建立","summary":"一个自发氧化还原反应被分成两个空间分离的半反应。","items":[{"label":"构成与作用","rule":"两个电极、电解质和闭合回路使电子经外电路流动，把化学能转化为电能。","examples":["【示范：锌铜原电池四条线】Zn失电子作负极：Zn-2e⁻=Zn²⁺；Cu²⁺在正极得电子：Cu²⁺+2e⁻=Cu。电子从Zn经外电路到Cu；盐桥阴离子移向Zn侧、阳离子移向Cu侧。"],"visualSteps":["构成与作用","负极氧化","正极还原","电子外电路","离子内电路"]},{"label":"负极","rule":"发生氧化反应，放出电子；活泼金属常作负极，但最终以实际电极反应为准。","examples":["【示范：锌铜原电池四条线】Zn失电子作负极：Zn-2e⁻=Zn²⁺；Cu²⁺在正极得电子：Cu²⁺+2e⁻=Cu。电子从Zn经外电路到Cu；盐桥阴离子移向Zn侧、阳离子移向Cu侧。"],"visualSteps":["负极","负极氧化","正极还原","电子外电路","离子内电路"]},{"label":"正极","rule":"发生还原反应，接受外电路电子；电极材料可能只导电而不消耗。","examples":["【示范：锌铜原电池四条线】Zn失电子作负极：Zn-2e⁻=Zn²⁺；Cu²⁺在正极得电子：Cu²⁺+2e⁻=Cu。电子从Zn经外电路到Cu；盐桥阴离子移向Zn侧、阳离子移向Cu侧。"],"visualSteps":["正极","负极氧化","正极还原","电子外电路","离子内电路"]},{"label":"盐桥或离子膜","rule":"连通内电路并维持两侧电中性；阴离子通常移向负极区，阳离子移向正极区。","examples":["【示范：锌铜原电池四条线】Zn失电子作负极：Zn-2e⁻=Zn²⁺；Cu²⁺在正极得电子：Cu²⁺+2e⁻=Cu。电子从Zn经外电路到Cu；盐桥阴离子移向Zn侧、阳离子移向Cu侧。"],"visualSteps":["盐桥或离子膜","负极氧化","正极还原","电子外电路","离子内电路"]}]},{"title":"电解池从零建立","summary":"外电源强迫电子流动，把电能转化为化学能。","items":[{"label":"阳极与电源正极相连","rule":"电极或溶液中的粒子失电子，发生氧化。","examples":["【示范：电解CuCl₂溶液】常规浓度、惰性电极条件下，阳极接正极，Cl⁻失电子生成Cl₂；阴极接负极，Cu²⁺得电子析Cu。若题目给出很稀溶液或特殊条件，要再比较水与离子的放电。"],"visualSteps":["阳极与电源正极相连","辨电解池","阳极氧化","阴极还原","条件复核"]},{"label":"阴极与电源负极相连","rule":"电解质中的阳离子或水等粒子在阴极得到电子，发生还原。","examples":["【示范：电解CuCl₂溶液】常规浓度、惰性电极条件下，阳极接正极，Cl⁻失电子生成Cl₂；阴极接负极，Cu²⁺得电子析Cu。若题目给出很稀溶液或特殊条件，要再比较水与离子的放电。"],"visualSteps":["阴极与电源负极相连","辨电解池","阳极氧化","阴极还原","条件复核"]},{"label":"放电顺序","rule":"由电极材料、离子氧化还原能力、浓度和过电位等共同决定；中学常规体系按已学规律，陌生体系按题给信息。","examples":["【示范：电解CuCl₂溶液】常规浓度、惰性电极条件下，阳极接正极，Cl⁻失电子生成Cl₂；阴极接负极，Cu²⁺得电子析Cu。若题目给出很稀溶液或特殊条件，要再比较水与离子的放电。"],"visualSteps":["放电顺序","辨电解池","阳极氧化","阴极还原","条件复核"]},{"label":"惰性与活性电极","rule":"惰性电极主要导电；活性阳极可能优先溶解，直接参与反应。","examples":["【示范：电解CuCl₂溶液】常规浓度、惰性电极条件下，阳极接正极，Cl⁻失电子生成Cl₂；阴极接负极，Cu²⁺得电子析Cu。若题目给出很稀溶液或特殊条件，要再比较水与离子的放电。"],"visualSteps":["惰性与活性电极","辨电解池","阳极氧化","阴极还原","条件复核"]}]},{"title":"电极反应式的稳定写法","summary":"先写半反应，再用介质补齐。","items":[{"label":"1. 定氧化或还原","rule":"阳极写失电子，阴极写得电子，电子位置不能写反。","examples":["【示范：酸性介质写燃料电池电极式】先定燃料在阳极被氧化、O₂在阴极被还原；写骨架后用H₂O补O、H⁺补H、e⁻配电荷。两式倍乘消去电子后必须等于总反应。"],"visualSteps":["1. 定氧化或还原","定氧化还原","写骨架","按介质配平","相加核对"]},{"label":"2. 定实际粒子","rule":"判断是电极材料、溶质离子还是水参加，产物还受酸碱介质影响。","examples":["【示范：酸性介质写燃料电池电极式】先定燃料在阳极被氧化、O₂在阴极被还原；写骨架后用H₂O补O、H⁺补H、e⁻配电荷。两式倍乘消去电子后必须等于总反应。"],"visualSteps":["2. 定实际粒子","定氧化还原","写骨架","按介质配平","相加核对"]},{"label":"3. 配原子和电荷","rule":"先配核心元素，再用H₂O、H⁺或OH⁻按介质补H和O，最后用e⁻配电荷。","examples":["【示范：酸性介质写燃料电池电极式】先定燃料在阳极被氧化、O₂在阴极被还原；写骨架后用H₂O补O、H⁺补H、e⁻配电荷。两式倍乘消去电子后必须等于总反应。"],"visualSteps":["3. 配原子和电荷","定氧化还原","写骨架","按介质配平","相加核对"]},{"label":"4. 合并总反应","rule":"两极电子数配成相等后相加，删除两边相同粒子并检查是否与装置物质变化一致。","examples":["【示范：酸性介质写燃料电池电极式】先定燃料在阳极被氧化、O₂在阴极被还原；写骨架后用H₂O补O、H⁺补H、e⁻配电荷。两式倍乘消去电子后必须等于总反应。"],"visualSteps":["4. 合并总反应","定氧化还原","写骨架","按介质配平","相加核对"]}]},{"title":"离子迁移、膜和多室装置","summary":"膜不是让电子通过，而是控制离子通过。","items":[{"label":"电中性要求","rule":"某侧产生正电荷，就需阴离子迁入或阳离子迁出；由此判断迁移方向。","examples":["【示范：盐桥和阳离子膜怎么判方向】锌铜原电池中负极区Zn²⁺增加，盐桥阴离子移入；正极区Cu²⁺减少，阳离子移入。若换成选择膜，先看膜允许谁通过，再用各室电中性判断方向和数量。"],"visualSteps":["电中性要求","各室做电荷账","判断离子增减","看膜选择性","维持电中性"]},{"label":"选择性交换膜","rule":"阳离子膜主要允许阳离子通过，阴离子膜主要允许阴离子通过；作用可能是隔开产物、维持电荷或富集物质。","examples":["【示范：盐桥和阳离子膜怎么判方向】锌铜原电池中负极区Zn²⁺增加，盐桥阴离子移入；正极区Cu²⁺减少，阳离子移入。若换成选择膜，先看膜允许谁通过，再用各室电中性判断方向和数量。"],"visualSteps":["选择性交换膜","各室做电荷账","判断离子增减","看膜选择性","维持电中性"]},{"label":"电子与电流","rule":"电子在外电路由供电子处流向受电子处；传统电流方向与电子相反。","caution":"不能写“电子穿过电解质溶液或离子交换膜”。","examples":["【示范：盐桥和阳离子膜怎么判方向】锌铜原电池中负极区Zn²⁺增加，盐桥阴离子移入；正极区Cu²⁺减少，阳离子移入。若换成选择膜，先看膜允许谁通过，再用各室电中性判断方向和数量。"],"visualSteps":["电子与电流","各室做电荷账","判断离子增减","看膜选择性","维持电中性"]}]},{"title":"腐蚀、防护与定量","summary":"腐蚀是微小原电池，防护就是控制电极反应。","items":[{"label":"电化学腐蚀","rule":"较活泼区域作负极被氧化；酸性或中性含氧环境中正极反应不同。","examples":["【示范：铁的腐蚀与电子定量】酸性水膜中Fe作负极失电子，较活泼金属连接可作牺牲阳极；外加电流保护时被保护铁接电源负极。若转移0.20 mol e⁻，各电极产物都按半反应电子系数换算。"],"visualSteps":["电化学腐蚀","判腐蚀电极","选择防护方式","求n(e⁻)","换质量或气体"]},{"label":"牺牲阳极保护","rule":"连接更活泼金属，使其作负极优先溶解，被保护金属作正极。","examples":["【示范：铁的腐蚀与电子定量】酸性水膜中Fe作负极失电子，较活泼金属连接可作牺牲阳极；外加电流保护时被保护铁接电源负极。若转移0.20 mol e⁻，各电极产物都按半反应电子系数换算。"],"visualSteps":["牺牲阳极保护","判腐蚀电极","选择防护方式","求n(e⁻)","换质量或气体"]},{"label":"外加电流保护","rule":"用直流电源使被保护金属连接负极，成为阴极。","examples":["【示范：铁的腐蚀与电子定量】酸性水膜中Fe作负极失电子，较活泼金属连接可作牺牲阳极；外加电流保护时被保护铁接电源负极。若转移0.20 mol e⁻，各电极产物都按半反应电子系数换算。"],"visualSteps":["外加电流保护","判腐蚀电极","选择防护方式","求n(e⁻)","换质量或气体"]},{"label":"电子守恒计算","rule":"同一回路各电极通过电子的物质的量相等；用电极半反应把e⁻与质量、气体体积、离子浓度相连。","examples":["【示范：铁的腐蚀与电子定量】酸性水膜中Fe作负极失电子，较活泼金属连接可作牺牲阳极；外加电流保护时被保护铁接电源负极。若转移0.20 mol e⁻，各电极产物都按半反应电子系数换算。"],"visualSteps":["电子守恒计算","判腐蚀电极","选择防护方式","求n(e⁻)","换质量或气体"]}]}],"workedExamples":[{"substance":"锌铜原电池四条线","path":"Zn失电子作负极：Zn-2e⁻=Zn²⁺；Cu²⁺在正极得电子：Cu²⁺+2e⁻=Cu。电子从Zn经外电路到Cu；盐桥阴离子移向Zn侧、阳离子移向Cu侧。","labels":["负极氧化","正极还原","电子外电路","离子内电路"]},{"substance":"电解CuCl₂溶液","path":"常规浓度、惰性电极条件下，阳极接正极，Cl⁻失电子生成Cl₂；阴极接负极，Cu²⁺得电子析Cu。若题目给出很稀溶液或特殊条件，要再比较水与离子的放电。","labels":["辨电解池","阳极氧化","阴极还原","条件复核"]},{"substance":"酸性介质写燃料电池电极式","path":"先定燃料在阳极被氧化、O₂在阴极被还原；写骨架后用H₂O补O、H⁺补H、e⁻配电荷。两式倍乘消去电子后必须等于总反应。","labels":["定氧化还原","写骨架","按介质配平","相加核对"]},{"substance":"盐桥和阳离子膜怎么判方向","path":"锌铜原电池中负极区Zn²⁺增加，盐桥阴离子移入；正极区Cu²⁺减少，阳离子移入。若换成选择膜，先看膜允许谁通过，再用各室电中性判断方向和数量。","labels":["各室做电荷账","判断离子增减","看膜选择性","维持电中性"]},{"substance":"铁的腐蚀与电子定量","path":"酸性水膜中Fe作负极失电子，较活泼金属连接可作牺牲阳极；外加电流保护时被保护铁接电源负极。若转移0.20 mol e⁻，各电极产物都按半反应电子系数换算。","labels":["判腐蚀电极","选择防护方式","求n(e⁻)","换质量或气体"]},{"substance":"锌铜原电池","path":"负极Zn−2e⁻=Zn²⁺；正极Cu²⁺+2e⁻=Cu；电子从Zn经导线流向Cu。盐桥阴离子移向Zn侧、阳离子移向Cu侧以维持电中性。","labels":["负极氧化","正极还原","电子走外电路","离子走内电路"]},{"substance":"电解CuSO₄溶液析铜","path":"阴极Cu²⁺+2e⁻=Cu。若外电路通过0.20 mol e⁻，析出Cu为0.10 mol，质量约6.4 g；另一电极也对应转移0.20 mol e⁻。","labels":["2 mol e⁻/mol Cu","电子守恒","再换质量"]}],"checkpoints":["我能先判断装置是原电池还是电解池。","我不会混淆正负极和阴阳极。","我能用电中性判断膜两侧离子迁移。","我能把电极反应与电子守恒计算连起来。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H2_ELECTRO' and skill_id = 'H2_ELECTRO';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H3_STOICH","version":2,"intro":"高三计量综合仍然只有一个枢纽n。先把单位、对象和条件补回，再用质量、粒子数、气体体积、溶液浓度进入n，最后用方程式或守恒连接不同物质。","overview":["四条入口：n=m/M，n=N/Nₐ，气体n=V/Vₘ，溶液n=cV。","Nₐ判断先查对象、状态、反应、电离/水解、可逆性和化学式倍数。","反应计量只使用配平后的系数比；多反应物要先判断限制量。","复杂过程优先寻找质量、元素、电子、电荷或质子守恒，减少逐步追算。"],"sections":[{"title":"先补回五个量和四个公式","summary":"每个符号、单位和适用条件都要说完整。","items":[{"label":"n、N与Nₐ","rule":"物质的量n以mol计；微粒数N=nNₐ；对象必须明确到分子、原子、离子、电子或化学键。","examples":["【示范：两个样品贯通五个量】0.50 mol CO₂的质量为22 g、分子数为0.50Nₐ、标况体积为11.2 L；另将0.50 mol NaCl配成500 mL溶液，c(NaCl)=1.0 mol·L⁻¹。每次转换都先回到n，并核对物态和总体积。"],"visualSteps":["n、N与Nₐ","识别对象","用对应公式到n","按物态和条件转换","单位贯穿"]},{"label":"m与M","rule":"n=m/M；质量m常用g，摩尔质量M常用g·mol⁻¹。相对分子质量无单位。","examples":["【示范：两个样品贯通五个量】0.50 mol CO₂的质量为22 g、分子数为0.50Nₐ、标况体积为11.2 L；另将0.50 mol NaCl配成500 mL溶液，c(NaCl)=1.0 mol·L⁻¹。每次转换都先回到n，并核对物态和总体积。"],"visualSteps":["m与M","识别对象","用对应公式到n","按物态和条件转换","单位贯穿"]},{"label":"V与Vₘ","rule":"气体n=V/Vₘ；标准状况下Vₘ≈22.4 L·mol⁻¹，但必须先确认物态和状态条件。","examples":["【示范：两个样品贯通五个量】0.50 mol CO₂的质量为22 g、分子数为0.50Nₐ、标况体积为11.2 L；另将0.50 mol NaCl配成500 mL溶液，c(NaCl)=1.0 mol·L⁻¹。每次转换都先回到n，并核对物态和总体积。"],"visualSteps":["V与Vₘ","识别对象","用对应公式到n","按物态和条件转换","单位贯穿"]},{"label":"c与溶液体积","rule":"n=cV，V用L且指溶液总体积；稀释无反应时溶质n守恒。","examples":["【示范：两个样品贯通五个量】0.50 mol CO₂的质量为22 g、分子数为0.50Nₐ、标况体积为11.2 L；另将0.50 mol NaCl配成500 mL溶液，c(NaCl)=1.0 mol·L⁻¹。每次转换都先回到n，并核对物态和总体积。"],"visualSteps":["c与溶液体积","识别对象","用对应公式到n","按物态和条件转换","单位贯穿"]}]},{"title":"阿伏加德罗常数选择题的六关","summary":"每个选项都逐关检查，不凭熟悉感。","items":[{"label":"1. 对象关","rule":"粒子名称是否明确，化学式下标和离子电荷带来的倍数是否计入。","examples":["【示范：NA选择题六关扫描】判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。"],"visualSteps":["1. 对象关","对象","状态与溶液","反应","结构倍数与守恒"]},{"label":"2. 状态关","rule":"给体积时是否为气体、是否在标准状况；标准状况下H₂O、SO₃等常见物态要核对。","examples":["【示范：NA选择题六关扫描】判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。"],"visualSteps":["2. 状态关","对象","状态与溶液","反应","结构倍数与守恒"]},{"label":"3. 溶液关","rule":"给浓度却没给体积通常不能求总粒子数；弱电解质电离、盐水解使粒子种类更复杂。","examples":["【示范：NA选择题六关扫描】判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。"],"visualSteps":["3. 溶液关","对象","状态与溶液","反应","结构倍数与守恒"]},{"label":"4. 反应关","rule":"可逆反应不完全、过量与不足、歧化、聚合和混合后反应都会改变粒子数。","examples":["【示范：NA选择题六关扫描】判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。"],"visualSteps":["4. 反应关","对象","状态与溶液","反应","结构倍数与守恒"]},{"label":"5. 结构关","rule":"质子、中子、电子、价电子、化学键数需按一个粒子的结构逐一计数。","examples":["【示范：NA选择题六关扫描】判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。"],"visualSteps":["5. 结构关","对象","状态与溶液","反应","结构倍数与守恒"]},{"label":"6. 守恒关","rule":"必要时用原子、电子或电荷守恒检查，而非追逐所有中间物。","examples":["【示范：NA选择题六关扫描】判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。"],"visualSteps":["6. 守恒关","对象","状态与溶液","反应","结构倍数与守恒"]}]},{"title":"反应计量和限制量","summary":"所有已知量先变成mol，再按反应进度分配。","items":[{"label":"配平方程式","rule":"系数比就是物质的量比；未配平的式子不能用于定量。","examples":["【示范：Fe和Cl₂谁限制产物】先配2Fe+3Cl₂=2FeCl₃，分别算n(Fe)/2和n(Cl₂)/3，较小者为反应进度上限；由它求FeCl₃理论量，再与实际产量比较产率。"],"visualSteps":["配平方程式","配平方程式","全部换n","比较n/系数","理论量与产率"]},{"label":"限制量","rule":"分别计算每种反应物可支持的反应进度n/系数，最小者先耗尽。","examples":["【示范：Fe和Cl₂谁限制产物】先配2Fe+3Cl₂=2FeCl₃，分别算n(Fe)/2和n(Cl₂)/3，较小者为反应进度上限；由它求FeCl₃理论量，再与实际产量比较产率。"],"visualSteps":["限制量","配平方程式","全部换n","比较n/系数","理论量与产率"]},{"label":"过量与产率","rule":"理论产量由限制量决定；实际产率=实际产量/理论产量×100%。","examples":["【示范：Fe和Cl₂谁限制产物】先配2Fe+3Cl₂=2FeCl₃，分别算n(Fe)/2和n(Cl₂)/3，较小者为反应进度上限；由它求FeCl₃理论量，再与实际产量比较产率。"],"visualSteps":["过量与产率","配平方程式","全部换n","比较n/系数","理论量与产率"]},{"label":"连续与并行反应","rule":"连续反应可建立总关系式；并行反应通常配合元素守恒、电子守恒或总量关系求解。","examples":["【示范：Fe和Cl₂谁限制产物】先配2Fe+3Cl₂=2FeCl₃，分别算n(Fe)/2和n(Cl₂)/3，较小者为反应进度上限；由它求FeCl₃理论量，再与实际产量比较产率。"],"visualSteps":["连续与并行反应","配平方程式","全部换n","比较n/系数","理论量与产率"]}]},{"title":"四类守恒怎样选","summary":"守恒量要对应过程始终不变的对象。","items":[{"label":"质量守恒","rule":"封闭体系中反应前后总质量相等；有气体逸出或外界物质进入时要明确系统边界。","examples":["【示范：多步炼铁选哪种守恒】从Fe₂O₃经中间氧化物到Fe，若只求最终Fe可直接用Fe元素守恒；若同时涉及CO/CO₂可用C或O守恒；涉及变价氧化剂还可用电子守恒；溶液离子关系用电荷守恒。"],"visualSteps":["质量守恒","圈不变对象","选最短守恒","列等量关系","用另一守恒验算"]},{"label":"元素守恒","rule":"某元素的原子总数在化学变化中守恒，适合多步转化、混合物组成和工艺流程。","examples":["【示范：多步炼铁选哪种守恒】从Fe₂O₃经中间氧化物到Fe，若只求最终Fe可直接用Fe元素守恒；若同时涉及CO/CO₂可用C或O守恒；涉及变价氧化剂还可用电子守恒；溶液离子关系用电荷守恒。"],"visualSteps":["元素守恒","圈不变对象","选最短守恒","列等量关系","用另一守恒验算"]},{"label":"电子守恒","rule":"氧化还原中总失电子=总得电子，适合滴定、电化学和多步变价。","examples":["【示范：多步炼铁选哪种守恒】从Fe₂O₃经中间氧化物到Fe，若只求最终Fe可直接用Fe元素守恒；若同时涉及CO/CO₂可用C或O守恒；涉及变价氧化剂还可用电子守恒；溶液离子关系用电荷守恒。"],"visualSteps":["电子守恒","圈不变对象","选最短守恒","列等量关系","用另一守恒验算"]},{"label":"电荷/质子守恒","rule":"溶液总体电中性；酸碱与水解体系可用质子得失关系。","examples":["【示范：多步炼铁选哪种守恒】从Fe₂O₃经中间氧化物到Fe，若只求最终Fe可直接用Fe元素守恒；若同时涉及CO/CO₂可用C或O守恒；涉及变价氧化剂还可用电子守恒；溶液离子关系用电荷守恒。"],"visualSteps":["电荷/质子守恒","圈不变对象","选最短守恒","列等量关系","用另一守恒验算"]}]},{"title":"数据、图像与计算表达","summary":"计算题既要结果，也要可检查的过程。","items":[{"label":"单位贯穿","rule":"公式代入前统一L、mL、g、kg等单位，最终结果带单位和合理有效数字。","examples":["【示范：从图表读数到规范结果】先读清横纵轴、单位和刻度，从曲线取有效数字；把图中体积mL换成L后代式，分步写公式—代数—结果，并用数量级、极限情况和守恒检查。"],"visualSteps":["单位贯穿","读轴与单位","提取数据","分步计算","数量级复核"]},{"label":"图像先读轴","rule":"热重、滴定或反应进程图先看横轴条件、纵轴物理量和平台/拐点，再把变化量换算为n。","examples":["【示范：从图表读数到规范结果】先读清横纵轴、单位和刻度，从曲线取有效数字；把图中体积mL换成L后代式，分步写公式—代数—结果，并用数量级、极限情况和守恒检查。"],"visualSteps":["图像先读轴","读轴与单位","提取数据","分步计算","数量级复核"]},{"label":"数量级检查","rule":"微粒数通常为10²³量级；浓度、转化率、质量分数必须落在物理合理范围。","examples":["【示范：从图表读数到规范结果】先读清横纵轴、单位和刻度，从曲线取有效数字；把图中体积mL换成L后代式，分步写公式—代数—结果，并用数量级、极限情况和守恒检查。"],"visualSteps":["数量级检查","读轴与单位","提取数据","分步计算","数量级复核"]}]}],"workedExamples":[{"substance":"两个样品贯通五个量","path":"0.50 mol CO₂的质量为22 g、分子数为0.50Nₐ、标况体积为11.2 L；另将0.50 mol NaCl配成500 mL溶液，c(NaCl)=1.0 mol·L⁻¹。每次转换都先回到n，并核对物态和总体积。","labels":["识别对象","用对应公式到n","按物态和条件转换","单位贯穿"]},{"substance":"NA选择题六关扫描","path":"判断“1 mol Na₂O₂含阴离子数2Nₐ”时：对象是过氧根离子，每个化学式单位只有1个O₂²⁻，所以应为Nₐ；还要依次查状态、溶液、反应、结构和守恒。","labels":["对象","状态与溶液","反应","结构倍数与守恒"]},{"substance":"Fe和Cl₂谁限制产物","path":"先配2Fe+3Cl₂=2FeCl₃，分别算n(Fe)/2和n(Cl₂)/3，较小者为反应进度上限；由它求FeCl₃理论量，再与实际产量比较产率。","labels":["配平方程式","全部换n","比较n/系数","理论量与产率"]},{"substance":"多步炼铁选哪种守恒","path":"从Fe₂O₃经中间氧化物到Fe，若只求最终Fe可直接用Fe元素守恒；若同时涉及CO/CO₂可用C或O守恒；涉及变价氧化剂还可用电子守恒；溶液离子关系用电荷守恒。","labels":["圈不变对象","选最短守恒","列等量关系","用另一守恒验算"]},{"substance":"从图表读数到规范结果","path":"先读清横纵轴、单位和刻度，从曲线取有效数字；把图中体积mL换成L后代式，分步写公式—代数—结果，并用数量级、极限情况和守恒检查。","labels":["读轴与单位","提取数据","分步计算","数量级复核"]},{"substance":"标况气体与粒子数","path":"标况11.2 L CO₂为0.5 mol CO₂，含0.5Nₐ个CO₂分子、0.5Nₐ个C原子、1.0Nₐ个O原子，总原子数1.5Nₐ。","labels":["状态关","对象关","化学式倍数"]},{"substance":"Fe与盐酸的限制量","path":"先求n(Fe)和n(HCl)，按Fe+2HCl=FeCl₂+H₂比较n(Fe)/1与n(HCl)/2，较小者决定H₂理论物质的量；再换成体积或质量。","labels":["都先换n","除以系数","最小值决定产量"]}],"checkpoints":["我能画出以n为中心的完整换算网络。","我做Nₐ题会逐项过六关。","我会用n/系数判断限制量。","我能为复杂过程选择合适的守恒。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_STOICH' and skill_id = 'H3_STOICH';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H3_ION_REDOX","version":2,"intro":"高三离子与氧化还原综合不是新体系：先判断溶液中真实粒子和反应事实，再处理少量/过量，最后用电子、电荷和原子守恒把方程式闭合。","overview":["离子共存先翻译隐含条件，再查沉淀、气体、弱电解质、氧化还原和题给特殊反应。","离子方程式按写—拆—删—查；少量、过量决定最终粒子。","氧化还原先标价，升失氧、降得还；总失电子等于总得电子。","陌生方程式仍服从反应事实、电子守恒、电荷守恒、原子守恒和介质条件。"],"sections":[{"title":"离子反应基础重启","summary":"先知道哪些粒子能拆、哪些要保留。","items":[{"label":"可溶强电解质拆写","rule":"水溶液中的强酸、强碱、可溶性盐通常拆成离子。","examples":["【示范：BaCl₂与Na₂SO₄的净反应】两溶液中可溶强电解质拆成离子，BaSO₄沉淀保留化学式，删去Na⁺、Cl⁻，得到Ba²⁺+SO₄²⁻=BaSO₄↓。"],"visualSteps":["可溶强电解质拆写","列真实粒子","保留沉淀","删除旁观离子","查原子电荷"]},{"label":"保留化学式","rule":"沉淀、气体、弱电解质、单质、氧化物通常不拆。","examples":["【示范：BaCl₂与Na₂SO₄的净反应】两溶液中可溶强电解质拆成离子，BaSO₄沉淀保留化学式，删去Na⁺、Cl⁻，得到Ba²⁺+SO₄²⁻=BaSO₄↓。"],"visualSteps":["保留化学式","列真实粒子","保留沉淀","删除旁观离子","查原子电荷"]},{"label":"反应条件","rule":"生成沉淀、气体、弱电解质或发生氧化还原等，使某些粒子显著减少。","examples":["【示范：BaCl₂与Na₂SO₄的净反应】两溶液中可溶强电解质拆成离子，BaSO₄沉淀保留化学式，删去Na⁺、Cl⁻，得到Ba²⁺+SO₄²⁻=BaSO₄↓。"],"visualSteps":["反应条件","列真实粒子","保留沉淀","删除旁观离子","查原子电荷"]}]},{"title":"共存与隐含条件","summary":"先处理题干，再看选项。","items":[{"label":"酸碱与颜色","rule":"强酸性加入大量H⁺，强碱性加入大量OH⁻；无色排除明显有色离子。","examples":["【示范：无色强酸性溶液的共存】把无色排除有色离子，把强酸性转成大量H⁺；再查沉淀、气体、弱电解质、氧化还原与双水解。HCO₃⁻会与H⁺反应，Fe²⁺还可能与酸性NO₃⁻发生氧化还原。"],"visualSteps":["酸碱与颜色","翻译条件","逐对排查","写证据反应","所有离子同时成立"]},{"label":"氧化还原环境","rule":"强氧化性介质与强还原性离子不能大量共存；NO₃⁻在酸性条件下的氧化性等要结合题设。","examples":["【示范：无色强酸性溶液的共存】把无色排除有色离子，把强酸性转成大量H⁺；再查沉淀、气体、弱电解质、氧化还原与双水解。HCO₃⁻会与H⁺反应，Fe²⁺还可能与酸性NO₃⁻发生氧化还原。"],"visualSteps":["氧化还原环境","翻译条件","逐对排查","写证据反应","所有离子同时成立"]},{"label":"双水解和复杂反应","rule":"若水解相互促进并生成沉淀/气体可显著进行，或题给络合信息，也要排除。","examples":["【示范：无色强酸性溶液的共存】把无色排除有色离子，把强酸性转成大量H⁺；再查沉淀、气体、弱电解质、氧化还原与双水解。HCO₃⁻会与H⁺反应，Fe²⁺还可能与酸性NO₃⁻发生氧化还原。"],"visualSteps":["双水解和复杂反应","翻译条件","逐对排查","写证据反应","所有离子同时成立"]},{"label":"结论边界","rule":"逐对无明显反应才能判大量共存；检出某离子不等于溶液只含该离子。","examples":["【示范：无色强酸性溶液的共存】把无色排除有色离子，把强酸性转成大量H⁺；再查沉淀、气体、弱电解质、氧化还原与双水解。HCO₃⁻会与H⁺反应，Fe²⁺还可能与酸性NO₃⁻发生氧化还原。"],"visualSteps":["结论边界","翻译条件","逐对排查","写证据反应","所有离子同时成立"]}]},{"title":"少量、过量与反应顺序","summary":"写到哪个终点由用量决定。","items":[{"label":"定少量为1","rule":"把少量物质的系数先定为1或使其完全反应，再按计量关系确定其他粒子。","examples":["【示范：CO₂通入NaOH的阶段图】OH⁻足量时CO₂先变CO₃²⁻；CO₂继续加入时CO₃²⁻再变HCO₃⁻。根据少量/过量确定终点，必要时写两段式再按物质的量合并。"],"visualSteps":["定少量为1","确定少量物","列阶段","判断竞争顺序","得到终点总式"]},{"label":"分阶段","rule":"若先生成中间产物、继续加试剂又反应，就分别写阶段方程式。","examples":["【示范：CO₂通入NaOH的阶段图】OH⁻足量时CO₂先变CO₃²⁻；CO₂继续加入时CO₃²⁻再变HCO₃⁻。根据少量/过量确定终点，必要时写两段式再按物质的量合并。"],"visualSteps":["分阶段","确定少量物","列阶段","判断竞争顺序","得到终点总式"]},{"label":"合并总式","rule":"根据总用量把阶段方程式按比例相加，确保最终物种与题设一致。","examples":["【示范：CO₂通入NaOH的阶段图】OH⁻足量时CO₂先变CO₃²⁻；CO₂继续加入时CO₃²⁻再变HCO₃⁻。根据少量/过量确定终点，必要时写两段式再按物质的量合并。"],"visualSteps":["合并总式","确定少量物","列阶段","判断竞争顺序","得到终点总式"]},{"label":"竞争顺序","rule":"通常先发生更有利的酸碱、沉淀或氧化还原反应；具体以题给信息和已知强弱为准。","examples":["【示范：CO₂通入NaOH的阶段图】OH⁻足量时CO₂先变CO₃²⁻；CO₂继续加入时CO₃²⁻再变HCO₃⁻。根据少量/过量确定终点，必要时写两段式再按物质的量合并。"],"visualSteps":["竞争顺序","确定少量物","列阶段","判断竞争顺序","得到终点总式"]}]},{"title":"氧化还原配平从零补回","summary":"价态是入口，电子是本质。","items":[{"label":"标化合价","rule":"找到真正变价元素，算每个粒子升降电子数。","examples":["【示范：酸性MnO₄⁻配Fe²⁺】Mn从+7到+2得5e⁻，Fe从+2到+3失1e⁻，先定1:5；酸性用H₂O补O、H⁺补H，得MnO₄⁻+5Fe²⁺+8H⁺=Mn²⁺+5Fe³⁺+4H₂O。"],"visualSteps":["标化合价","标价","电子守恒定骨架","按介质补H/O","电荷复核"]},{"label":"电子守恒定骨架","rule":"用最小公倍数使总失电子=总得电子，先确定氧化剂、还原剂及对应产物系数。","examples":["【示范：酸性MnO₄⁻配Fe²⁺】Mn从+7到+2得5e⁻，Fe从+2到+3失1e⁻，先定1:5；酸性用H₂O补O、H⁺补H，得MnO₄⁻+5Fe²⁺+8H⁺=Mn²⁺+5Fe³⁺+4H₂O。"],"visualSteps":["电子守恒定骨架","标价","电子守恒定骨架","按介质补H/O","电荷复核"]},{"label":"介质补H和O","rule":"酸性用H⁺、H₂O，碱性可用OH⁻、H₂O；最后检查电荷。","examples":["【示范：酸性MnO₄⁻配Fe²⁺】Mn从+7到+2得5e⁻，Fe从+2到+3失1e⁻，先定1:5；酸性用H₂O补O、H⁺补H，得MnO₄⁻+5Fe²⁺+8H⁺=Mn²⁺+5Fe³⁺+4H₂O。"],"visualSteps":["介质补H和O","标价","电子守恒定骨架","按介质补H/O","电荷复核"]},{"label":"缺项配平","rule":"根据原子与电荷守恒推断缺少H⁺、OH⁻、H₂O或其他粒子，并结合介质与反应事实验证。","examples":["【示范：酸性MnO₄⁻配Fe²⁺】Mn从+7到+2得5e⁻，Fe从+2到+3失1e⁻，先定1:5；酸性用H₂O补O、H⁺补H，得MnO₄⁻+5Fe²⁺+8H⁺=Mn²⁺+5Fe³⁺+4H₂O。"],"visualSteps":["缺项配平","标价","电子守恒定骨架","按介质补H/O","电荷复核"]}]},{"title":"综合题四重校验","summary":"任何漂亮的式子都要经得起四项检查。","items":[{"label":"反应事实","rule":"产物、沉淀、气体、价态和介质必须合理。","examples":["【示范：同一离子方程式四重校验】检查MnO₄⁻与Fe²⁺反应：产物价态符合酸性介质；Mn、Fe、H、O原子数相等；左右总电荷均+17；Mn得5e⁻与5个Fe共失5e⁻相等。"],"visualSteps":["反应事实","反应事实","原子守恒","电荷守恒","电子守恒"]},{"label":"原子守恒","rule":"配平后的方程式左右两边，每一种元素的原子总数都相等。","examples":["【示范：同一离子方程式四重校验】检查MnO₄⁻与Fe²⁺反应：产物价态符合酸性介质；Mn、Fe、H、O原子数相等；左右总电荷均+17；Mn得5e⁻与5个Fe共失5e⁻相等。"],"visualSteps":["原子守恒","反应事实","原子守恒","电荷守恒","电子守恒"]},{"label":"电荷守恒","rule":"离子方程式左右两边各离子电荷的代数和必须相等。","examples":["【示范：同一离子方程式四重校验】检查MnO₄⁻与Fe²⁺反应：产物价态符合酸性介质；Mn、Fe、H、O原子数相等；左右总电荷均+17；Mn得5e⁻与5个Fe共失5e⁻相等。"],"visualSteps":["电荷守恒","反应事实","原子守恒","电荷守恒","电子守恒"]},{"label":"电子守恒","rule":"变价元素总升降数相等；还要检查系数是否最简。","examples":["【示范：同一离子方程式四重校验】检查MnO₄⁻与Fe²⁺反应：产物价态符合酸性介质；Mn、Fe、H、O原子数相等；左右总电荷均+17；Mn得5e⁻与5个Fe共失5e⁻相等。"],"visualSteps":["电子守恒","反应事实","原子守恒","电荷守恒","电子守恒"]}]}],"workedExamples":[{"substance":"BaCl₂与Na₂SO₄的净反应","path":"两溶液中可溶强电解质拆成离子，BaSO₄沉淀保留化学式，删去Na⁺、Cl⁻，得到Ba²⁺+SO₄²⁻=BaSO₄↓。","labels":["列真实粒子","保留沉淀","删除旁观离子","查原子电荷"]},{"substance":"无色强酸性溶液的共存","path":"把无色排除有色离子，把强酸性转成大量H⁺；再查沉淀、气体、弱电解质、氧化还原与双水解。HCO₃⁻会与H⁺反应，Fe²⁺还可能与酸性NO₃⁻发生氧化还原。","labels":["翻译条件","逐对排查","写证据反应","所有离子同时成立"]},{"substance":"CO₂通入NaOH的阶段图","path":"OH⁻足量时CO₂先变CO₃²⁻；CO₂继续加入时CO₃²⁻再变HCO₃⁻。根据少量/过量确定终点，必要时写两段式再按物质的量合并。","labels":["确定少量物","列阶段","判断竞争顺序","得到终点总式"]},{"substance":"酸性MnO₄⁻配Fe²⁺","path":"Mn从+7到+2得5e⁻，Fe从+2到+3失1e⁻，先定1:5；酸性用H₂O补O、H⁺补H，得MnO₄⁻+5Fe²⁺+8H⁺=Mn²⁺+5Fe³⁺+4H₂O。","labels":["标价","电子守恒定骨架","按介质补H/O","电荷复核"]},{"substance":"同一离子方程式四重校验","path":"检查MnO₄⁻与Fe²⁺反应：产物价态符合酸性介质；Mn、Fe、H、O原子数相等；左右总电荷均+17；Mn得5e⁻与5个Fe共失5e⁻相等。","labels":["反应事实","原子守恒","电荷守恒","电子守恒"]},{"substance":"酸性MnO₄⁻与Fe²⁺","path":"Mn(+7)得5e⁻变Mn²⁺，Fe²⁺失1e⁻变Fe³⁺，先定1:5；补H和O得MnO₄⁻+5Fe²⁺+8H⁺=Mn²⁺+5Fe³⁺+4H₂O；左右电荷均+17。","labels":["电子1:5","酸性补H⁺","原子电荷复核"]},{"substance":"过量CO₂通NaOH","path":"先CO₂+2OH⁻=CO₃²⁻+H₂O；继续通CO₂，CO₃²⁻+CO₂+H₂O=2HCO₃⁻。过量终点合并为CO₂+OH⁻=HCO₃⁻。","labels":["分阶段","看终点","合并总式"]}],"checkpoints":["我会先翻译离子共存题的隐含条件。","我能按用量决定离子方程式的最终产物。","我能在酸性或碱性介质中补齐氧化还原方程式。","我会做事实、原子、电荷、电子四重检查。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_ION_REDOX' and skill_id = 'H3_ION_REDOX';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H3_INORGANIC","version":2,"intro":"元素化合物知识量大，但组织方式很少：先画元素价态阶梯，再给每一种物质贴上类别标签，最后用反应条件连接转化。这样遇到陌生物质也能推，而不是背孤立方程式。","overview":["三条主轴：元素价态决定氧化还原方向，物质类别决定酸碱/离子反应，条件决定具体产物。","金属主线常见Na、Mg、Al、Fe、Cu；非金属主线常见Cl、S、N、C、Si及其化合物。","制备、检验、除杂必须形成“试剂—操作—现象—结论”闭环，并排除干扰。","陌生转化先守恒中心元素，再用题给性质、价态和条件预测。"],"sections":[{"title":"价态—类别—条件三维框架","summary":"每个反应都能在三条轴上定位。","items":[{"label":"价态轴","rule":"低价态常有还原性，高价态常有氧化性，中间价态可能兼有；具体强弱由物质和介质决定。","examples":["【示范：Fe的三条坐标轴】先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。"],"visualSteps":["价态轴","标价态","判物质类别","读反应条件","连接网络"]},{"label":"类别轴","rule":"氧化物、酸、碱、盐、单质各有通性；两性物质能在合适条件下与强酸和强碱反应。","examples":["【示范：Fe的三条坐标轴】先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。"],"visualSteps":["类别轴","标价态","判物质类别","读反应条件","连接网络"]},{"label":"条件轴","rule":"浓度、温度、酸碱介质、试剂用量、空气/光照可改变产物或反应程度。","examples":["【示范：Fe的三条坐标轴】先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。"],"visualSteps":["条件轴","标价态","判物质类别","读反应条件","连接网络"]},{"label":"网络轴","rule":"先守住中心元素，再看它从哪种价态和类别转到哪一种，方程式自然成为网络的连线。","examples":["【示范：Fe的三条坐标轴】先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。"],"visualSteps":["网络轴","标价态","判物质类别","读反应条件","连接网络"]}]},{"title":"常见金属主线","summary":"抓特征反应和价态转化，不背百科。","items":[{"label":"Na及其化合物","rule":"Na强还原性；Na₂O₂中O为-1；Na₂CO₃/NaHCO₃关注水解、热稳定性和转化。","examples":["【示范：Na、Al、Fe各抓一条主线】Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。"],"visualSteps":["Na及其化合物","结构性质","典型化合物","价态/两性转化","实验现象"]},{"label":"Al及其化合物","rule":"Al、Al₂O₃、Al(OH)₃具有典型两性；Al³⁺与OH⁻的少量/过量会出现沉淀生成与溶解。","examples":["【示范：Na、Al、Fe各抓一条主线】Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。"],"visualSteps":["Al及其化合物","结构性质","典型化合物","价态/两性转化","实验现象"]},{"label":"Fe及其化合物","rule":"Fe常见0、+2、+3价；Fe²⁺有还原性，Fe³⁺有氧化性，利用颜色、沉淀和KSCN等建立检验与转化。","examples":["【示范：Na、Al、Fe各抓一条主线】Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。"],"visualSteps":["Fe及其化合物","结构性质","典型化合物","价态/两性转化","实验现象"]},{"label":"金属制备与防护","rule":"活泼性决定冶炼方法的大方向；腐蚀防护从原电池电极反应解释。","examples":["【示范：Na、Al、Fe各抓一条主线】Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。"],"visualSteps":["金属制备与防护","结构性质","典型化合物","价态/两性转化","实验现象"]}]},{"title":"常见非金属主线","summary":"用氧化还原和酸碱性把族内物质连接起来。","items":[{"label":"Cl","rule":"Cl₂强氧化性，氯水多粒子共存，HClO负责氧化漂白和消毒；Cl⁻用酸化AgNO₃检验。","examples":["【示范：C、Si、N、S、Cl网络定位】C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。"],"visualSteps":["Cl","中心元素","常见价态","物质类别","条件与环境"]},{"label":"S","rule":"H₂S中S为-2、SO₂中+4、H₂SO₄中+6；SO₂兼有还原性、氧化性并具有特定漂白现象。","examples":["【示范：C、Si、N、S、Cl网络定位】C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。"],"visualSteps":["S","中心元素","常见价态","物质类别","条件与环境"]},{"label":"N","rule":"NH₃/NH₄⁺、N₂、NO/NO₂、HNO₃构成价态网络；NH₃制备检验、硝酸氧化性和氮氧化物转化常考。","examples":["【示范：C、Si、N、S、Cl网络定位】C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。"],"visualSteps":["N","中心元素","常见价态","物质类别","条件与环境"]},{"label":"C与Si","rule":"CO₂/碳酸盐平衡、CO还原性；SiO₂网络结构及无机非金属材料联系性质与用途。","examples":["【示范：C、Si、N、S、Cl网络定位】C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。"],"visualSteps":["C与Si","中心元素","常见价态","物质类别","条件与环境"]}]},{"title":"制备、检验和除杂","summary":"答案不能只写试剂名。","items":[{"label":"制备","rule":"选择原料和反应，控制条件，设计发生—净化—收集—尾气处理，兼顾安全和纯度。","examples":["【示范：Fe²⁺、Fe³⁺的检验和除杂】检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。"],"visualSteps":["制备","制备要防副反应","取样检验","先排干扰","选择性除杂"]},{"label":"检验","rule":"加入特异试剂，写操作和明显现象，再给不超出证据的结论。","examples":["【示范：Fe²⁺、Fe³⁺的检验和除杂】检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。"],"visualSteps":["检验","制备要防副反应","取样检验","先排干扰","选择性除杂"]},{"label":"除杂","rule":"除去杂质但不引入新杂质、不损失主体，试剂适量或过量后的处理要交代。","examples":["【示范：Fe²⁺、Fe³⁺的检验和除杂】检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。"],"visualSteps":["除杂","制备要防副反应","取样检验","先排干扰","选择性除杂"]},{"label":"鉴别","rule":"同一操作下产生不同现象，或设计最少步骤的顺序实验；先排除干扰。","examples":["【示范：Fe²⁺、Fe³⁺的检验和除杂】检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。"],"visualSteps":["鉴别","制备要防副反应","取样检验","先排干扰","选择性除杂"]}]},{"title":"陌生信息题的迁移","summary":"陌生名称不等于陌生规律。","items":[{"label":"读信息","rule":"把氧化性、溶解性、颜色、热稳定性或给定方程式标到物质节点上。","examples":["【示范：陌生钴化合物信息题】题给Co²⁺/Co³⁺颜色、电势或反应条件时，先抄出中心元素价态和物质类别；再判断氧化/还原、酸碱或配位变化，写方程式并用原子、电荷、电子守恒核验。"],"visualSteps":["读信息","读题给信息","映射熟悉模型","写反应","守恒校验"]},{"label":"守中心元素","rule":"跟踪目标元素在每一步的价态和去向，先判断反应类型。","examples":["【示范：陌生钴化合物信息题】题给Co²⁺/Co³⁺颜色、电势或反应条件时，先抄出中心元素价态和物质类别；再判断氧化/还原、酸碱或配位变化，写方程式并用原子、电荷、电子守恒核验。"],"visualSteps":["守中心元素","读题给信息","映射熟悉模型","写反应","守恒校验"]},{"label":"写并校验","rule":"根据介质和条件写方程式，再用电子、原子、电荷守恒核验。","examples":["【示范：陌生钴化合物信息题】题给Co²⁺/Co³⁺颜色、电势或反应条件时，先抄出中心元素价态和物质类别；再判断氧化/还原、酸碱或配位变化，写方程式并用原子、电荷、电子守恒核验。"],"visualSteps":["写并校验","读题给信息","映射熟悉模型","写反应","守恒校验"]}]}],"workedExamples":[{"substance":"Fe的三条坐标轴","path":"先在价态轴标Fe⁰、Fe²⁺、Fe³⁺；再在类别轴放入单质、氧化物/氢氧化物、盐；最后用酸碱性、氧化还原条件和配体信息连接转化。","labels":["标价态","判物质类别","读反应条件","连接网络"]},{"substance":"Na、Al、Fe各抓一条主线","path":"Na抓强还原性与Na₂O₂/碳酸盐；Al抓两性与Al³⁺—Al(OH)₃—含铝酸根；Fe抓0/+2/+3价互转及沉淀颜色。遇具体反应再按条件写方程式。","labels":["结构性质","典型化合物","价态/两性转化","实验现象"]},{"substance":"C、Si、N、S、Cl网络定位","path":"C/Si抓氧化物和酸盐，N/S抓多价态氧化还原及酸雨/工业转化，Cl抓Cl₂—HClO—Cl⁻。先追中心元素价态，再看介质和反应条件。","labels":["中心元素","常见价态","物质类别","条件与环境"]},{"substance":"Fe²⁺、Fe³⁺的检验和除杂","path":"检Fe³⁺可取样加KSCN显血红色；检Fe²⁺可用能给出特征现象且排除Fe³⁺干扰的方案。除去Fe³⁺而保留Mg²⁺时按题给沉淀pH范围调节并过滤。","labels":["制备要防副反应","取样检验","先排干扰","选择性除杂"]},{"substance":"陌生钴化合物信息题","path":"题给Co²⁺/Co³⁺颜色、电势或反应条件时，先抄出中心元素价态和物质类别；再判断氧化/还原、酸碱或配位变化，写方程式并用原子、电荷、电子守恒核验。","labels":["读题给信息","映射熟悉模型","写反应","守恒校验"]},{"substance":"Fe²⁺和Fe³⁺相互转化","path":"Fe²⁺失e⁻可变Fe³⁺，需氧化剂；Fe³⁺得e⁻可变Fe²⁺，需还原剂。检验Fe³⁺可用KSCN出现血红色，但该现象只能证明检出Fe³⁺。","labels":["价态轴","选氧化剂/还原剂","证据边界"]},{"substance":"Al³⁺中滴加NaOH至过量","path":"先Al³⁺+3OH⁻=Al(OH)₃↓；继续加OH⁻，两性氢氧化物溶解生成含铝酸根的溶液粒子。要根据苏教版题设采用相应表示式。","labels":["先沉淀","后溶解","少量过量"]}],"checkpoints":["我能为一种元素画出价态阶梯。","我能从类别通性预测反应而不是只背方程式。","我会把检验答案写成操作、现象、结论。","我能用题给信息解决陌生物质转化。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_INORGANIC' and skill_id = 'H3_INORGANIC';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H3_THERMO_RATE","version":2,"intro":"能量问题看始态和终态，速率问题看反应途径和有效碰撞。二者常出现在同一图或同一工业背景中，但ΔH、活化能、反应速率和平衡限度必须分开。","overview":["ΔH=生成物焓−反应物焓，只由始终态决定；反应式变形时ΔH同步变形。","活化能控制反应路径难易；催化剂降低能垒，不改变ΔH和K。","平均速率由浓度变化表示，不同物质速率按计量数换算。","工业条件同时考虑速率、平衡、能耗、成本与安全，不要求背精确参数。"],"sections":[{"title":"热化学基础补回","summary":"先判正负，再谈数值。","items":[{"label":"吸放热与ΔH","rule":"放热ΔH<0，吸热ΔH>0；反应式逆写ΔH变号，系数乘k则ΔH乘k。","examples":["【示范：燃烧反应的ΔH三种算法】由能量图可读生成物减反应物；由键能用断键总能−成键总能；由多步反应用盖斯定律相加。无论哪种方法，都先核对物态、系数和正负号。"],"visualSteps":["吸放热与ΔH","判吸放热","物态系数","选择能量/键能/盖斯","核对ΔH"]},{"label":"盖斯定律","rule":"反应热只与始终态有关，可把已知反应式线性组合得到目标反应。","examples":["【示范：燃烧反应的ΔH三种算法】由能量图可读生成物减反应物；由键能用断键总能−成键总能；由多步反应用盖斯定律相加。无论哪种方法，都先核对物态、系数和正负号。"],"visualSteps":["盖斯定律","判吸放热","物态系数","选择能量/键能/盖斯","核对ΔH"]},{"label":"键能法","rule":"ΔH≈断裂反应物化学键吸能总和−形成生成物化学键放能总和。","examples":["【示范：燃烧反应的ΔH三种算法】由能量图可读生成物减反应物；由键能用断键总能−成键总能；由多步反应用盖斯定律相加。无论哪种方法，都先核对物态、系数和正负号。"],"visualSteps":["键能法","判吸放热","物态系数","选择能量/键能/盖斯","核对ΔH"]}]},{"title":"反应历程图","summary":"横轴是历程，不是时间；纵轴通常是能量。","items":[{"label":"峰与谷","rule":"从反应物能级到峰顶的差是正反应活化能；中间谷可能对应中间体。","examples":["【示范：催化剂反应历程图】无催化路径峰高，加入催化剂出现另一条低峰路径；正逆活化能都降低，而始态、终态和ΔH不变。若图中有多个峰，峰谷间可对应中间体和分步反应。"],"visualSteps":["峰与谷","读始终态","看峰谷","比较活化能","区分路径与ΔH"]},{"label":"正逆活化能","rule":"正、逆活化能之差与ΔH相关；始终态能量差不因催化剂改变。","examples":["【示范：催化剂反应历程图】无催化路径峰高，加入催化剂出现另一条低峰路径；正逆活化能都降低，而始态、终态和ΔH不变。若图中有多个峰，峰谷间可对应中间体和分步反应。"],"visualSteps":["正逆活化能","读始终态","看峰谷","比较活化能","区分路径与ΔH"]},{"label":"催化路径","rule":"催化剂提供新的低能垒路径，可能增加步骤，但最高能垒降低。","examples":["【示范：催化剂反应历程图】无催化路径峰高，加入催化剂出现另一条低峰路径；正逆活化能都降低，而始态、终态和ΔH不变。若图中有多个峰，峰谷间可对应中间体和分步反应。"],"visualSteps":["催化路径","读始终态","看峰谷","比较活化能","区分路径与ΔH"]}]},{"title":"速率表示和影响因素","summary":"统一表示后再比较。","items":[{"label":"平均速率","rule":"v=|Δc|/Δt；不同物质表示的速率比等于系数比。","examples":["【示范：N₂+3H₂合成NH₃的速率因素】用Δc/Δt表示平均速率并按1:3:2换算；升温、增反应气分压、加催化剂通常提速。对题给基元步骤只据其信息判断，不自行套更高层次数学模型。"],"visualSteps":["平均速率","算平均速率","按系数换算","解释因素","题给机理优先"]},{"label":"浓度与压强","rule":"提高有效反应粒子的浓度或分压通常增加碰撞频率；恒容加惰性气体不改变反应组分浓度。","examples":["【示范：N₂+3H₂合成NH₃的速率因素】用Δc/Δt表示平均速率并按1:3:2换算；升温、增反应气分压、加催化剂通常提速。对题给基元步骤只据其信息判断，不自行套更高层次数学模型。"],"visualSteps":["浓度与压强","算平均速率","按系数换算","解释因素","题给机理优先"]},{"label":"温度","rule":"升温显著增加活化分子比例，使有效碰撞增加。","examples":["【示范：N₂+3H₂合成NH₃的速率因素】用Δc/Δt表示平均速率并按1:3:2换算；升温、增反应气分压、加催化剂通常提速。对题给基元步骤只据其信息判断，不自行套更高层次数学模型。"],"visualSteps":["温度","算平均速率","按系数换算","解释因素","题给机理优先"]},{"label":"催化剂和表面积","rule":"催化剂降低活化能；固体粉碎增大接触面积，两者机制不同。","examples":["【示范：N₂+3H₂合成NH₃的速率因素】用Δc/Δt表示平均速率并按1:3:2换算；升温、增反应气分压、加催化剂通常提速。对题给基元步骤只据其信息判断，不自行套更高层次数学模型。"],"visualSteps":["催化剂和表面积","算平均速率","按系数换算","解释因素","题给机理优先"]}]},{"title":"图表、实验与表达","summary":"答案要把数据趋势和化学原因连接起来。","items":[{"label":"浓度—时间曲线","rule":"斜率绝对值表示瞬时速率，平台可能是反应结束或达到平衡，需结合可逆性判断。","examples":["【示范：由曲线和实验表判断快慢】先读轴和单位，浓度—时间曲线斜率绝对值越大速率越快；实验表比较时只选其余条件相同的两组。若用初段数据算初速，要统一时间和浓度单位。"],"visualSteps":["浓度—时间曲线","图像读轴","斜率","控制变量","表格计算"]},{"label":"初速或表格比较","rule":"选择只有一个条件不同的实验组做对照；若多因素同时改变不能直接归因。","examples":["【示范：由曲线和实验表判断快慢】先读轴和单位，浓度—时间曲线斜率绝对值越大速率越快；实验表比较时只选其余条件相同的两组。若用初段数据算初速，要统一时间和浓度单位。"],"visualSteps":["初速或表格比较","图像读轴","斜率","控制变量","表格计算"]},{"label":"机理信息","rule":"高中只根据题给基元步骤、中间体或能垒信息判断快慢和催化作用，不展开大学动力学的定量理论。","examples":["【示范：由曲线和实验表判断快慢】先读轴和单位，浓度—时间曲线斜率绝对值越大速率越快；实验表比较时只选其余条件相同的两组。若用初段数据算初速，要统一时间和浓度单位。"],"visualSteps":["机理信息","图像读轴","斜率","控制变量","表格计算"]}]},{"title":"工业条件的多目标权衡","summary":"“平衡最有利”不一定等于“生产最合适”。","items":[{"label":"温度折中","rule":"温度影响速率和放/吸热反应的平衡方向，选择兼顾两者的条件。","examples":["【示范：合成氨为何不用最低温最高压】降低温度有利于放热平衡但速率下降；增压提高平衡转化率却增加设备成本和风险；催化剂提高速率不改K。最终条件在速率、转化率、能耗、安全和设备间折中。"],"visualSteps":["温度折中","分开速率与限度","温度折中","压强成本","安全能耗"]},{"label":"压强与浓度","rule":"提高反应物分压可加快速率，也可能改变气相平衡，但高压设备成本和安全要求更高。","examples":["【示范：合成氨为何不用最低温最高压】降低温度有利于放热平衡但速率下降；增压提高平衡转化率却增加设备成本和风险；催化剂提高速率不改K。最终条件在速率、转化率、能耗、安全和设备间折中。"],"visualSteps":["压强与浓度","分开速率与限度","温度折中","压强成本","安全能耗"]},{"label":"催化剂","rule":"提高单位时间产量并降低所需温度，但不提高平衡转化率。","examples":["【示范：合成氨为何不用最低温最高压】降低温度有利于放热平衡但速率下降；增压提高平衡转化率却增加设备成本和风险；催化剂提高速率不改K。最终条件在速率、转化率、能耗、安全和设备间折中。"],"visualSteps":["催化剂","分开速率与限度","温度折中","压强成本","安全能耗"]}]}],"workedExamples":[{"substance":"燃烧反应的ΔH三种算法","path":"由能量图可读生成物减反应物；由键能用断键总能−成键总能；由多步反应用盖斯定律相加。无论哪种方法，都先核对物态、系数和正负号。","labels":["判吸放热","物态系数","选择能量/键能/盖斯","核对ΔH"]},{"substance":"催化剂反应历程图","path":"无催化路径峰高，加入催化剂出现另一条低峰路径；正逆活化能都降低，而始态、终态和ΔH不变。若图中有多个峰，峰谷间可对应中间体和分步反应。","labels":["读始终态","看峰谷","比较活化能","区分路径与ΔH"]},{"substance":"N₂+3H₂合成NH₃的速率因素","path":"用Δc/Δt表示平均速率并按1:3:2换算；升温、增反应气分压、加催化剂通常提速。对题给基元步骤只据其信息判断，不自行套更高层次数学模型。","labels":["算平均速率","按系数换算","解释因素","题给机理优先"]},{"substance":"由曲线和实验表判断快慢","path":"先读轴和单位，浓度—时间曲线斜率绝对值越大速率越快；实验表比较时只选其余条件相同的两组。若用初段数据算初速，要统一时间和浓度单位。","labels":["图像读轴","斜率","控制变量","表格计算"]},{"substance":"合成氨为何不用最低温最高压","path":"降低温度有利于放热平衡但速率下降；增压提高平衡转化率却增加设备成本和风险；催化剂提高速率不改K。最终条件在速率、转化率、能耗、安全和设备间折中。","labels":["分开速率与限度","温度折中","压强成本","安全能耗"]},{"substance":"催化剂能量图","path":"催化曲线的始态和终态与无催化曲线相同，峰值更低；因此正逆反应活化能都降低、反应更快，而ΔH和一定温度下K不变。","labels":["路径变","始终态不变","速率变","限度不变"]},{"substance":"放热可逆反应升温","path":"升温使正逆速率都增大，反应更快；同时平衡向吸热的逆向移动，K减小。必须分别回答“速率”和“限度”。","labels":["速率都增大","平衡逆移","K减小"]}],"checkpoints":["我能区分ΔH、活化能、速率和K。","我会正确读取反应历程图的横纵轴。","我能设计单变量速率实验。","我能用多目标权衡解释工业条件。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_THERMO_RATE' and skill_id = 'H3_THERMO_RATE';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H3_EQUILIBRIUM","version":2,"intro":"高三平衡综合需要同时说清三件事：体系是否达到平衡、条件改变后向哪边移动、平衡能进行到什么限度。工具分别是平衡标志、v正/v逆或Q-K、三段式与K。","overview":["平衡是动态的：v正=v逆且不为0，各组分含量保持不变。","Q<K向右，Q>K向左，Q=K平衡；温度不变时K固定。","三段式用一个变化量按计量数展开，平衡量代入K并验根。","图像先读坐标和控制条件，再区分瞬间、过程、新平衡。","等效平衡的核心是相同条件下能否归算到相同的起始投料状态或相同平衡组成。"],"sections":[{"title":"状态：怎样确认平衡","summary":"标志必须对该反应具有判别力。","items":[{"label":"直接标志","rule":"同一反应的正逆速率相等；用不同物质表示时要按系数归一。","examples":["【示范：2NO₂⇌N₂O₄确认平衡】密闭恒温下颜色不再变化，说明NO₂浓度保持不变；微观上正逆反应仍继续且v正=v逆。若选总质量等本来恒定的量，则不能据此判平衡。"],"visualSteps":["直接标志","可逆体系","v正=v逆","可变宏观量不变","排除恒量"]},{"label":"组成不变","rule":"反应物或生成物浓度、物质的量分数、颜色等不再变化。","examples":["【示范：2NO₂⇌N₂O₄确认平衡】密闭恒温下颜色不再变化，说明NO₂浓度保持不变；微观上正逆反应仍继续且v正=v逆。若选总质量等本来恒定的量，则不能据此判平衡。"],"visualSteps":["组成不变","可逆体系","v正=v逆","可变宏观量不变","排除恒量"]},{"label":"总量指标的条件","rule":"总压、密度、平均摩尔质量等只有在随反应进程会改变时，其不变才是有效标志。","examples":["【示范：2NO₂⇌N₂O₄确认平衡】密闭恒温下颜色不再变化，说明NO₂浓度保持不变；微观上正逆反应仍继续且v正=v逆。若选总质量等本来恒定的量，则不能据此判平衡。"],"visualSteps":["总量指标的条件","可逆体系","v正=v逆","可变宏观量不变","排除恒量"]}]},{"title":"方向：速率法与Q-K法","summary":"两种方法应给出同一结论。","items":[{"label":"速率法","rule":"条件改变瞬间v正>v逆向右，v正<v逆向左。","examples":["【示范：放热反应升温的速率法和Q-K法】升温瞬间正逆速率都增大但逆向增幅更大，故左移；也可由升温使放热反应K减小，而瞬间组成未变、Q仍为旧K，所以Q>K向左。"],"visualSteps":["速率法","瞬间速率比较","判断移动","温度改变K","Q与新K比较"]},{"label":"Q-K法","rule":"把当前组成代入反应商；Q<K向正方向，Q>K向逆方向。","examples":["【示范：放热反应升温的速率法和Q-K法】升温瞬间正逆速率都增大但逆向增幅更大，故左移；也可由升温使放热反应K减小，而瞬间组成未变、Q仍为旧K，所以Q>K向左。"],"visualSteps":["Q-K法","瞬间速率比较","判断移动","温度改变K","Q与新K比较"]},{"label":"勒夏特列法","rule":"用于定性判断浓度、压强、温度影响；对复杂或多条件题优先用Q-K更稳。","examples":["【示范：放热反应升温的速率法和Q-K法】升温瞬间正逆速率都增大但逆向增幅更大，故左移；也可由升温使放热反应K减小，而瞬间组成未变、Q仍为旧K，所以Q>K向左。"],"visualSteps":["勒夏特列法","瞬间速率比较","判断移动","温度改变K","Q与新K比较"]}]},{"title":"限度：K、转化率和三段式","summary":"K是平衡定量的中心。","items":[{"label":"K表达式","rule":"按平衡浓度/分压和计量数书写，纯固体纯液体通常不写。","examples":["【示范：A+B⇌2C的三段式和转化率】由起始量列-x、-x、+2x，写平衡浓度并代K；解出x后检查非负，再算某反应物转化率=x/初始量。反应倒转K取倒数，系数倍乘K取幂。"],"visualSteps":["K表达式","写K","三段式","验根","算转化率"]},{"label":"三段式","rule":"起始—变化—平衡，变化量服从计量数，代入K求解并排除负浓度等无意义根。","examples":["【示范：A+B⇌2C的三段式和转化率】由起始量列-x、-x、+2x，写平衡浓度并代K；解出x后检查非负，再算某反应物转化率=x/初始量。反应倒转K取倒数，系数倍乘K取幂。"],"visualSteps":["三段式","写K","三段式","验根","算转化率"]},{"label":"转化率与产率","rule":"转化率的分母是某反应物初始量；条件改变时K可能不变但转化率可变。","examples":["【示范：A+B⇌2C的三段式和转化率】由起始量列-x、-x、+2x，写平衡浓度并代K；解出x后检查非负，再算某反应物转化率=x/初始量。反应倒转K取倒数，系数倍乘K取幂。"],"visualSteps":["转化率与产率","写K","三段式","验根","算转化率"]},{"label":"反应式变换","rule":"逆反应K倒数，系数倍乘K取幂，多反应相加K相乘。","examples":["【示范：A+B⇌2C的三段式和转化率】由起始量列-x、-x、+2x，写平衡浓度并代K；解出x后检查非负，再算某反应物转化率=x/初始量。反应倒转K取倒数，系数倍乘K取幂。"],"visualSteps":["反应式变换","写K","三段式","验根","算转化率"]}]},{"title":"平衡图像的读取","summary":"任何图都先说清横轴改变了什么。","items":[{"label":"浓度—时间","rule":"突变表示瞬间直接改变的物质；随后曲线方向反映移动；新平台是新平衡。","examples":["【示范：浓度突变图完整读法】某反应物曲线在t时刻竖直上跳，表示直接加入；随后它下降、生成物上升，表示向正向移动；新平台表示新平衡。温度不变，所以新旧K相同。"],"visualSteps":["浓度—时间","读轴","找瞬间跳变","看随后趋势","判断新平台"]},{"label":"速率—时间","rule":"条件改变瞬间正逆速率的跳变大小决定移动方向，最终重新相等。","examples":["【示范：浓度突变图完整读法】某反应物曲线在t时刻竖直上跳，表示直接加入；随后它下降、生成物上升，表示向正向移动；新平台表示新平衡。温度不变，所以新旧K相同。"],"visualSteps":["速率—时间","读轴","找瞬间跳变","看随后趋势","判断新平台"]},{"label":"转化率—温度/压强","rule":"结合反应热和气体计量数判断趋势；催化剂只影响达到平衡速度，不改变平衡曲线终值。","examples":["【示范：浓度突变图完整读法】某反应物曲线在t时刻竖直上跳，表示直接加入；随后它下降、生成物上升，表示向正向移动；新平台表示新平衡。温度不变，所以新旧K相同。"],"visualSteps":["转化率—温度/压强","读轴","找瞬间跳变","看随后趋势","判断新平台"]},{"label":"控制变量","rule":"比较曲线前先确认除横轴外其他条件相同，不能把浓度和温度效应混在一起。","examples":["【示范：浓度突变图完整读法】某反应物曲线在t时刻竖直上跳，表示直接加入；随后它下降、生成物上升，表示向正向移动；新平台表示新平衡。温度不变，所以新旧K相同。"],"visualSteps":["控制变量","读轴","找瞬间跳变","看随后趋势","判断新平台"]}]},{"title":"等效平衡与工业优化","summary":"先归算投料，再谈是否等效。","items":[{"label":"恒温恒容","rule":"对反应前后气体物质的量改变的体系，通常要求归算后的各物质起始量相同才能得到相同平衡。","examples":["【示范：等效平衡和工业条件】恒温恒容时先把投料按反应计量关系归算到同一侧，再比较起始量；恒温恒压还要看投料比例与体积条件。工业选择同时考虑平衡组成、到达速度、设备成本和安全。"],"visualSteps":["恒温恒容","确认容器条件","归算投料","判断等效","多目标优化"]},{"label":"恒温恒压","rule":"按相同投料比例可能得到组成相同的平衡，具体结合反应和容器条件判断。","examples":["【示范：等效平衡和工业条件】恒温恒容时先把投料按反应计量关系归算到同一侧，再比较起始量；恒温恒压还要看投料比例与体积条件。工业选择同时考虑平衡组成、到达速度、设备成本和安全。"],"visualSteps":["恒温恒压","确认容器条件","归算投料","判断等效","多目标优化"]},{"label":"工业优化","rule":"高转化率、快速率、低成本、低能耗和安全之间折中；催化剂加快速率而不改K。","examples":["【示范：等效平衡和工业条件】恒温恒容时先把投料按反应计量关系归算到同一侧，再比较起始量；恒温恒压还要看投料比例与体积条件。工业选择同时考虑平衡组成、到达速度、设备成本和安全。"],"visualSteps":["工业优化","确认容器条件","归算投料","判断等效","多目标优化"]}]}],"workedExamples":[{"substance":"2NO₂⇌N₂O₄确认平衡","path":"密闭恒温下颜色不再变化，说明NO₂浓度保持不变；微观上正逆反应仍继续且v正=v逆。若选总质量等本来恒定的量，则不能据此判平衡。","labels":["可逆体系","v正=v逆","可变宏观量不变","排除恒量"]},{"substance":"放热反应升温的速率法和Q-K法","path":"升温瞬间正逆速率都增大但逆向增幅更大，故左移；也可由升温使放热反应K减小，而瞬间组成未变、Q仍为旧K，所以Q>K向左。","labels":["瞬间速率比较","判断移动","温度改变K","Q与新K比较"]},{"substance":"A+B⇌2C的三段式和转化率","path":"由起始量列-x、-x、+2x，写平衡浓度并代K；解出x后检查非负，再算某反应物转化率=x/初始量。反应倒转K取倒数，系数倍乘K取幂。","labels":["写K","三段式","验根","算转化率"]},{"substance":"浓度突变图完整读法","path":"某反应物曲线在t时刻竖直上跳，表示直接加入；随后它下降、生成物上升，表示向正向移动；新平台表示新平衡。温度不变，所以新旧K相同。","labels":["读轴","找瞬间跳变","看随后趋势","判断新平台"]},{"substance":"等效平衡和工业条件","path":"恒温恒容时先把投料按反应计量关系归算到同一侧，再比较起始量；恒温恒压还要看投料比例与体积条件。工业选择同时考虑平衡组成、到达速度、设备成本和安全。","labels":["确认容器条件","归算投料","判断等效","多目标优化"]},{"substance":"浓度突变图","path":"某反应物浓度在t时刻竖直升高，说明直接加入该反应物；随后其浓度下降、生成物上升，说明平衡向右；最终各浓度到新平台，K因温度不变而不变。","labels":["瞬间跳变","过程方向","新平台","K不变"]},{"substance":"Q-K方向判断","path":"A+B⇌2C，K=4。某时刻c(A)=c(B)=1、c(C)=1，则Q=1²/(1×1)=1<K，体系向右，直到Q增至4。","labels":["写Q","比较K","方向"]}],"checkpoints":["我能分别回答状态、方向和限度。","我会选择速率法或Q-K法判断移动。","我能读出图中的瞬间变化和渐变。","我能列三段式并判断解是否合理。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_EQUILIBRIUM' and skill_id = 'H3_EQUILIBRIUM';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H3_AQ","version":2,"intro":"水溶液综合的底层是“粒子+平衡+守恒”。先列实际粒子和主要反应，再写Ka、Kb、Kw或Ksp控制趋势，最后用电荷、物料、质子守恒锁定数量。","overview":["弱电解质部分电离，盐可能水解，水始终微弱电离；粒子种类先列全。","Kw、Ka、Kb、Kh、Ksp在一定温度下固定，外界改变通过Q与K决定平衡方向。","电荷守恒适用于所有溶液，物料守恒跟踪来源，质子守恒联系酸碱转移。","滴定曲线按滴定前—缓冲/混合区—化学计量点—过量区分段。","沉淀问题用Qsp-Ksp；“沉淀完全”是低于题给残余标准，不是浓度为0。"],"sections":[{"title":"粒子清单和主次判断","summary":"先决定谁大量存在，谁只是微量。","items":[{"label":"完全电离来源","rule":"强酸、强碱、可溶性盐先按化学计量数给出主要离子。","examples":["【示范：CH₃COONa溶液粒子清单】先完全电离得Na⁺、CH₃COO⁻；再由CH₃COO⁻水解补CH₃COOH、OH⁻，水还贡献极少H⁺。主要粒子先列，微弱平衡后处理。"],"visualSteps":["完全电离来源","完全电离","找弱者水解","列全部粒子","分主次"]},{"label":"弱平衡来源","rule":"弱酸弱碱分子与离子共存；能水解的盐离子、水的H⁺和OH⁻都要列入。","examples":["【示范：CH₃COONa溶液粒子清单】先完全电离得Na⁺、CH₃COO⁻；再由CH₃COO⁻水解补CH₃COOH、OH⁻，水还贡献极少H⁺。主要粒子先列，微弱平衡后处理。"],"visualSteps":["弱平衡来源","完全电离","找弱者水解","列全部粒子","分主次"]},{"label":"主次关系","rule":"强反应先做完全，再处理剩余粒子的弱电离、水解或沉淀平衡。","examples":["【示范：CH₃COONa溶液粒子清单】先完全电离得Na⁺、CH₃COO⁻；再由CH₃COO⁻水解补CH₃COOH、OH⁻，水还贡献极少H⁺。主要粒子先列，微弱平衡后处理。"],"visualSteps":["主次关系","完全电离","找弱者水解","列全部粒子","分主次"]}]},{"title":"四类常数的统一理解","summary":"表达式不同，逻辑都是平衡时Q=K。","items":[{"label":"Ka/Kb","rule":"描述弱酸/弱碱电离；同温下越大通常越强。","examples":["【示范：Ka、Kw、Ksp放在同一框架】醋酸电离用Ka，水用Kw，AgCl溶解用Ksp；三者都由相应平衡式写浓度幂之比且在一定温度下固定。外界改变先改变Q，再由Q与K判方向。"],"visualSteps":["Ka/Kb","写平衡式","写常数","温度条件","Q-K方向"]},{"label":"Kw","rule":"Kw=c(H⁺)c(OH⁻)，只随温度；中性为两者相等。","examples":["【示范：Ka、Kw、Ksp放在同一框架】醋酸电离用Ka，水用Kw，AgCl溶解用Ksp；三者都由相应平衡式写浓度幂之比且在一定温度下固定。外界改变先改变Q，再由Q与K判方向。"],"visualSteps":["Kw","写平衡式","写常数","温度条件","Q-K方向"]},{"label":"水解常数","rule":"共轭酸碱的水解可由相应Ka或Kb联系，具体按题给关系使用。","examples":["【示范：Ka、Kw、Ksp放在同一框架】醋酸电离用Ka，水用Kw，AgCl溶解用Ksp；三者都由相应平衡式写浓度幂之比且在一定温度下固定。外界改变先改变Q，再由Q与K判方向。"],"visualSteps":["水解常数","写平衡式","写常数","温度条件","Q-K方向"]},{"label":"Ksp","rule":"描述难溶电解质的溶解平衡；表达式含离子浓度的计量数次方。","examples":["【示范：Ka、Kw、Ksp放在同一框架】醋酸电离用Ka，水用Kw，AgCl溶解用Ksp；三者都由相应平衡式写浓度幂之比且在一定温度下固定。外界改变先改变Q，再由Q与K判方向。"],"visualSteps":["Ksp","写平衡式","写常数","温度条件","Q-K方向"]}]},{"title":"离子浓度排序与三大守恒","summary":"先守恒，再比较平衡强弱。","items":[{"label":"电荷守恒","rule":"正电荷浓度总和=负电荷浓度总和，多价离子乘电荷数。","examples":["【示范：CH₃COONa的浓度排序与守恒】由完全电离和少量水解知c(Na⁺)>c(CH₃COO⁻)>c(OH⁻)>c(H⁺)常为合理主次；再用物料守恒与电荷守恒核对，不能只背排序。"],"visualSteps":["电荷守恒","先判主要粒子","比较弱平衡","写物料守恒","写电荷守恒"]},{"label":"物料守恒","rule":"某元素或某组分所有存在形态的浓度之和等于投入总量关系。","examples":["【示范：CH₃COONa的浓度排序与守恒】由完全电离和少量水解知c(Na⁺)>c(CH₃COO⁻)>c(OH⁻)>c(H⁺)常为合理主次；再用物料守恒与电荷守恒核对，不能只背排序。"],"visualSteps":["物料守恒","先判主要粒子","比较弱平衡","写物料守恒","写电荷守恒"]},{"label":"质子守恒","rule":"由质子转移建立，可由电荷和物料守恒组合；写时明确参考态。","examples":["【示范：CH₃COONa的浓度排序与守恒】由完全电离和少量水解知c(Na⁺)>c(CH₃COO⁻)>c(OH⁻)>c(H⁺)常为合理主次；再用物料守恒与电荷守恒核对，不能只背排序。"],"visualSteps":["质子守恒","先判主要粒子","比较弱平衡","写物料守恒","写电荷守恒"]},{"label":"排序步骤","rule":"先比较大量的完全电离离子，再用电离/水解程度比较次要粒子，最后用守恒式核查。","examples":["【示范：CH₃COONa的浓度排序与守恒】由完全电离和少量水解知c(Na⁺)>c(CH₃COO⁻)>c(OH⁻)>c(H⁺)常为合理主次；再用物料守恒与电荷守恒核对，不能只背排序。"],"visualSteps":["排序步骤","先判主要粒子","比较弱平衡","写物料守恒","写电荷守恒"]}]},{"title":"pH与滴定曲线","summary":"每个区段的主要粒子不同，算法也不同。","items":[{"label":"滴定前","rule":"由待测酸碱本身决定；弱电解质需Ka/Kb。","examples":["【示范：强酸滴定弱碱曲线】滴定前用Kb；混合区先完全反应；计量点为共轭酸盐水解，pH通常<7；强酸过量后由剩余H⁺决定。指示剂变色范围要落在突跃内。"],"visualSteps":["滴定前","滴定前","混合反应","计量点水解","过量与终点"]},{"label":"反应进行中","rule":"先做n(H⁺)/n(OH⁻)或酸碱化学计量反应，再处理剩余和共轭体系。","examples":["【示范：强酸滴定弱碱曲线】滴定前用Kb；混合区先完全反应；计量点为共轭酸盐水解，pH通常<7；强酸过量后由剩余H⁺决定。指示剂变色范围要落在突跃内。"],"visualSteps":["反应进行中","滴定前","混合反应","计量点水解","过量与终点"]},{"label":"化学计量点","rule":"恰好反应完全不等于pH=7；强弱组合决定产物水解。","examples":["【示范：强酸滴定弱碱曲线】滴定前用Kb；混合区先完全反应；计量点为共轭酸盐水解，pH通常<7；强酸过量后由剩余H⁺决定。指示剂变色范围要落在突跃内。"],"visualSteps":["化学计量点","滴定前","混合反应","计量点水解","过量与终点"]},{"label":"过量区","rule":"由过量强酸或强碱主导；计算用混合后总体积。","examples":["【示范：强酸滴定弱碱曲线】滴定前用Kb；混合区先完全反应；计量点为共轭酸盐水解，pH通常<7；强酸过量后由剩余H⁺决定。指示剂变色范围要落在突跃内。"],"visualSteps":["过量区","滴定前","混合反应","计量点水解","过量与终点"]},{"label":"指示剂与终点","rule":"指示剂变色区间应落在pH突跃内；终点是实验指示，化学计量点是理论点。","examples":["【示范：强酸滴定弱碱曲线】滴定前用Kb；混合区先完全反应；计量点为共轭酸盐水解，pH通常<7；强酸过量后由剩余H⁺决定。指示剂变色范围要落在突跃内。"],"visualSteps":["指示剂与终点","滴定前","混合反应","计量点水解","过量与终点"]}]},{"title":"沉淀溶解与综合分离","summary":"把瞬时离子积与平衡限度分开。","items":[{"label":"Qsp判断","rule":"混合后先求瞬时浓度，Qsp>Ksp析出，Qsp<Ksp未饱和。","examples":["【示范：调pH分离Fe³⁺和Mg²⁺】按题给Ksp或沉淀pH范围，选择一个窗口使Fe(OH)₃的Qsp>Ksp充分沉淀，而Mg(OH)₂仍Qsp<Ksp；过滤分离。酸耗OH⁻可促氢氧化物溶解。"],"visualSteps":["Qsp判断","算瞬时Qsp","选择pH窗口","控制选择沉淀","说明完全标准"]},{"label":"pH控制","rule":"OH⁻或弱酸根浓度随pH变化，可用于分步沉淀、溶解和分离。","examples":["【示范：调pH分离Fe³⁺和Mg²⁺】按题给Ksp或沉淀pH范围，选择一个窗口使Fe(OH)₃的Qsp>Ksp充分沉淀，而Mg(OH)₂仍Qsp<Ksp；过滤分离。酸耗OH⁻可促氢氧化物溶解。"],"visualSteps":["pH控制","算瞬时Qsp","选择pH窗口","控制选择沉淀","说明完全标准"]},{"label":"沉淀转化","rule":"消耗一种离子或生成更稳定沉淀能推动转化；定量时构造总平衡常数。","examples":["【示范：调pH分离Fe³⁺和Mg²⁺】按题给Ksp或沉淀pH范围，选择一个窗口使Fe(OH)₃的Qsp>Ksp充分沉淀，而Mg(OH)₂仍Qsp<Ksp；过滤分离。酸耗OH⁻可促氢氧化物溶解。"],"visualSteps":["沉淀转化","算瞬时Qsp","选择pH窗口","控制选择沉淀","说明完全标准"]}]}],"workedExamples":[{"substance":"CH₃COONa溶液粒子清单","path":"先完全电离得Na⁺、CH₃COO⁻；再由CH₃COO⁻水解补CH₃COOH、OH⁻，水还贡献极少H⁺。主要粒子先列，微弱平衡后处理。","labels":["完全电离","找弱者水解","列全部粒子","分主次"]},{"substance":"Ka、Kw、Ksp放在同一框架","path":"醋酸电离用Ka，水用Kw，AgCl溶解用Ksp；三者都由相应平衡式写浓度幂之比且在一定温度下固定。外界改变先改变Q，再由Q与K判方向。","labels":["写平衡式","写常数","温度条件","Q-K方向"]},{"substance":"CH₃COONa的浓度排序与守恒","path":"由完全电离和少量水解知c(Na⁺)>c(CH₃COO⁻)>c(OH⁻)>c(H⁺)常为合理主次；再用物料守恒与电荷守恒核对，不能只背排序。","labels":["先判主要粒子","比较弱平衡","写物料守恒","写电荷守恒"]},{"substance":"强酸滴定弱碱曲线","path":"滴定前用Kb；混合区先完全反应；计量点为共轭酸盐水解，pH通常<7；强酸过量后由剩余H⁺决定。指示剂变色范围要落在突跃内。","labels":["滴定前","混合反应","计量点水解","过量与终点"]},{"substance":"调pH分离Fe³⁺和Mg²⁺","path":"按题给Ksp或沉淀pH范围，选择一个窗口使Fe(OH)₃的Qsp>Ksp充分沉淀，而Mg(OH)₂仍Qsp<Ksp；过滤分离。酸耗OH⁻可促氢氧化物溶解。","labels":["算瞬时Qsp","选择pH窗口","控制选择沉淀","说明完全标准"]},{"substance":"CH₃COONa溶液浓度关系","path":"Na⁺来自完全电离，CH₃COO⁻部分水解生成CH₃COOH和OH⁻。物料守恒c(Na⁺)=c(CH₃COO⁻)+c(CH₃COOH)；电荷守恒c(Na⁺)+c(H⁺)=c(CH₃COO⁻)+c(OH⁻)。","labels":["先列粒子","物料守恒","电荷守恒","显碱性"]},{"substance":"强酸滴定弱碱计量点","path":"计量点时弱碱恰好转化为其共轭酸盐；共轭酸发生水解产生H⁺，因此计量点通常显酸性，pH<7（常温常规条件）。","labels":["先完全反应","产物水解","计量点不等于中性"]}],"checkpoints":["我能先列粒子再写平衡。","我会用守恒关系检查离子浓度排序。","我能分段分析滴定曲线。","我会用Qsp-Ksp而不是“看起来难溶”判断沉淀。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_AQ' and skill_id = 'H3_AQ';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H3_ELECTRO","version":2,"intro":"高三电化学装置可以很陌生，但解法稳定：判能量来源和装置类型，找氧化还原两端，写电极反应，按电中性判断膜迁移，最后用电子守恒做定量。","overview":["阳极氧化、阴极还原恒成立；原电池负极=阳极、正极=阴极。","电子经外电路移动，离子在电解质/膜中移动；不能让电子穿膜。","电极反应受介质影响，H⁺、OH⁻、H₂O必须按酸碱环境配平。","新型电池先找总反应和变价元素，充放电方向要分开。","定量统一到e⁻：两极、串联池、物质变化和电量都由电子守恒连接。"],"sections":[{"title":"装置类型与四个极名","summary":"先判原电池/电解池，再翻译极名。","items":[{"label":"原电池放电","rule":"自发反应输出电能：负极（阳极）氧化，正极（阴极）还原。","examples":["【示范：同一电池放电和充电】放电是原电池：负极氧化、正极还原；充电是电解池：阳极接电源正极氧化、阴极接负极还原。同一物理电极的氧化/还原及阴、阳极角色会反向，正负端按当前连接判断。"],"visualSteps":["原电池放电","先判放电/充电","看电源连接","定阴阳极","写氧化还原"]},{"label":"电解池","rule":"外加电源输入电能：阳极接正极并氧化，阴极接负极并还原。","examples":["【示范：同一电池放电和充电】放电是原电池：负极氧化、正极还原；充电是电解池：阳极接电源正极氧化、阴极接负极还原。同一物理电极的氧化/还原及阴、阳极角色会反向，正负端按当前连接判断。"],"visualSteps":["电解池","先判放电/充电","看电源连接","定阴阳极","写氧化还原"]},{"label":"充电电池","rule":"放电时是原电池，充电时是电解池；同一物理电极在充、放电时发生的氧化/还原反应及阴、阳极角色反向，判断正负端要看当前过程和电源连接。","examples":["【示范：同一电池放电和充电】放电是原电池：负极氧化、正极还原；充电是电解池：阳极接电源正极氧化、阴极接负极还原。同一物理电极的氧化/还原及阴、阳极角色会反向，正负端按当前连接判断。"],"visualSteps":["充电电池","先判放电/充电","看电源连接","定阴阳极","写氧化还原"]}]},{"title":"电极式从总反应反推","summary":"陌生装置不必先认识名称。","items":[{"label":"找变价元素","rule":"从总反应或物质变化判断谁失电子、谁得电子。","examples":["【示范：碱性氢氧燃料电池电极式】阳极H₂+2OH⁻-2e⁻=2H₂O；阴极O₂+2H₂O+4e⁻=4OH⁻。两式配成4e⁻后相加得到2H₂+O₂=2H₂O，并与介质中粒子变化核对。"],"visualSteps":["找变价元素","找变价","写骨架","按碱性介质配平","相加得总式"]},{"label":"写骨架","rule":"阳极把还原态写到左边并在右边放e⁻；阴极把氧化态和e⁻写左边。","examples":["【示范：碱性氢氧燃料电池电极式】阳极H₂+2OH⁻-2e⁻=2H₂O；阴极O₂+2H₂O+4e⁻=4OH⁻。两式配成4e⁻后相加得到2H₂+O₂=2H₂O，并与介质中粒子变化核对。"],"visualSteps":["写骨架","找变价","写骨架","按碱性介质配平","相加得总式"]},{"label":"按介质配平","rule":"酸性常用H⁺、H₂O，碱性常用OH⁻、H₂O；固体氧化物电解质还要跟踪O²⁻。","examples":["【示范：碱性氢氧燃料电池电极式】阳极H₂+2OH⁻-2e⁻=2H₂O；阴极O₂+2H₂O+4e⁻=4OH⁻。两式配成4e⁻后相加得到2H₂+O₂=2H₂O，并与介质中粒子变化核对。"],"visualSteps":["按介质配平","找变价","写骨架","按碱性介质配平","相加得总式"]},{"label":"相加核对","rule":"电子消去后应得到总反应，且与两极质量、气体和溶液pH变化一致。","examples":["【示范：碱性氢氧燃料电池电极式】阳极H₂+2OH⁻-2e⁻=2H₂O；阴极O₂+2H₂O+4e⁻=4OH⁻。两式配成4e⁻后相加得到2H₂+O₂=2H₂O，并与介质中粒子变化核对。"],"visualSteps":["相加核对","找变价","写骨架","按碱性介质配平","相加得总式"]}]},{"title":"膜与离子迁移","summary":"电荷在哪里增加，就要有相反电荷补偿。","items":[{"label":"盐桥","rule":"阴离子移向产生阳离子的负极区，阳离子移向消耗阳离子的正极区。","examples":["【示范：三室电解槽的膜方向】先写两极反应，标每室哪些阳/阴离子增加或减少；阳膜只让阳离子主要通过，阴膜只让阴离子主要通过；按电场与电中性共同确定迁移方向和物质的量。"],"visualSteps":["盐桥","两极反应","各室电荷账","膜选择性","电子数对应迁移量"]},{"label":"交换膜","rule":"阳膜允许阳离子主要通过，阴膜允许阴离子主要通过；方向由电场和电中性共同决定。","examples":["【示范：三室电解槽的膜方向】先写两极反应，标每室哪些阳/阴离子增加或减少；阳膜只让阳离子主要通过，阴膜只让阴离子主要通过；按电场与电中性共同确定迁移方向和物质的量。"],"visualSteps":["交换膜","两极反应","各室电荷账","膜选择性","电子数对应迁移量"]},{"label":"多室装置","rule":"逐室做电荷账：电极产生/消耗哪些离子，膜允许谁通过，溶液浓度和pH如何变化。","examples":["【示范：三室电解槽的膜方向】先写两极反应，标每室哪些阳/阴离子增加或减少；阳膜只让阳离子主要通过，阴膜只让阴离子主要通过；按电场与电中性共同确定迁移方向和物质的量。"],"visualSteps":["多室装置","两极反应","各室电荷账","膜选择性","电子数对应迁移量"]},{"label":"物质跨膜数","rule":"由每转移一定mol e⁻产生的净电荷数确定迁移离子量。","examples":["【示范：三室电解槽的膜方向】先写两极反应，标每室哪些阳/阴离子增加或减少；阳膜只让阳离子主要通过，阴膜只让阴离子主要通过；按电场与电中性共同确定迁移方向和物质的量。"],"visualSteps":["物质跨膜数","两极反应","各室电荷账","膜选择性","电子数对应迁移量"]}]},{"title":"常见装置与应用","summary":"用同一规则解释，不背设备外形。","items":[{"label":"燃料电池","rule":"燃料在阳极被氧化，氧化剂在阴极被还原；产物和电极式取决于酸、碱、熔融盐或固体氧化物介质。","examples":["【示范：燃料电池、精炼和腐蚀】燃料电池中燃料在阳极氧化；电解精炼时粗金属作阳极、纯金属在阴极析出；牺牲阳极保护让更活泼金属先氧化。每套装置都回到“阳极氧化、阴极还原”。"],"visualSteps":["燃料电池","判装置目的","阳极氧化","阴极还原","联系应用"]},{"label":"二次电池","rule":"放电总反应自发，充电总反应逆向；标注题目讨论的是充电还是放电。","examples":["【示范：燃料电池、精炼和腐蚀】燃料电池中燃料在阳极氧化；电解精炼时粗金属作阳极、纯金属在阴极析出；牺牲阳极保护让更活泼金属先氧化。每套装置都回到“阳极氧化、阴极还原”。"],"visualSteps":["二次电池","判装置目的","阳极氧化","阴极还原","联系应用"]},{"label":"电解精炼/电镀","rule":"精炼时粗金属阳极溶解、纯金属阴极析出；电镀件作阴极，镀层金属离子在阴极还原。","examples":["【示范：燃料电池、精炼和腐蚀】燃料电池中燃料在阳极氧化；电解精炼时粗金属作阳极、纯金属在阴极析出；牺牲阳极保护让更活泼金属先氧化。每套装置都回到“阳极氧化、阴极还原”。"],"visualSteps":["电解精炼/电镀","判装置目的","阳极氧化","阴极还原","联系应用"]},{"label":"腐蚀防护","rule":"牺牲阳极、外加电流和涂层保护分别从改变电极角色或隔绝介质解释。","examples":["【示范：燃料电池、精炼和腐蚀】燃料电池中燃料在阳极氧化；电解精炼时粗金属作阳极、纯金属在阴极析出；牺牲阳极保护让更活泼金属先氧化。每套装置都回到“阳极氧化、阴极还原”。"],"visualSteps":["腐蚀防护","判装置目的","阳极氧化","阴极还原","联系应用"]}]},{"title":"电子守恒定量","summary":"无论装置多复杂，电子账必须相等。","items":[{"label":"半反应系数","rule":"先读出生成1 mol产物需要或放出几mol e⁻。","examples":["【示范：串联电解池电子守恒】第一池析出0.10 mol Cu，由Cu²⁺+2e⁻=Cu知通过0.20 mol e⁻；串联第二池同样通过0.20 mol e⁻，再按其电极式求气体、质量或pH变化。"],"visualSteps":["半反应系数","由已知产物求e⁻","串联电量相同","按半反应换算","考虑总体积"]},{"label":"串联电解池","rule":"串联各池通过的电量相同，所以转移电子的物质的量相同。","examples":["【示范：串联电解池电子守恒】第一池析出0.10 mol Cu，由Cu²⁺+2e⁻=Cu知通过0.20 mol e⁻；串联第二池同样通过0.20 mol e⁻，再按其电极式求气体、质量或pH变化。"],"visualSteps":["串联电解池","由已知产物求e⁻","串联电量相同","按半反应换算","考虑总体积"]},{"label":"质量/气体/pH","rule":"由n(e⁻)经电极式转成金属质量、气体体积或H⁺/OH⁻变化，再考虑溶液体积。","examples":["【示范：串联电解池电子守恒】第一池析出0.10 mol Cu，由Cu²⁺+2e⁻=Cu知通过0.20 mol e⁻；串联第二池同样通过0.20 mol e⁻，再按其电极式求气体、质量或pH变化。"],"visualSteps":["质量/气体/pH","由已知产物求e⁻","串联电量相同","按半反应换算","考虑总体积"]}]}],"workedExamples":[{"substance":"同一电池放电和充电","path":"放电是原电池：负极氧化、正极还原；充电是电解池：阳极接电源正极氧化、阴极接负极还原。同一物理电极的氧化/还原及阴、阳极角色会反向，正负端按当前连接判断。","labels":["先判放电/充电","看电源连接","定阴阳极","写氧化还原"]},{"substance":"碱性氢氧燃料电池电极式","path":"阳极H₂+2OH⁻-2e⁻=2H₂O；阴极O₂+2H₂O+4e⁻=4OH⁻。两式配成4e⁻后相加得到2H₂+O₂=2H₂O，并与介质中粒子变化核对。","labels":["找变价","写骨架","按碱性介质配平","相加得总式"]},{"substance":"三室电解槽的膜方向","path":"先写两极反应，标每室哪些阳/阴离子增加或减少；阳膜只让阳离子主要通过，阴膜只让阴离子主要通过；按电场与电中性共同确定迁移方向和物质的量。","labels":["两极反应","各室电荷账","膜选择性","电子数对应迁移量"]},{"substance":"燃料电池、精炼和腐蚀","path":"燃料电池中燃料在阳极氧化；电解精炼时粗金属作阳极、纯金属在阴极析出；牺牲阳极保护让更活泼金属先氧化。每套装置都回到“阳极氧化、阴极还原”。","labels":["判装置目的","阳极氧化","阴极还原","联系应用"]},{"substance":"串联电解池电子守恒","path":"第一池析出0.10 mol Cu，由Cu²⁺+2e⁻=Cu知通过0.20 mol e⁻；串联第二池同样通过0.20 mol e⁻，再按其电极式求气体、质量或pH变化。","labels":["由已知产物求e⁻","串联电量相同","按半反应换算","考虑总体积"]},{"substance":"碱性氢氧燃料电池","path":"阳极H₂+2OH⁻−2e⁻=2H₂O；阴极O₂+2H₂O+4e⁻=4OH⁻；配成4e⁻相加得2H₂+O₂=2H₂O。","labels":["燃料阳极氧化","氧阴极还原","碱性用OH⁻/H₂O"]},{"substance":"串联两电解池","path":"若第一池析出0.10 mol Cu，由Cu²⁺+2e⁻=Cu知通过0.20 mol e⁻；串联第二池也通过0.20 mol e⁻，再按其电极式求产物。","labels":["先由产物求e⁻","串联电子相同","再换第二池"]}],"checkpoints":["我能在充电、放电中分别标极。","我能从总反应写出适合介质的半反应。","我会逐室做电荷账判断膜迁移。","我能用电子守恒连接串联装置。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_ELECTRO' and skill_id = 'H3_ELECTRO';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H3_EXPERIMENT","version":2,"intro":"实验综合不是背装置，而是建立证据链：目的决定原理，原理决定装置和操作，操作产生现象，现象支持结论；最后检查干扰、安全和误差。","overview":["完整实验链：目的—原理—装置/试剂—操作—现象—结论—误差。","制备实验按发生、净化、干燥、收集、检验、尾气处理组织。","探究实验必须控制变量、设置对照、排除干扰，结论不得超过证据。","定量实验先写测量量与待求量关系，再判断误差如何传递。","安全优先：气密性、防倒吸、防爆沸、有毒气体处理和规范加热。"],"sections":[{"title":"先把常见仪器和操作补回","summary":"每个操作都对应一个目的。","items":[{"label":"测量仪器","rule":"量筒量取近似体积，滴定管精确放液，容量瓶配制固定体积，移液管移取准确体积。滴定管、移液管按要求用待装液润洗；容量瓶不能用待配溶液润洗。","examples":["【示范：配液—加热—过滤的仪器链】用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。"],"visualSteps":["测量仪器","选择测量仪器","规范加热","过滤洗涤","检查气密性"]},{"label":"加热与冷却","rule":"试管、烧杯、坩埚等加热方式不同；加热前检查装置，停止加热后防倒吸，热玻璃不能骤冷。","examples":["【示范：配液—加热—过滤的仪器链】用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。"],"visualSteps":["加热与冷却","选择测量仪器","规范加热","过滤洗涤","检查气密性"]},{"label":"过滤、洗涤、结晶","rule":"过滤分固液；洗涤除表面可溶杂质；蒸发浓缩—冷却结晶适合溶解度随温度变化明显的物质。","examples":["【示范：配液—加热—过滤的仪器链】用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。"],"visualSteps":["过滤、洗涤、结晶","选择测量仪器","规范加热","过滤洗涤","检查气密性"]},{"label":"气密性","rule":"形成密闭体系，通过压强变化产生气泡、液面差等现象判断；装药前完成。","examples":["【示范：配液—加热—过滤的仪器链】用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。"],"visualSteps":["气密性","选择测量仪器","规范加热","过滤洗涤","检查气密性"]}]},{"title":"气体制备装置链","summary":"从反应物状态和条件选发生装置。","items":[{"label":"发生","rule":"固—固加热、固—液不加热或液—液加热决定装置；需要控制速率时用滴液漏斗等。","examples":["【示范：制备干燥NH₃的装置链】发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。"],"visualSteps":["发生","发生","净化干燥","收集","尾气与安全"]},{"label":"净化与干燥","rule":"先除杂再干燥；洗气试剂不能消耗主体或引入新杂质，气体通常长管进。","examples":["【示范：制备干燥NH₃的装置链】发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。"],"visualSteps":["净化与干燥","发生","净化干燥","收集","尾气与安全"]},{"label":"收集","rule":"由气体密度、溶解性、是否与水/空气反应选择排水、向上或向下排空气。","examples":["【示范：制备干燥NH₃的装置链】发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。"],"visualSteps":["收集","发生","净化干燥","收集","尾气与安全"]},{"label":"尾气与防倒吸","rule":"有毒、刺激性气体要吸收；易溶气体吸收时设置安全瓶、倒扣漏斗等防倒吸。","examples":["【示范：制备干燥NH₃的装置链】发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。"],"visualSteps":["尾气与防倒吸","发生","净化干燥","收集","尾气与安全"]}]},{"title":"检验与性质探究","summary":"现象必须具有唯一或经排干扰后的指向。","items":[{"label":"检验三件套","rule":"写“取样—加试剂/操作—观察现象—得出检出结论”，不能只报试剂名。","examples":["【示范：检验SO₄²⁻的完整证据】取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。"],"visualSteps":["检验三件套","取样","排除干扰","现象","对照与结论边界"]},{"label":"排除干扰","rule":"先除去或掩蔽会产生相同现象的粒子；试剂加入顺序可能决定结论是否可靠。","examples":["【示范：检验SO₄²⁻的完整证据】取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。"],"visualSteps":["排除干扰","取样","排除干扰","现象","对照与结论边界"]},{"label":"控制变量","rule":"只改变研究因素，其余物质用量、浓度、温度、接触面积等保持一致。","examples":["【示范：检验SO₄²⁻的完整证据】取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。"],"visualSteps":["控制变量","取样","排除干扰","现象","对照与结论边界"]},{"label":"对照与空白","rule":"阳性对照证明体系能出现预期现象，空白对照排除试剂或装置本身造成的现象。","examples":["【示范：检验SO₄²⁻的完整证据】取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。"],"visualSteps":["对照与空白","取样","排除干扰","现象","对照与结论边界"]}]},{"title":"定量实验和数据处理","summary":"先建计算模型，再操作。","items":[{"label":"滴定","rule":"标准液浓度和体积通过方程式计量关系求待测量；平行测定剔除明显异常，取相近值平均。","examples":["【示范：滴定数据和误差方向】平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。"],"visualSteps":["滴定","记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]},{"label":"称量法/气体法","rule":"由沉淀质量、质量差或气体体积反推组分；要保证转化完全、产物组成明确。","examples":["【示范：滴定数据和误差方向】平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。"],"visualSteps":["称量法/气体法","记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]},{"label":"有效数字与记录","rule":"记录精度由仪器决定；中间保留足够位数，最终按要求表达。","examples":["【示范：滴定数据和误差方向】平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。"],"visualSteps":["有效数字与记录","记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]},{"label":"误差方向","rule":"沿“操作错误→直接测量量偏大/偏小→公式中分子分母→结果方向”推，不背孤立结论。","examples":["【示范：滴定数据和误差方向】平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。"],"visualSteps":["误差方向","记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]}]},{"title":"方案评价和开放设计","summary":"评价要指出问题、后果和改进。","items":[{"label":"可行性","rule":"反应能否发生、现象是否明显、仪器条件是否满足。","examples":["【示范：评价一个气体制备方案】依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。"],"visualSteps":["可行性","可行性","科学性","安全环保","简约准确"]},{"label":"科学性","rule":"变量是否唯一、证据是否充分、结论是否超范围、是否有重复验证。","examples":["【示范：评价一个气体制备方案】依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。"],"visualSteps":["科学性","可行性","科学性","安全环保","简约准确"]},{"label":"安全与环保","rule":"有毒、腐蚀、易燃、爆炸风险是否控制，废液和尾气是否处理。","examples":["【示范：评价一个气体制备方案】依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。"],"visualSteps":["安全与环保","可行性","科学性","安全环保","简约准确"]},{"label":"简约与准确","rule":"在保证可靠前提下步骤更少、误差更小、资源更省；不能为简化牺牲证据。","examples":["【示范：评价一个气体制备方案】依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。"],"visualSteps":["简约与准确","可行性","科学性","安全环保","简约准确"]}]}],"workedExamples":[{"substance":"配液—加热—过滤的仪器链","path":"用容量瓶配固定体积时先在烧杯溶解并冷却再转移；加热固体前检查装置；反应后过滤并洗涤沉淀。气体实验在装药前先通过压强变化检查气密性。","labels":["选择测量仪器","规范加热","过滤洗涤","检查气密性"]},{"substance":"制备干燥NH₃的装置链","path":"发生端由固体混合加热，净化试剂不能消耗NH₃，干燥剂要适配；因NH₃极易溶于水且密度小，选向下排空气收集，尾气吸收装置要防倒吸。","labels":["发生","净化干燥","收集","尾气与安全"]},{"substance":"检验SO₄²⁻的完整证据","path":"取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂，出现白色沉淀可支持检出SO₄²⁻；另设空白或已知样对照可检查试剂体系。","labels":["取样","排除干扰","现象","对照与结论边界"]},{"substance":"滴定数据和误差方向","path":"平行滴定取相近数据平均、剔除明显异常；若开始滴定管尖嘴有气泡、结束消失，读出体积偏大。沿“V偏大→公式分子偏大→待测浓度偏高”判断。","labels":["记录有效数字","筛平行数据","判直接测量偏差","沿公式传递"]},{"substance":"评价一个气体制备方案","path":"依次问：反应能否发生且现象可测；是否只改变目标变量、有对照；有毒尾气和倒吸是否处理；步骤是否在可靠前提下更少、误差更小。","labels":["可行性","科学性","安全环保","简约准确"]},{"substance":"检验SO₄²⁻","path":"取少量待测液，先加稀盐酸排除CO₃²⁻、SO₃²⁻等干扰，再加BaCl₂溶液；若出现白色沉淀，可支持检出SO₄²⁻。若原样含Ag⁺等，还需考虑新增干扰。","labels":["取样","排干扰","加试剂","现象与边界"]},{"substance":"滴定读数偏差","path":"若滴定管尖嘴开始有气泡、结束时气泡消失，读出的标准液体积包含填充尖嘴的体积，读数偏大；由计算式判断待测浓度通常偏高。","labels":["先判V偏大","再看公式","结论方向"]}],"checkpoints":["我能把实验答案写成完整证据链。","我会按发生—净化—收集—尾气处理检查装置。","我能设计单变量和对照实验。","我会从直接测量量推导误差方向。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_EXPERIMENT' and skill_id = 'H3_EXPERIMENT';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H3_PROCESS","version":2,"intro":"工艺流程图是一条“目标元素旅行路线”。先标目标元素进入哪一相、杂质去了哪里，再解释每一步为什么选择该试剂、pH、温度和分离方法。","overview":["读图先圈原料、目标产物、循环物、滤渣、滤液和每次加入/移出的物质。","每一步回答三问：目标物去哪？杂质去哪？为什么用这个条件？","浸取、氧化还原、调pH、过滤洗涤、蒸发结晶都由已学平衡与性质解释。","方程式和计算常用元素守恒、电子守恒、Ksp和物料衡算。","评价兼顾产率、纯度、能耗、成本、安全、废物和循环利用。"],"sections":[{"title":"流程图怎么读","summary":"先读物流，再读反应。","items":[{"label":"标目标元素","rule":"从原料到产品逐框圈出目标元素的存在形态，防止在滤渣或母液中“丢失”。","examples":["【示范：从含锂矿到锂盐的流程图】沿每个框标出Li所在固体或溶液，记录加入酸碱/氧化剂和温度；过滤后明确Li在滤液还是滤渣，母液回用箭头说明可循环的物质。"],"visualSteps":["标目标元素","圈目标元素","标相态操作","读加入物和条件","找循环支路"]},{"label":"标相态与操作","rule":"溶液、固体、气体决定过滤、结晶、洗涤或吸收；箭头上的加入物和条件是解题信息。","examples":["【示范：从含锂矿到锂盐的流程图】沿每个框标出Li所在固体或溶液，记录加入酸碱/氧化剂和温度；过滤后明确Li在滤液还是滤渣，母液回用箭头说明可循环的物质。"],"visualSteps":["标相态与操作","圈目标元素","标相态操作","读加入物和条件","找循环支路"]},{"label":"找循环支路","rule":"循环物通常为未反应原料、母液或可再生试剂；说明提高利用率、减少排放等作用。","examples":["【示范：从含锂矿到锂盐的流程图】沿每个框标出Li所在固体或溶液，记录加入酸碱/氧化剂和温度；过滤后明确Li在滤液还是滤渣，母液回用箭头说明可循环的物质。"],"visualSteps":["找循环支路","圈目标元素","标相态操作","读加入物和条件","找循环支路"]}]},{"title":"原料预处理与浸取","summary":"目标是让目标组分可分离地进入溶液。","items":[{"label":"粉碎/研磨","rule":"增大接触面积，加快浸取速率；不直接改变平衡常数。","examples":["【示范：粉碎—焙烧—酸浸】粉碎增大接触面积加快速率；焙烧把难浸价态/物相转为易处理形态并除挥发组分；酸浸条件在浸取率、能耗、副反应和腐蚀之间折中。"],"visualSteps":["粉碎/研磨","预处理目的","判断焙烧气氛","选择浸取剂","优化温度时间"]},{"label":"焙烧/煅烧","rule":"分解原料、氧化/还原到易浸取价态或除去挥发组分；结合气氛和温度判断。","examples":["【示范：粉碎—焙烧—酸浸】粉碎增大接触面积加快速率；焙烧把难浸价态/物相转为易处理形态并除挥发组分；酸浸条件在浸取率、能耗、副反应和腐蚀之间折中。"],"visualSteps":["焙烧/煅烧","预处理目的","判断焙烧气氛","选择浸取剂","优化温度时间"]},{"label":"酸浸/碱浸/水浸","rule":"依据目标物和杂质的酸碱性、两性、氧化还原性和溶解性选择。","examples":["【示范：粉碎—焙烧—酸浸】粉碎增大接触面积加快速率；焙烧把难浸价态/物相转为易处理形态并除挥发组分；酸浸条件在浸取率、能耗、副反应和腐蚀之间折中。"],"visualSteps":["酸浸/碱浸/水浸","预处理目的","判断焙烧气氛","选择浸取剂","优化温度时间"]},{"label":"浸取率条件","rule":"温度、浓度、时间、液固比提高可能促进浸取，但还要考虑能耗、副反应和设备腐蚀。","examples":["【示范：粉碎—焙烧—酸浸】粉碎增大接触面积加快速率；焙烧把难浸价态/物相转为易处理形态并除挥发组分；酸浸条件在浸取率、能耗、副反应和腐蚀之间折中。"],"visualSteps":["浸取率条件","预处理目的","判断焙烧气氛","选择浸取剂","优化温度时间"]}]},{"title":"转化与除杂","summary":"用价态、沉淀和络合等性质拉开差异。","items":[{"label":"氧化还原调价","rule":"把目标或杂质调到更易沉淀、萃取或稳定存在的价态；用电子守恒配方程式和用量。","examples":["【示范：调pH除Fe³⁺保留Mg²⁺】先把Fe调到易沉淀价态，按Ksp或题给pH范围加碱，使Fe(OH)₃充分沉淀而Mg²⁺留液；除杂剂不能大量带走目标物，新引入离子要能后续去除。"],"visualSteps":["氧化还原调价","调价","Qsp/Ksp","选择pH","检查新杂质"]},{"label":"调pH沉淀","rule":"利用不同氢氧化物/盐的沉淀范围，使杂质沉淀而目标离子保留，或反向沉淀目标。","examples":["【示范：调pH除Fe³⁺保留Mg²⁺】先把Fe调到易沉淀价态，按Ksp或题给pH范围加碱，使Fe(OH)₃充分沉淀而Mg²⁺留液；除杂剂不能大量带走目标物，新引入离子要能后续去除。"],"visualSteps":["调pH沉淀","调价","Qsp/Ksp","选择pH","检查新杂质"]},{"label":"除杂试剂","rule":"试剂应选择性强、不过度消耗目标物，过量试剂及新引入离子应能在后续去除。","examples":["【示范：调pH除Fe³⁺保留Mg²⁺】先把Fe调到易沉淀价态，按Ksp或题给pH范围加碱，使Fe(OH)₃充分沉淀而Mg²⁺留液；除杂剂不能大量带走目标物，新引入离子要能后续去除。"],"visualSteps":["除杂试剂","调价","Qsp/Ksp","选择pH","检查新杂质"]},{"label":"Ksp判断","rule":"用Qsp与Ksp或题给沉淀pH范围定量选择条件，“完全”按残余浓度标准。","examples":["【示范：调pH除Fe³⁺保留Mg²⁺】先把Fe调到易沉淀价态，按Ksp或题给pH范围加碱，使Fe(OH)₃充分沉淀而Mg²⁺留液；除杂剂不能大量带走目标物，新引入离子要能后续去除。"],"visualSteps":["Ksp判断","调价","Qsp/Ksp","选择pH","检查新杂质"]}]},{"title":"分离、洗涤与结晶","summary":"操作名称后必须写目的。","items":[{"label":"过滤","rule":"分离不溶性固体与液体；明确目标在滤渣还是滤液。","examples":["【示范：从滤液得到纯晶体】蒸发浓缩到合适程度后冷却结晶，过滤得到晶体；用少量冷的合适洗液除母液杂质，必要时检验最后一次洗液；重结晶利用冷热溶解度差进一步提纯。"],"visualSteps":["过滤","浓缩结晶","过滤","少量冷洗","重结晶提纯"]},{"label":"洗涤","rule":"除去沉淀/晶体表面可溶杂质；用少量合适洗液，必要时检验最后一次洗液。","examples":["【示范：从滤液得到纯晶体】蒸发浓缩到合适程度后冷却结晶，过滤得到晶体；用少量冷的合适洗液除母液杂质，必要时检验最后一次洗液；重结晶利用冷热溶解度差进一步提纯。"],"visualSteps":["洗涤","浓缩结晶","过滤","少量冷洗","重结晶提纯"]},{"label":"蒸发浓缩—冷却结晶","rule":"适用于溶解度随温度降低明显减小且受热较稳定的产品；通常不直接蒸干。","examples":["【示范：从滤液得到纯晶体】蒸发浓缩到合适程度后冷却结晶，过滤得到晶体；用少量冷的合适洗液除母液杂质，必要时检验最后一次洗液；重结晶利用冷热溶解度差进一步提纯。"],"visualSteps":["蒸发浓缩—冷却结晶","浓缩结晶","过滤","少量冷洗","重结晶提纯"]},{"label":"重结晶/趁热过滤","rule":"利用溶解度随温度差异提纯；趁热过滤防止目标物提前析出。","examples":["【示范：从滤液得到纯晶体】蒸发浓缩到合适程度后冷却结晶，过滤得到晶体；用少量冷的合适洗液除母液杂质，必要时检验最后一次洗液；重结晶利用冷热溶解度差进一步提纯。"],"visualSteps":["重结晶/趁热过滤","浓缩结晶","过滤","少量冷洗","重结晶提纯"]}]},{"title":"计算与评价","summary":"把化学量、工程量和环境量分开。","items":[{"label":"产率与纯度","rule":"理论产量由限制量/目标元素守恒求得；实际产率考虑各步骤损失。","examples":["【示范：流程产率和绿色评价】由原料中目标元素守恒求理论产量，再用实际产量算产率；评价母液/试剂是否循环、副产物能否利用、三废是否减少，同时说明高温或过量试剂对成本、安全和选择性的影响。"],"visualSteps":["产率与纯度","理论产量","实际产率","循环副产物","成本安全表达"]},{"label":"循环和副产物","rule":"评价能否回收试剂、利用副产物、减少“三废”，但不能让杂质无限累积。","examples":["【示范：流程产率和绿色评价】由原料中目标元素守恒求理论产量，再用实际产量算产率；评价母液/试剂是否循环、副产物能否利用、三废是否减少，同时说明高温或过量试剂对成本、安全和选择性的影响。"],"visualSteps":["循环和副产物","理论产量","实际产率","循环副产物","成本安全表达"]},{"label":"条件优化","rule":"不是越高温、越多试剂越好；综合速率、平衡、选择性、成本与安全。","examples":["【示范：流程产率和绿色评价】由原料中目标元素守恒求理论产量，再用实际产量算产率；评价母液/试剂是否循环、副产物能否利用、三废是否减少，同时说明高温或过量试剂对成本、安全和选择性的影响。"],"visualSteps":["条件优化","理论产量","实际产率","循环副产物","成本安全表达"]},{"label":"规范表述","rule":"“调pH使X转化为沉淀除去，同时避免Y沉淀”比只写“除杂”更完整。","examples":["【示范：流程产率和绿色评价】由原料中目标元素守恒求理论产量，再用实际产量算产率；评价母液/试剂是否循环、副产物能否利用、三废是否减少，同时说明高温或过量试剂对成本、安全和选择性的影响。"],"visualSteps":["规范表述","理论产量","实际产率","循环副产物","成本安全表达"]}]}],"workedExamples":[{"substance":"从含锂矿到锂盐的流程图","path":"沿每个框标出Li所在固体或溶液，记录加入酸碱/氧化剂和温度；过滤后明确Li在滤液还是滤渣，母液回用箭头说明可循环的物质。","labels":["圈目标元素","标相态操作","读加入物和条件","找循环支路"]},{"substance":"粉碎—焙烧—酸浸","path":"粉碎增大接触面积加快速率；焙烧把难浸价态/物相转为易处理形态并除挥发组分；酸浸条件在浸取率、能耗、副反应和腐蚀之间折中。","labels":["预处理目的","判断焙烧气氛","选择浸取剂","优化温度时间"]},{"substance":"调pH除Fe³⁺保留Mg²⁺","path":"先把Fe调到易沉淀价态，按Ksp或题给pH范围加碱，使Fe(OH)₃充分沉淀而Mg²⁺留液；除杂剂不能大量带走目标物，新引入离子要能后续去除。","labels":["调价","Qsp/Ksp","选择pH","检查新杂质"]},{"substance":"从滤液得到纯晶体","path":"蒸发浓缩到合适程度后冷却结晶，过滤得到晶体；用少量冷的合适洗液除母液杂质，必要时检验最后一次洗液；重结晶利用冷热溶解度差进一步提纯。","labels":["浓缩结晶","过滤","少量冷洗","重结晶提纯"]},{"substance":"流程产率和绿色评价","path":"由原料中目标元素守恒求理论产量，再用实际产量算产率；评价母液/试剂是否循环、副产物能否利用、三废是否减少，同时说明高温或过量试剂对成本、安全和选择性的影响。","labels":["理论产量","实际产率","循环副产物","成本安全表达"]},{"substance":"晶体洗涤","path":"过滤得到晶体后，用少量冷的合适洗液淋洗，除去表面母液中的可溶杂质；冷洗减少产品溶解损失，再低温干燥。","labels":["除表面杂质","少量冷洗","兼顾产率"]}],"checkpoints":["我能沿流程追踪目标元素。","我会为每个操作写目的而不只写名称。","我能用Ksp或题给范围解释调pH。","我能从产率、纯度、成本和环保多维评价。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_PROCESS' and skill_id = 'H3_PROCESS';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H3_STRUCTURE","version":2,"intro":"物质结构与性质按尺度逐层解释：电子排布决定成键倾向，价层电子对决定空间构型，粒子间作用决定晶体结构，晶体结构再决定熔沸点、硬度和导电性。","overview":["原子层：电子排布、价电子、周期位置、电离能/电负性等趋势。","分子层：Lewis结构、VSEPR、杂化、σ/π键、极性和分子间作用力。","晶体层：分子、离子、共价、金属晶体的构成粒子与作用力。","晶胞计算按“均摊计数—配位—几何关系—密度”完成。","只使用福建高中范围内模型，不展开大学层次的高级成键与晶体理论。"],"sections":[{"title":"原子结构和电子排布","summary":"先找到价电子，才能解释化学性质。","items":[{"label":"能层、能级与轨道","rule":"电子按能量由低到高排布，遵守泡利原理、洪特规则和能量最低原理；每个轨道最多2个自旋相反电子。","examples":["【示范：Fe与Fe²⁺的电子排布】先按能量最低、泡利和洪特规则写Fe基态排布；形成Fe²⁺时先失较外层4s电子，再核对未成对电子数。周期趋势比较时说明电子层、有效核电荷和亚层稳定性的局部例外。"],"visualSteps":["能层、能级与轨道","能层能级轨道","价电子","原子到离子","周期趋势"]},{"label":"价电子排布","rule":"主族元素价电子决定主要成键和周期性质；过渡元素还要考虑(n−1)d与ns电子。","examples":["【示范：Fe与Fe²⁺的电子排布】先按能量最低、泡利和洪特规则写Fe基态排布；形成Fe²⁺时先失较外层4s电子，再核对未成对电子数。周期趋势比较时说明电子层、有效核电荷和亚层稳定性的局部例外。"],"visualSteps":["价电子排布","能层能级轨道","价电子","原子到离子","周期趋势"]},{"label":"电子排布表示","rule":"可用电子排布式、简化排布式、轨道表示式；失电子时按外层和题给规律处理。","examples":["【示范：Fe与Fe²⁺的电子排布】先按能量最低、泡利和洪特规则写Fe基态排布；形成Fe²⁺时先失较外层4s电子，再核对未成对电子数。周期趋势比较时说明电子层、有效核电荷和亚层稳定性的局部例外。"],"visualSteps":["电子排布表示","能层能级轨道","价电子","原子到离子","周期趋势"]},{"label":"周期趋势","rule":"原子半径、电离能、电负性总体有周期性，但第一电离能等存在由电子亚层稳定性导致的局部例外。","examples":["【示范：Fe与Fe²⁺的电子排布】先按能量最低、泡利和洪特规则写Fe基态排布；形成Fe²⁺时先失较外层4s电子，再核对未成对电子数。周期趋势比较时说明电子层、有效核电荷和亚层稳定性的局部例外。"],"visualSteps":["周期趋势","能层能级轨道","价电子","原子到离子","周期趋势"]}]},{"title":"化学键与Lewis结构","summary":"先数价电子，再画连接和孤电子对。","items":[{"label":"离子键/共价键/金属键","rule":"分别来自阴阳离子静电作用、原子间共享电子对、金属阳离子与自由电子的作用模型。","examples":["【示范：由CO₂画Lewis结构】统计总价电子，O—C—O先以单键连接，补外围八电子后中心C仍缺电子，形成两个C=O双键；再用形式电荷和总电子数核对。"],"visualSteps":["离子键/共价键/金属键","统计价电子","搭骨架","补八电子/多键","核对形式"]},{"label":"Lewis结构","rule":"统计价电子总数，选中心原子，先单键连接，补外围八电子，再把剩余电子给中心，必要时形成多键。","examples":["【示范：由CO₂画Lewis结构】统计总价电子，O—C—O先以单键连接，补外围八电子后中心C仍缺电子，形成两个C=O双键；再用形式电荷和总电子数核对。"],"visualSteps":["Lewis结构","统计价电子","搭骨架","补八电子/多键","核对形式"]},{"label":"形式与实际","rule":"Lewis式是电子计数模型，真实键可有离域；按课标和题给信息使用，不作大学理论展开。","examples":["【示范：由CO₂画Lewis结构】统计总价电子，O—C—O先以单键连接，补外围八电子后中心C仍缺电子，形成两个C=O双键；再用形式电荷和总电子数核对。"],"visualSteps":["形式与实际","统计价电子","搭骨架","补八电子/多键","核对形式"]}]},{"title":"VSEPR、杂化与分子性质","summary":"电子域相互排斥，决定大致空间排列。","items":[{"label":"价层电子对数","rule":"中心原子的成键电子域和孤电子对共同决定电子对构型；多键通常算一个电子域。","examples":["【示范：NH₃的空间结构与极性】N周围3个成键电子域和1个孤电子对，共4域，电子对构型四面体、sp³杂化；去掉孤对看分子为三角锥，键偶极不完全抵消，分子有极性。"],"visualSteps":["价层电子对数","数电子域","定VSEPR/杂化","去孤对定构型","矢量判极性"]},{"label":"常见对应","rule":"2域直线/sp，3域平面三角/sp²，4域四面体/sp³；分子构型还要去掉孤电子对位置。","examples":["【示范：NH₃的空间结构与极性】N周围3个成键电子域和1个孤电子对，共4域，电子对构型四面体、sp³杂化；去掉孤对看分子为三角锥，键偶极不完全抵消，分子有极性。"],"visualSteps":["常见对应","数电子域","定VSEPR/杂化","去孤对定构型","矢量判极性"]},{"label":"σ键与π键","rule":"单键通常1个σ键；双键1σ+1π；三键1σ+2π。","examples":["【示范：NH₃的空间结构与极性】N周围3个成键电子域和1个孤电子对，共4域，电子对构型四面体、sp³杂化；去掉孤对看分子为三角锥，键偶极不完全抵消，分子有极性。"],"visualSteps":["σ键与π键","数电子域","定VSEPR/杂化","去孤对定构型","矢量判极性"]},{"label":"分子极性","rule":"先看键的极性，再做空间矢量合成；对称分子可能含极性键但整体非极性。","examples":["【示范：NH₃的空间结构与极性】N周围3个成键电子域和1个孤电子对，共4域，电子对构型四面体、sp³杂化；去掉孤对看分子为三角锥，键偶极不完全抵消，分子有极性。"],"visualSteps":["分子极性","数电子域","定VSEPR/杂化","去孤对定构型","矢量判极性"]},{"label":"分子间作用力","rule":"范德华力、氢键等影响熔沸点、溶解性；它们不同于分子内化学键。","examples":["【示范：NH₃的空间结构与极性】N周围3个成键电子域和1个孤电子对，共4域，电子对构型四面体、sp³杂化；去掉孤对看分子为三角锥，键偶极不完全抵消，分子有极性。"],"visualSteps":["分子间作用力","数电子域","定VSEPR/杂化","去孤对定构型","矢量判极性"]}]},{"title":"配合物与晶体类型","summary":"先认构成粒子，再认作用力。","items":[{"label":"配位概念","rule":"中心离子/原子接受配体孤电子对形成配位键；识别配体、配位原子和配位数。","caution":"只按教材要求识别，不展开大学层次的配合物理论。","examples":["【示范：NaCl、金刚石、干冰和Cu】NaCl由离子构成，金刚石由原子共价网络构成，干冰由CO₂分子构成，Cu用金属键模型；从构成粒子和作用力解释熔点、硬度及导电性。配合物则另识别中心、配体和配位数。"],"visualSteps":["配位概念","识别构成粒子","判断作用力","晶体类型","结构解释性质"]},{"label":"分子晶体","rule":"构成粒子是分子，粒子间作用较弱，熔沸点通常较低；部分能形成氢键。","examples":["【示范：NaCl、金刚石、干冰和Cu】NaCl由离子构成，金刚石由原子共价网络构成，干冰由CO₂分子构成，Cu用金属键模型；从构成粒子和作用力解释熔点、硬度及导电性。配合物则另识别中心、配体和配位数。"],"visualSteps":["分子晶体","识别构成粒子","判断作用力","晶体类型","结构解释性质"]},{"label":"离子晶体","rule":"阴阳离子以静电作用构成，熔点较高，熔融或溶于水后常能导电。","examples":["【示范：NaCl、金刚石、干冰和Cu】NaCl由离子构成，金刚石由原子共价网络构成，干冰由CO₂分子构成，Cu用金属键模型；从构成粒子和作用力解释熔点、硬度及导电性。配合物则另识别中心、配体和配位数。"],"visualSteps":["离子晶体","识别构成粒子","判断作用力","晶体类型","结构解释性质"]},{"label":"共价晶体","rule":"原子以共价键形成空间网络，常硬、熔点高，导电性视结构而异。","examples":["【示范：NaCl、金刚石、干冰和Cu】NaCl由离子构成，金刚石由原子共价网络构成，干冰由CO₂分子构成，Cu用金属键模型；从构成粒子和作用力解释熔点、硬度及导电性。配合物则另识别中心、配体和配位数。"],"visualSteps":["共价晶体","识别构成粒子","判断作用力","晶体类型","结构解释性质"]},{"label":"金属晶体","rule":"用金属键模型解释金属晶体能够导电、导热并具有延展性。","examples":["【示范：NaCl、金刚石、干冰和Cu】NaCl由离子构成，金刚石由原子共价网络构成，干冰由CO₂分子构成，Cu用金属键模型；从构成粒子和作用力解释熔点、硬度及导电性。配合物则另识别中心、配体和配位数。"],"visualSteps":["金属晶体","识别构成粒子","判断作用力","晶体类型","结构解释性质"]}]},{"title":"晶胞与结构—性质解释","summary":"把图形问题拆成计数和几何。","items":[{"label":"均摊计数","rule":"顶点1/8、棱上1/4、面心1/2、体心1；边界外共享情况结合晶胞定义。","examples":["【示范：NaCl晶胞密度】按顶点1/8、面心1/2等均摊得到一个晶胞中的化学式单位数Z；数最近邻得配位数；用ρ=(ZM/Nₐ)/Vcell，先把边长换成cm。"],"visualSteps":["均摊计数","均摊计数","最近邻配位","晶胞质量","体积与单位"]},{"label":"配位数","rule":"以目标粒子为中心，数最近邻粒子；注意晶胞外同样存在邻居。","examples":["【示范：NaCl晶胞密度】按顶点1/8、面心1/2等均摊得到一个晶胞中的化学式单位数Z；数最近邻得配位数；用ρ=(ZM/Nₐ)/Vcell，先把边长换成cm。"],"visualSteps":["配位数","均摊计数","最近邻配位","晶胞质量","体积与单位"]},{"label":"密度公式","rule":"ρ=晶胞质量/晶胞体积=(Z·M/Nₐ)/Vcell；单位要统一。","examples":["【示范：NaCl晶胞密度】按顶点1/8、面心1/2等均摊得到一个晶胞中的化学式单位数Z；数最近邻得配位数；用ρ=(ZM/Nₐ)/Vcell，先把边长换成cm。"],"visualSteps":["密度公式","均摊计数","最近邻配位","晶胞质量","体积与单位"]},{"label":"性质解释链","rule":"明确“构成粒子—粒子间作用—需要克服的作用—宏观性质”，避免只说“结构稳定”。","examples":["【示范：NaCl晶胞密度】按顶点1/8、面心1/2等均摊得到一个晶胞中的化学式单位数Z；数最近邻得配位数；用ρ=(ZM/Nₐ)/Vcell，先把边长换成cm。"],"visualSteps":["性质解释链","均摊计数","最近邻配位","晶胞质量","体积与单位"]}]}],"workedExamples":[{"substance":"Fe与Fe²⁺的电子排布","path":"先按能量最低、泡利和洪特规则写Fe基态排布；形成Fe²⁺时先失较外层4s电子，再核对未成对电子数。周期趋势比较时说明电子层、有效核电荷和亚层稳定性的局部例外。","labels":["能层能级轨道","价电子","原子到离子","周期趋势"]},{"substance":"由CO₂画Lewis结构","path":"统计总价电子，O—C—O先以单键连接，补外围八电子后中心C仍缺电子，形成两个C=O双键；再用形式电荷和总电子数核对。","labels":["统计价电子","搭骨架","补八电子/多键","核对形式"]},{"substance":"NH₃的空间结构与极性","path":"N周围3个成键电子域和1个孤电子对，共4域，电子对构型四面体、sp³杂化；去掉孤对看分子为三角锥，键偶极不完全抵消，分子有极性。","labels":["数电子域","定VSEPR/杂化","去孤对定构型","矢量判极性"]},{"substance":"NaCl、金刚石、干冰和Cu","path":"NaCl由离子构成，金刚石由原子共价网络构成，干冰由CO₂分子构成，Cu用金属键模型；从构成粒子和作用力解释熔点、硬度及导电性。配合物则另识别中心、配体和配位数。","labels":["识别构成粒子","判断作用力","晶体类型","结构解释性质"]},{"substance":"NaCl晶胞密度","path":"按顶点1/8、面心1/2等均摊得到一个晶胞中的化学式单位数Z；数最近邻得配位数；用ρ=(ZM/Nₐ)/Vcell，先把边长换成cm。","labels":["均摊计数","最近邻配位","晶胞质量","体积与单位"]},{"substance":"NH₃构型","path":"N有5个价电子，与3个H形成3个成键电子对，另有1个孤电子对，共4个电子域，N为sp³杂化；电子对构型四面体，分子构型三角锥，分子有极性。","labels":["数价电子","4电子域","去孤对看构型","判极性"]},{"substance":"晶胞密度","path":"先用均摊法得一个晶胞含Z个化学式单位，晶胞质量=ZM/Nₐ；由晶胞参数求体积并统一到cm³，代ρ=m/V。","labels":["均摊Z","摩尔质量","单位换算","密度"]}],"checkpoints":["我能从价电子画基础Lewis结构。","我能区分电子对构型和分子构型。","我能按构成粒子判断晶体类型。","我能用均摊法和密度公式处理晶胞。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_STRUCTURE' and skill_id = 'H3_STRUCTURE';

update public.chem_knowledge_cards
set structured_content = $card${"skillId":"H3_ORGANIC","version":2,"intro":"有机化学从碳骨架和官能团重新开始：碳骨架决定同分异构，官能团决定主要性质，反应条件决定发生哪种转化。合成路线就是把这些转化按目标倒推和正推。","overview":["看结构先圈碳骨架、官能团、官能团数目与位置，再判断类别和性质。","常见反应类型：取代、加成、消去、氧化、还原、酯化、水解、加聚、缩聚。","同分异构体：分子式相同、结构不同；按碳链—位置—官能团顺序系统枚举。","合成推断同时追踪碳原子数、官能团变化、反应条件和题给新信息。","只使用福建高中教材要求的官能团、反应类型、转化路线和信息题方法，不展开大学层次的反应机理、立体化学命名和专门合成反应。"],"sections":[{"title":"有机物表示、分类和命名基础","summary":"先读懂结构，再谈反应。","items":[{"label":"碳骨架","rule":"判断链状/环状、脂肪/芳香、饱和/不饱和，数清主链和支链。","examples":["【示范：读CH₃CH(OH)CH₂CHO】先找最长含主要官能团碳链，圈羟基和醛基，编号使醛基位次最低；由结构式核分子式和不饱和度，再按命名规则组织名称。"],"visualSteps":["碳骨架","识别碳骨架","圈官能团","编号命名","分子式复核"]},{"label":"官能团","rule":"碳碳双/三键、卤素原子、羟基、醚键、醛基、羰基、羧基、酯基、酰胺基等决定特征性质。","examples":["【示范：读CH₃CH(OH)CH₂CHO】先找最长含主要官能团碳链，圈羟基和醛基，编号使醛基位次最低；由结构式核分子式和不饱和度，再按命名规则组织名称。"],"visualSteps":["官能团","识别碳骨架","圈官能团","编号命名","分子式复核"]},{"label":"命名思路","rule":"选含主要官能团的最长主链，编号使主要官能团和取代基位次合理，按规则写名称。","examples":["【示范：读CH₃CH(OH)CH₂CHO】先找最长含主要官能团碳链，圈羟基和醛基，编号使醛基位次最低；由结构式核分子式和不饱和度，再按命名规则组织名称。"],"visualSteps":["命名思路","识别碳骨架","圈官能团","编号命名","分子式复核"]},{"label":"分子式与不饱和度","rule":"由元素组成和结构特征核对环/双键信息；具体计算按课内不饱和度方法或题给信息。","examples":["【示范：读CH₃CH(OH)CH₂CHO】先找最长含主要官能团碳链，圈羟基和醛基，编号使醛基位次最低；由结构式核分子式和不饱和度，再按命名规则组织名称。"],"visualSteps":["分子式与不饱和度","识别碳骨架","圈官能团","编号命名","分子式复核"]}]},{"title":"常见官能团性质网络","summary":"把试剂、条件、断键成键和现象配成套。","items":[{"label":"烯烃/炔烃","rule":"可加成、加聚、被氧化；溴水褪色要结合反应对象排除其他还原性基团。","examples":["【示范：乙烯—乙醇—乙醛—乙酸—酯】乙烯加成得乙醇；乙醇氧化得乙醛，再氧化得乙酸；乙酸与乙醇酯化得乙酸乙酯。每一步把试剂条件和官能团变化配成对。"],"visualSteps":["烯烃/炔烃","烯烃加成","醇/醛氧化","羧酸酯化","条件与现象"]},{"label":"卤代烃","rule":"水解生成醇，消去生成不饱和键；条件不同产物不同。","examples":["【示范：乙烯—乙醇—乙醛—乙酸—酯】乙烯加成得乙醇；乙醇氧化得乙醛，再氧化得乙酸；乙酸与乙醇酯化得乙酸乙酯。每一步把试剂条件和官能团变化配成对。"],"visualSteps":["卤代烃","烯烃加成","醇/醛氧化","羧酸酯化","条件与现象"]},{"label":"醇与酚","rule":"醇可取代、氧化、消去、酯化；酚羟基受苯环影响呈弱酸性并有特征取代/显色反应。","examples":["【示范：乙烯—乙醇—乙醛—乙酸—酯】乙烯加成得乙醇；乙醇氧化得乙醛，再氧化得乙酸；乙酸与乙醇酯化得乙酸乙酯。每一步把试剂条件和官能团变化配成对。"],"visualSteps":["醇与酚","烯烃加成","醇/醛氧化","羧酸酯化","条件与现象"]},{"label":"醛、酮、羧酸、酯","rule":"醛易氧化并能还原银氨溶液/新制Cu(OH)₂；羧酸显酸性并酯化；酯可水解。","examples":["【示范：乙烯—乙醇—乙醛—乙酸—酯】乙烯加成得乙醇；乙醇氧化得乙醛，再氧化得乙酸；乙酸与乙醇酯化得乙酸乙酯。每一步把试剂条件和官能团变化配成对。"],"visualSteps":["醛、酮、羧酸、酯","烯烃加成","醇/醛氧化","羧酸酯化","条件与现象"]},{"label":"胺/酰胺与生物大分子","rule":"按教材掌握碱性、成盐、水解及蛋白质、糖类、油脂的基础性质，不展开超出课标的反应机理。","examples":["【示范：乙烯—乙醇—乙醛—乙酸—酯】乙烯加成得乙醇；乙醇氧化得乙醛，再氧化得乙酸；乙酸与乙醇酯化得乙酸乙酯。每一步把试剂条件和官能团变化配成对。"],"visualSteps":["胺/酰胺与生物大分子","烯烃加成","醇/醛氧化","羧酸酯化","条件与现象"]}]},{"title":"反应类型与条件","summary":"看到条件要反向联想到官能团变化。","items":[{"label":"取代","rule":"一个原子或基团被另一个原子或基团替换；常见实例有烷烃卤代、卤代烃水解和苯环取代。酯化、聚合等按教材给出的独立反应类型判断。","examples":["【示范：溴乙烷的水解和消去】溴乙烷在NaOH水溶液、加热条件下水解得乙醇；在NaOH醇溶液、加热条件下消去得乙烯。同一底物因条件不同发生不同反应。"],"visualSteps":["取代","读条件","判断取代/消去","画断键成键","核对产物"]},{"label":"加成与消去","rule":"加成使不饱和度降低，消去形成不饱和键；水/醇溶液、温度等条件是关键信号。","examples":["【示范：溴乙烷的水解和消去】溴乙烷在NaOH水溶液、加热条件下水解得乙醇；在NaOH醇溶液、加热条件下消去得乙烯。同一底物因条件不同发生不同反应。"],"visualSteps":["加成与消去","读条件","判断取代/消去","画断键成键","核对产物"]},{"label":"氧化与还原","rule":"跟踪C与O/H的关系：加O或去H常为氧化，加H或去O常为还原；最终以化合价/结构变化判断。","examples":["【示范：溴乙烷的水解和消去】溴乙烷在NaOH水溶液、加热条件下水解得乙醇；在NaOH醇溶液、加热条件下消去得乙烯。同一底物因条件不同发生不同反应。"],"visualSteps":["氧化与还原","读条件","判断取代/消去","画断键成键","核对产物"]},{"label":"聚合","rule":"加聚通常打开不饱和键不产生小分子；缩聚由多官能团单体反应并常放出小分子。","examples":["【示范：溴乙烷的水解和消去】溴乙烷在NaOH水溶液、加热条件下水解得乙醇；在NaOH醇溶液、加热条件下消去得乙烯。同一底物因条件不同发生不同反应。"],"visualSteps":["聚合","读条件","判断取代/消去","画断键成键","核对产物"]}]},{"title":"同分异构体系统枚举","summary":"写完要用分子式和条件双重核对。","items":[{"label":"第一步：确定类别","rule":"根据官能团、与试剂反应、核磁信号等题给条件确定可能类别。","examples":["【示范：C₄H₈O₂且能放CO₂的异构体】与NaHCO₃放CO₂先锁定羧基；再枚举满足总碳数的不同碳链和羧基位置，利用对称性去重；逐个回算分子式和题给反应量。"],"visualSteps":["第一步：确定类别","确定官能团类别","枚举碳链","移动位置并去重","条件筛选"]},{"label":"第二步：碳链异构","rule":"先画不同碳骨架，注意对称性，避免旋转/翻转造成重复。","examples":["【示范：C₄H₈O₂且能放CO₂的异构体】与NaHCO₃放CO₂先锁定羧基；再枚举满足总碳数的不同碳链和羧基位置，利用对称性去重；逐个回算分子式和题给反应量。"],"visualSteps":["第二步：碳链异构","确定官能团类别","枚举碳链","移动位置并去重","条件筛选"]},{"label":"第三步：位置异构","rule":"在每个骨架上移动官能团或多键，排除等价位置。","examples":["【示范：C₄H₈O₂且能放CO₂的异构体】与NaHCO₃放CO₂先锁定羧基；再枚举满足总碳数的不同碳链和羧基位置，利用对称性去重；逐个回算分子式和题给反应量。"],"visualSteps":["第三步：位置异构","确定官能团类别","枚举碳链","移动位置并去重","条件筛选"]},{"label":"第四步：条件筛选","rule":"用取代产物数、反应消耗量、苯环取代关系等逐条筛选并回算分子式。","examples":["【示范：C₄H₈O₂且能放CO₂的异构体】与NaHCO₃放CO₂先锁定羧基；再枚举满足总碳数的不同碳链和羧基位置，利用对称性去重；逐个回算分子式和题给反应量。"],"visualSteps":["第四步：条件筛选","确定官能团类别","枚举碳链","移动位置并去重","条件筛选"]}]},{"title":"合成路线与实验","summary":"正推看能做什么，逆推看目标从哪来。","items":[{"label":"逆推目标官能团","rule":"目标若是酯，前一步可考虑酸+醇；若是醇，可由卤代烃水解或羰基还原等课内路线得到。","examples":["【示范：由乙烯合成乙二酸乙二酯】先逆推目标酯来自乙二酸和乙二醇；再正推乙烯经加成/氧化等课内路线得到相应双官能团物质。每一步同时核对碳数、官能团、反应条件和实验分离。"],"visualSteps":["逆推目标官能团","逆推目标官能团","正推可行路线","跟踪碳数","考虑条件与纯化"]},{"label":"保护与选择性信息","rule":"若多官能团互相干扰，题目通常给保护/转化新信息；严格按信息迁移，不自行引入大学试剂。","examples":["【示范：由乙烯合成乙二酸乙二酯】先逆推目标酯来自乙二酸和乙二醇；再正推乙烯经加成/氧化等课内路线得到相应双官能团物质。每一步同时核对碳数、官能团、反应条件和实验分离。"],"visualSteps":["保护与选择性信息","逆推目标官能团","正推可行路线","跟踪碳数","考虑条件与纯化"]},{"label":"跟踪碳数","rule":"每一步检查碳骨架是否增长、缩短、成环或断裂，避免只盯官能团。","examples":["【示范：由乙烯合成乙二酸乙二酯】先逆推目标酯来自乙二酸和乙二醇；再正推乙烯经加成/氧化等课内路线得到相应双官能团物质。每一步同时核对碳数、官能团、反应条件和实验分离。"],"visualSteps":["跟踪碳数","逆推目标官能团","正推可行路线","跟踪碳数","考虑条件与纯化"]},{"label":"有机实验","rule":"关注试剂用量、加热方式、冷凝回流、萃取洗涤、蒸馏结晶和产率纯化。","examples":["【示范：由乙烯合成乙二酸乙二酯】先逆推目标酯来自乙二酸和乙二醇；再正推乙烯经加成/氧化等课内路线得到相应双官能团物质。每一步同时核对碳数、官能团、反应条件和实验分离。"],"visualSteps":["有机实验","逆推目标官能团","正推可行路线","跟踪碳数","考虑条件与纯化"]}]}],"workedExamples":[{"substance":"读CH₃CH(OH)CH₂CHO","path":"先找最长含主要官能团碳链，圈羟基和醛基，编号使醛基位次最低；由结构式核分子式和不饱和度，再按命名规则组织名称。","labels":["识别碳骨架","圈官能团","编号命名","分子式复核"]},{"substance":"乙烯—乙醇—乙醛—乙酸—酯","path":"乙烯加成得乙醇；乙醇氧化得乙醛，再氧化得乙酸；乙酸与乙醇酯化得乙酸乙酯。每一步把试剂条件和官能团变化配成对。","labels":["烯烃加成","醇/醛氧化","羧酸酯化","条件与现象"]},{"substance":"溴乙烷的水解和消去","path":"溴乙烷在NaOH水溶液、加热条件下水解得乙醇；在NaOH醇溶液、加热条件下消去得乙烯。同一底物因条件不同发生不同反应。","labels":["读条件","判断取代/消去","画断键成键","核对产物"]},{"substance":"C₄H₈O₂且能放CO₂的异构体","path":"与NaHCO₃放CO₂先锁定羧基；再枚举满足总碳数的不同碳链和羧基位置，利用对称性去重；逐个回算分子式和题给反应量。","labels":["确定官能团类别","枚举碳链","移动位置并去重","条件筛选"]},{"substance":"由乙烯合成乙二酸乙二酯","path":"先逆推目标酯来自乙二酸和乙二醇；再正推乙烯经加成/氧化等课内路线得到相应双官能团物质。每一步同时核对碳数、官能团、反应条件和实验分离。","labels":["逆推目标官能团","正推可行路线","跟踪碳数","考虑条件与纯化"]},{"substance":"乙醇到乙酸乙酯","path":"乙醇先氧化可得乙醛，再氧化得乙酸；乙酸与乙醇在浓硫酸、加热条件下酯化生成乙酸乙酯和水。每一步标官能团：羟基→醛基→羧基→酯基。","labels":["官能团追踪","氧化","酯化","条件"]},{"substance":"限定同分异构体","path":"先由分子式和“能与NaHCO₃放CO₂”锁定羧基，再枚举满足碳数的碳骨架和羧基位置，利用等效位置去重，最后逐个核对分子式和题给其他现象。","labels":["先定官能团","枚举碳链","位置去重","条件复核"]}],"checkpoints":["我能先圈官能团再判断性质。","我能由反应条件反推官能团变化。","我会按碳链—位置—类别系统写同分异构体。","我能在合成路线中同步追踪碳数和官能团。"],"scopeNote":"只保留福建高中化学范围内必须理解和能够迁移的内容；更高学段理论、竞赛机理和旧选考制度内容不进入学生卡。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版教材顺序校准；考法与表述参考G盘《2024版化学步步高一轮复习·新教材苏教版》及福建高考班校对资料。"}$card$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H3_ORGANIC' and skill_id = 'H3_ORGANIC';

update public.chem_knowledge_cards
set review_status = 'retired', updated_at = now()
where id in ('CARD_PERIODIC_01', 'CARD_REDOX_01', 'CARD_ION_01', 'CARD_H2_RATE', 'CARD_H3_EQ');

do $verify$
declare
  formal_skill_count integer;
  complete_card_count integer;
  approved_duplicate_count integer;
begin
  select count(*) into formal_skill_count
  from public.chem_skills
  where active = true and grade_band in ('高一', '高二', '高三');

  select count(*) into complete_card_count
  from public.chem_knowledge_cards c
  join public.chem_skills s on s.id = c.skill_id
  where s.active = true
    and s.grade_band in ('高一', '高二', '高三')
    and c.id = 'KC_' || c.skill_id
    and c.review_status = 'approved'
    and coalesce((c.structured_content->>'version')::integer, 0) >= 2
    and jsonb_array_length(coalesce(c.structured_content->'overview', '[]'::jsonb)) >= 4
    and jsonb_array_length(coalesce(c.structured_content->'sections', '[]'::jsonb)) >= 4
    and jsonb_array_length(coalesce(c.structured_content->'workedExamples', '[]'::jsonb)) >= 2
    and jsonb_array_length(coalesce(c.structured_content->'checkpoints', '[]'::jsonb)) >= 4
    and not exists (
      select 1
      from jsonb_array_elements(c.structured_content->'sections') section_value
      cross join lateral jsonb_array_elements(section_value->'items') item_value
      where jsonb_array_length(coalesce(item_value->'examples', '[]'::jsonb)) = 0
    );

  select count(*) into approved_duplicate_count
  from (
    select c.skill_id
    from public.chem_knowledge_cards c
    join public.chem_skills s on s.id = c.skill_id
    where s.active = true
      and s.grade_band in ('高一', '高二', '高三')
      and c.review_status = 'approved'
    group by c.skill_id
    having count(*) <> 1
  ) duplicates;

  if formal_skill_count <> 27 then
    raise exception 'Expected 27 active H1-H3 skills, found %', formal_skill_count;
  end if;
  if complete_card_count <> 27 then
    raise exception 'Expected 27 complete zero-forgetting cards, found %', complete_card_count;
  end if;
  if approved_duplicate_count <> 0 then
    raise exception 'Approved knowledge-card duplicates remain for % skills', approved_duplicate_count;
  end if;
end
$verify$;
